    "score": "9.6",
    "category": "双男主",
    "abstract": "【实体书《遇卿》已上架，全平台可购！】【双男主＋无限流爽文＋相爱相杀+BOSS攻+疯子受+双强双洁1V1】\n\n三年前，《天堂的阶梯》突然降临，一批又一批的人被拉入逃生游戏，被迫直播，承受着观众的随意摆布和滔天恶评。\n\n虞卿长发柔软，长相单纯，大眼睛水汪汪的眨着，面对面前狞笑着骗他进屋的鬼婆婆，乖巧点头：“好。”\n\n观众：【……无脑，主播下一秒就要被鬼婆婆毒死了。】\n\n直播人数骤减，然后，噗呲——\n\n虞卿把鬼婆婆的头按进了餐盘里，笑问：“大家想看鬼做吃播吗？”\n\n观众：【？？？】\n\n虞卿：“我为大家谋福利，播点不一样的。”\n\n观众：【！！！】\n\n自此，事情变得奇怪起来。\n\n系统：【主播虞卿诛杀NPC，违反规则，生命值归零！】\n\n观众疯狂打赏生命值。\n\n【我老婆没错，一定是规则有问题！】\n\n【系统要他三更死，爷偏供他得永生！】\n\n其他主播：“我们的观众不是这样的！”\n\n然后，虞卿毫不费力的活了下来，主播积分越来越多，通关操作越来越浪，但……\n\n观众想看的为什么是：宝贝，抱住BOSS，把他亲懵？？！",
