    "author": "君莫管",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/9f03ff4b3ce3d7a3fc4e245e2935dadf~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358534&x-signature=oxlY31hqyoJLV4GcM86zobBV6ME%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【双男主+无限流+规则怪谈+1V1+双洁+甜宠无虐+体型差+攻不切片（有马甲）+微恐怖+HE】\n\n【疯批阴湿恋爱脑BOSS攻VS漂亮爱哭钓而不自知受】\n\n【攻身高195X受身高175】\n\n攻有马甲且多，受与攻马甲有亲密接触是在已经确认是攻的前提下（正文后续会解释）\n\n胆小的余诺忽然被拉进惊悚恐怖游戏之中，只有通关才能活着离开。\n\n他玩了一场真人版狼人杀，在玩狼人杀的同时，又必须进行角色扮演。\n\n【角色卡：太子妃，你是太子爷的未婚妻，你无比迷恋着太子爷，是没有了他就无法生存的菟丝草。】\n\n余诺看见了眼身旁那位抽中太子爷角色的疯批满级大佬，很没骨气地紧紧抱着他，哭着说道：“我怕。”\n\n苏烬夜捧着他哭红的脸，声音温柔却带着偏执道：“别怕，我会带你赢的。”\n\n余诺确实赢了，可苏烬夜却消失了。\n\n后来，余诺发现副本中总是追着他跑，喜欢喊他老婆的疯批BOSS竟然就是苏烬夜。\n\n他那个现实中死了六年，却始终想不起脸的未婚夫，也是苏烬夜。\n\n就连一直陪伴着他的系统，也是苏烬夜的一部分。\n\n于是他一遍遍的进入副本，拉着苏烬夜的手，坚定道：“我带你回家。”\n\n苏烬夜却反手一把将余诺拉进黑暗之中，语气癫狂道：“你现在跑不掉了...”",
