    "score": "8.4",
    "category": "双男主",
    "abstract": "(刚出评分，后续会涨)\n\n[无限流+双洁+双男主＋恋爱脑]\n\n段清有个查不到任何信息的男朋友\n\n突然进入副本的他，发现一个NPC和他的男朋友长的特别相似。\n\n一开始他并不在意，或许只是巧合呢，但是他发现，这个NPC好像意外的黏他。\n\n后来，他确认这就是他男朋友，且只要男朋友在的地方，好像那些诡异都不敢接近他。\n\n就算他刻意挑衅那些诡异，它们都不敢对他做什么。\n\n他的男朋友不简单啊。\n\n至此，段清为了完成气死人任务，开始自己的“作”路，别人不敢做的事，他上，出现什么事，有他男朋友顶着。别人不敢碰到东西，他碰，顺带再挑衅一下玩家，因为有他男朋友顶着。\n\n看的其他人心里直痒痒，心里都在控诉副本诡异的不公平！\n\n很快，段清就成了绝大多数玩家心中的敌人。\n\n副本诡异:“要打你们打啊，你们要是能打过他老公，我直接把副本系统打晕送给你！”\n\n邪神一次意外出现在了一个小男孩的身边，从那以后就一直陪着他，理所应当的成为了他男朋友。\n\n得知自己的宝宝来到了他的地盘，自己肯定是要往死里宠。\n\n“宝宝，那个诡异好可怕，吓到我了！”\n\n“没事，我现在就让他消失。”\n\n诡异：大人！我做错什么了！",
