    "score": "8.9",
    "category": "双男主",
    "abstract": "［正文完］【诡异攻X满级玩家受】【无限流+爽文+双强+双男主+掉马+直播+副本】\n\n表面高冷实际黑心嘴贫大佬受X表面疯批实际脑子有病人机忠犬邪神攻\n\n季随X魏池安\n\n*\n\n季随，没有异能，但是第一玩家，开了个小号还一年时间迅速晋升诡异恐怖榜榜首。\n\n坑过玩家骗过诡异，炸过系统挑衅过管理员，但眼下，美好的养老生活被打破，季随被迫重回副本。\n\n不过有谁能解释一下，为什么他身边会多一个像人工智障的东西？\n\n*\n\n世界一区自从两年前J的突然消失，彻底变为玩家眼里的混乱地带，听说里面住了一群神经病，诡异与玩家鱼龙混杂。\n\n季随得知此消息，脸上的笑僵了又僵。\n\n……他出去一趟，家里几个怎么打起来了？\n\n*\n\n季随扮演“内鬼”身份正上头的时候，一次失误。\n\n【您已死亡】\n\n全服都在缅怀“绝对幸运”玩家的陨落，而季随躲在角落，默默切换账号“活”了过来。\n\n可令他万万没想到的是，他被玩家目击了。\n\n弹幕：［……说出来各位可能不信，我早逝的亡妻好像活了］\n\n［我们主播怎么跟玩家排行榜第一撞脸了？］［神特么撞脸！你瞎啊？那是同一个人！！］",
