    "abstract": "【双男主+主受+无限流+he】评分正在缓慢上升中～\n\n谁能有封晏倒霉，好不容易通关恐怖游戏，回到现实世界。\n\n又被亲生父母在破旧的小房子里找到带回豪门，以为要过豪门贵族生活了。\n\n谁曾想，没学历，家里人硬是捐了几栋楼，把他送进学校，成了一个20岁“高龄”的学生！\n\n成功过上了早上6点起，晚上10点回的“幸福”生活。\n\n不过还是有好处的，遇见了一个长得贼对他胃口的帅哥，开开心心的谈起了恋爱。\n\n就是这恐怖游戏怎么在现实世界上线了啊？什么叫做内测结束，游戏上线？\n\n游戏里的怪物不要出现在现实世界啊！！！\n\n不对，他这对象怎么还是特管局的成员？\n\n好好好，一个个的都不让他过普通的躺平生活是吧？\n\n【光赎游戏】已强制接入。\n\n此地许诺光明与救赎，许诺万事如愿。\n\n但所有馈赠，仅留给活下来的人。\n\n力量、权位、财富、永生，皆是幸存者的奖励。\n\n胆敢止步者，将永坠黑暗。\n\n光赎系统在这里诚挚祝您……游戏愉快。\n\n求生者们，活下来吧……",
