    "book_id": "7581690172413070360",
    "book_name": "疯批美人配邪神，惊悚暧昧上大分",
    "author": "桃花坠西湖",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o417bc6c22a69e07ce1255fcd0d35fdd6~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358534&x-signature=eolOA2%2Bq3eh7FEt4sh8pDoG%2Bqkk%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【已完结】【情感缺失的吸血鬼玩家受x引导型BOSS攻】【双男主+无限流爽文+相爱相杀+疯子受+BOSS攻+双强双洁+1V1HE】\n\n恐怖游戏《地狱十九层》迎来了一位的疯子。\n\n惑钰，白发红瞳，长相很乖，是一只因不是纯血，身体承受不住日渐强大力量的病弱吸血鬼美人。\n\n面对身材矮小，满脸脓包的新郎，也只是优先询问道：“你是我老公吗？”\n\n观众：【……他有病吧？来这找老公，恋爱脑晚期了。】\n\n下一刻，噗——！\n\n惑钰捏爆了新郎的头，看向镜头，笑的温良：“要不要和我赌一场？”\n\n观众：【？？？】\n\n惑钰：“赌我能把他们都杀了。”\n\n观众开始兴奋，疯狂打赏助力。\n\n自此，惑钰直播间的画风变的奇怪起来。\n\n系统：【请不要总对你的队友抱有杀意。】\n\n【请不要随意击杀副本NPC。】\n\n观众：【主播不能死，我高低要看看这渣男到底是谁！】\n\n直到，男人虔诚的跪在惑钰脚边，虔诚道：“非要这样吗？我可以解释的。”\n\n观众：【！！！】\n\n首先恭喜惑钰找到了他的老公，但……\n\n这能对嘛，这是BOSS啊？！",
