    "abstract": "[双男主+规则无限流+甜宠爽文]\n\n攻非人，恐怖副本诡物大佬，病娇疯批爱脑，不喜慎入\n\n夏佑毕业旅游的路上莫名被拉入了诡的世界。在无限恐怖副本之中，他凭借着祖传的剪纸术、强大的心脏和…呃…还有恋爱脑诡物大佬的青睐下，在诡的世界中一步一步变强，爱情事业双丰收。\n\n病娇恋爱脑大佬语录：“这个人好暖，好喜欢，好像要”“说了要保护我，那就一辈子留在我身边，不许离开哦！！”",
