    "book_id": "7194743568718629922",
    "book_name": "无限流：他很美，可惜长了嘴",
    "author": "双影照清浔",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1ee112cdc928e839619b4dbf68801157~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358534&x-signature=Na6MNxc26JPJMM2InneevvGuq6Y%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【双男主＋无限流＋灵异＋沙雕＋HE】\n\n乔煜生前有个男朋友，谈的那叫一个天崩地裂人尽皆知，山无陵、天地合都不敢与君绝的那种。\n\n他们挺过了七年之痒，在即将面见家长顺便步入婚姻殿堂的时候，他那么大个男朋友突然没了！\n\n就是字面上的没了，活不见人死不见尸的那种。\n\n乔煜面对外界的嘲讽依旧该吃吃该喝喝该睡睡，然后一年后被车给撞死了。\n\n乔煜终于信了，秀恩爱、死得快。\n\n也不知道过了多久，他一觉醒来，突然变成了‘乔郁’。\n\n可能重启的方式有些不对劲儿，他被莫名其妙的拉入了一场逃生直播中，还是真的会死人的那种。\n\n接着......他那个成为了失踪人口的男朋友，正好端端的站在他面前，还恬不知耻的想要拉他的小手。\n\n乔煜：远方传来风笛～\n\n**\n\n直播间经历boss暴走，乔郁抠出自己的眼珠子顶着一脸血把boss吓得落荒而逃。\n\n一只手突然拉过正叉腰嚣张大笑的乔郁：“别闹了，我心脏受不了。”\n\n乔郁立马把眼珠子安了回去：“那我给你揉揉？”\n\n“来，谁不揉谁孙子！”\n\n乔郁：“爷爷。”\n\n“......闭嘴！”\n\n要钱不要命的皮皮Svs普天之下除了他和乔郁外一切皆垃圾G",
