    "score": "9.0",
    "category": "双男主",
    "abstract": "【双男主+无限流】（自割大腿肉作品！！）\n\n齐雾原本觉得以为自己是一名普通人，直到意外降临在自己身上后，他才发现，普通人没有他这么倒霉！！\n\n正式成为死亡游戏npc扮演员工之后：\n\n齐雾：“为什么那边有个男人一直在看我？”\n\n系统：“他是玩家，估计是把你当成重要npc了。”\n\n齐雾：“噢噢。”\n\n过了一会儿……\n\n齐雾：“为什么他凑的越来越近了啊喂！！”\n\n某男人：悄悄靠近，一把抢走齐雾。\n\n齐雾：“啊！”（被偷走）\n\n系统：“放开宿主啊啊啊！！！”\n\n（排雷：非传统好人夫夫，有高要求道德标准的宝贝慎入）",
