    "score": "0",
    "category": "双男主",
    "abstract": "【双男主+无限流+疯批BOSS受+扮猪吃虎白切黑攻+狼人杀+大逃杀+双强+1v1+日更】通关999关后，榜一大佬肆成书拒绝了管理员给的财富和权力。\n\n“我要当BOSS。”\n\n于是第三关的新人玩家们，迎来了史上最离谱的新手副本——\n\n狼人杀+大逃杀+吸血鬼城堡，BOSS本人亲自下场砍人。\n\n13个玩家里混进了5个高等级大佬，各个憋着坏水想见榜一真容。\n\n肆成书拎着锯子笑眯眯：“欢迎光临，祝你们死得开心。”\n\n只有那个2级新人，看他的眼神不太对劲。\n\n“我好像……在哪里见过你。”\n\n【疯批美人BOSS受 × 身份成谜新人攻】\n\n第一个副本:狼人杀➕大逃杀已完结！\n\n第二个副本:1v7 擂台赛已完结！\n\n第三个副本：深海疗养院已完结！\n\n第四个副本：主神争夺正在进行中！",
