    "author": "中华绿豆酥",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2od74cae0cd9a1435c6753b588faeb0895~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358534&x-signature=JKpBOH83GgYo%2BGnXBl8mHTa8h68%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【无限流+民俗怪谈+双男主+破镜重圆】\n\n【活人微死感社畜x傲慢杀伐果断诡神】\n\n符默高考之后，怪谈在他所在的世界降临了。\n\n好消息是，他去世一年多的父母重新回到了他的身边。\n\n他们身体健康，像过去一样爱他。除了性子变得急躁些，外表上看不出任何问题。\n\n坏消息是，他的竹马失踪了。\n\n不，也不能说失踪。毕竟他已经死了很多年。\n\n符默一直等待着，期盼他的竹马重新出现。\n\n【即使死亡将我们分离，我依然爱你】",
