    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/c0a1656a5abe4030f67223493ca7c6d1~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358534&x-signature=HdeimwFqna5wjCVEJbFQjLudguc%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "诡异+迪化脑补+扮演+双男主+规则怪谈\n\n陈右时是个懦弱的十八线演员，为了生机，他一口气接了三个人设不同的剧本。\n\n在偶像剧里他要扮演拜倒在女主魅力下的男n号，一个多情风流的海王。\n\n在悬疑剧里他要扮演最后出场的反派，一个冷静高智商的罪犯。\n\n在恐怖片里他要扮演……呃，一只鬼。\n\n有点难度。\n\n为了更好入戏，陈右时天天抱着道具睡觉。\n\n结果误闯诡异界，他不小心出了意外。\n\n一阵头脑重启后，他绝望发现自己分不清自己的身份了。\n\n他是谁？\n\n他是玩转情场的海王，是冷酷无情的杀手？\n\n还是诡异里的大诡？",
