    "abstract": "39先生谢德VS魏砚池【双男主+无限流+脑补迪化】\n\n摆烂的炮灰谢德天降了一个系统，原本以为可以从此走上龙傲天的道路，一路高歌，结果这个系统是个被废弃的废物系统，一问三没有。\n\n商城？没有。\n\n奖励？没有。\n\n任务？没有。\n\n得，谢德表示自己继续摆烂吧。\n\n结果系统不干，它虽然是个小废物，但谁说废物就不能有进取心？\n\n于是废物系统带着炮灰宿主勇闯任务流赛道。\n\n至于是什么任务，这就别管了。",
