    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1df42baa59652544fda4eb6940f2df6f~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358536&x-signature=ZYOn58yA%2BSlnGpEMgHT4DtWFgPk%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【双男主+双强+群像+无限流+惊悚直播+副本BOSS+满级大佬】\n\n（为了受甘愿做牛马攻X为了攻不愿做牛马受）\n\n宋九息出车祸被拉到一个惊悚世界。\n\n众多玩家都觉得他病恹恹的活不过第一个副本。\n\n谁知他在副本里砍瓜切菜的，像是回老家一样熟练。\n\n副本BOSS看到他就想绕道走，他打鬼是真的狠。\n\n玩家看到他就求他别乱走，害怕他不小心把BOSS秒了。\n\n通关太快是拿不到额外奖励的！！！",
