    "book_id": "7184231941900602400",
    "book_name": "穿进恐怖副本，高冷大神来贴贴",
    "author": "山不语十二",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/f74ad56780e664fb98c32452dc703738~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358536&x-signature=epUT%2Bp0TmYnxqVdp1j2VtdtG6kM%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【双强+双男主+无限流闯关+微恐爽文+甜宠】\n\n五人主角团热血闯关，性格鲜明，结局HE\n\n沈言译，华夏仅存的传承道士，实力超群\n\n某天，他踏进了一栋很奇怪的酒店，在这里找到了失踪两年的恋人。\n\n可是恋人莫名失忆，已经全然忘记自己。\n\n沈言译动了动手腕，望向男人的眼神满是兴味。\n\n段牧樊被看的呼吸一滞，内心莫名悸动。\n\n糟糕！难道是心动的感觉？\n\n——\n\n众闯关选手：夭寿啦！段大佬又暴走杀NPC啦！\n\n沈言译：（皱眉）把刀放下。\n\n段牧梵：（下意识放下刀）言言我错了。\n\n众人：？？？\n\n奔走相告！新来的帅哥是段大佬的人形镇定剂！",
