    "abstract": "（刚开分，后面会涨的）【双男主+无限流+微恐+一见钟情+天作之合+双强】（有副CP）\n\n战斗力超强偏执受vs对老婆占有欲爆棚邪神攻\n\n桑瑾的男朋友死了，所有人都这样告诉他\n\n但是他不相信，他感觉他的男朋友没有死，\n\n桑瑾每天都在找他男朋友还活着的痕迹\n\n终于有一天，惊悚游戏《神愿》找上了他\n\n在副本中，他终于找到了他的男朋友，只是，男朋友好像有点不正常\n\n但没关系，是他男朋友就好\n\n——\n\n祁渊看上了一个人类，这个人类好可爱，好像他命中注定的老婆\n\n结果老婆说自己是他男朋友，那真是太好了，既然是男朋友的话，那就要永远和他在一起哦\n\n避雷：不喜勿喷，直接退出，好书千千万，不喜直接换",
