    "author": "二两闲",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1928bf94f5d5757033755789bc0025e8~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358536&x-signature=0oSV85rKdr0pCp4VOd5ogPaGU2M%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【双男主+水仙+强强+无限流+微群像+1v1+直播】\n\n宁朔被拉进了一个恐怖剧本杀系统。\n\n涂着诡彩面具的小丑笑嘻嘻：【请给自己取个代号。】\n\n宁朔略加思索：“宁半仙。”\n\n观众们想这什么鬼名字，他这是想在恐怖游戏里忽悠那帮鬼怪吗？\n\n直到他们在直播间里，看到宁朔神神叨叨地对一个鬼怪说，你今夜子时，最多不过半个时辰，必有血光之灾。\n\n观众等着看他笑话，结果凌晨十二点，秒针刚刚归零，一把剑直接穿透鬼怪的咽喉。\n\n一身古装打扮、跟宁朔长相几乎一样的男子剑指宁朔，挑眉道：“你也是怪物？”\n\n宁朔笑吟吟：“或许，我是另一个你。”\n\n……\n\n见到宁望的第一眼，宁朔就知道他跟这个人拥有世上最亲近的关系，近到他们使用过同一个名字——\n\n谢宁。\n\n--排雷--\n\n1.受很爱中二，身体不好，不喜勿入；\n\n2.没有受了点小委屈就要人性命的情节，一切为剧情服务，不喜勿入；\n\n3.双男主，有副cp，没有哭包奶受，因为作者喜欢双强，不喜勿入；\n\n4.有直播弹幕，弹幕内容不代表作者三观，角色思想也不代表作者三观，不喜勿入。",
