    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/6f7171a4909e8fc3b018007ca634eeca~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358537&x-signature=dtCtVI%2F98OqIAMPrYYjmRY%2FmZtc%3D",
    "score": "8.8",
    "category": "双男主",
    "abstract": "【双洁1V1】【阴暗疯批、双向救赎】【主攻视角，副受视角】\n\n原本以为死亡就能彻底解脱的季延，在死后被拉入了副本世界中。\n\n但他并不想活着，为了能彻底死去，季延遵循系统的安排，无情的击杀副本中的玩家。\n\n第一个副本，他无情的击杀玩家。\n\n第二个副本，有个玩家迎着大火扑过来救了他。\n\n第三个副本，他又遇到了那个玩家，他用自己从他手中夺来的武器跟他打了一架，他，成功引起了他的兴趣，所以他救了他一次。\n\n第四个副本……\n\n第五个副本……\n\n后来，他发现，自己在很小的时候就认识了这个玩家……\n\n————\n\n季延：“想要通关副本吗？可以，杀了我。”\n\n宁轻回：“说的好听，是死亡，说难听了，就是逃避。”",
