    "book_id": "7411919928078371865",
    "book_name": "开局一张结婚证，邪神血条随便用",
    "author": "四两大米饭",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/4e6367e7064a4b2c37370cd03736d89c~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358537&x-signature=7kAVTnmpyDC0PftEU4iHVmNVEj4%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【无限流+双男主+强强+冷静理智美人受x吐了又吃真香邪神攻】1V1双洁\n\n把刀刃对准脖颈时，黎闲没有害怕。\n\n再次睁眼，进入九死一生的无限世界时，黎闲没有惊讶。\n\n发现自己要扮演的角色是新娘时，黎闲疑惑了一瞬，随后坦然接受。\n\n但当他听到自己的技能时，到底还是绷不住了——\n\n原地结婚是什么鬼啊？！难不成诡怪世界也有婚姻制度？\n\n于是他随便找了个人试验一下，结果随着技能效果的触发，他的血条直接变成了“？？？”\n\n莫名其妙被骗婚的季斜：“我堂堂邪神怎么会被这种技能束缚...我要离婚！！”\n\n后来的季斜：“你就算不会死也犯不着次次把自己弄一身伤吧...啧啧啧，看着就疼。”\n\n再后来，季斜把黎闲绑在了裤腰带上：“什么离婚？我说过吗？一定是你记错了。”",
