    "book_id": "7463813779701107737",
    "book_name": "无限，我们队全员疯批",
    "author": "unlanda",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o041400a8f8ce6032a789d23ecbf891a2~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358537&x-signature=XRAFG%2F%2BIZIQoGJQfsuYlbitUtII%3D",
    "score": "8.4",
    "category": "双男主",
    "abstract": "（双男主+疯批+群像+微沙雕+斯文败类攻vs智慧但喜欢找刺激受）病娇警告\n\n莫名其妙进入了无限流游戏?\n\n莫慌，专业对口了，墨辞可是一个疯批。\n\n后来，遇到了几个志同道合同样疯批的队友，那更是在副本中如鱼得水，把副本嚯嚯得所剩无几。\n\n只不过，墨辞看着缠着他不肯放的副本BOSS，有些沉默。\n\n这位副本boss你能不能好好做boss？不要只缠着我一个人啊喂。\n\n副本boss越来越过分，后来直接堂而皇之的入住墨辞的住所。\n\n墨辞:这能对吗？\n\n好在某个人过于不要脸，成功抱得美人归。\n\n于是五个疯批一起炸副本。\n\n然而等众人过了n个副本后，却猛然发现，这一切都是一场阴谋……\n\n缺失的记忆中到底隐瞒着什么？\n\n这其中又是谁的手笔。\n\n兜兜转转，越查越心惊，一切指向最不可能的人。",
