    "author": "万里星火",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o3f7d07b26a9e40edd00a6f23b1310abe~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358537&x-signature=Gx7ZqfAZm6EcHRQcMN%2FWKm7HJLE%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【双男主+无限流+惊悚游戏】夏黎是惊悚游戏的大boss，因为没有人能闯到最终关，他这个大boss虽然在岗，但是没有工作可以做，每天都很无聊，于是就混入了人类中，成为了闯关者中的一员。\n\n一个新加入且晋级很快的玩家裴司珩引起了夏黎的注意。\n\n直觉告诉他，这个裴司珩有些与众不同，他有可能闯入最后一关，成为自己最大的威胁。\n\n所以夏黎决定以一个普通玩家的身份潜藏在裴司珩身边。\n\n藏着藏着，夏黎就发现这个裴司珩看他的眼神有些不对劲了。\n\n终于，在裴司珩把他壁咚在墙边的时候，夏黎悟了。\n\n这个裴司珩确实是每天都在想怎么弄死他。\n\n只不过……\n\n这个弄死是另一个意思。\n\n夏黎：我一个惊悚游戏的大boss，被一个玩家扑倒，我不要面子的？\n\n裴司珩：换个位置也行，你扑我？\n\n夏黎：……",
