    "book_name": "惊悚登录：别惹那个恋爱脑邪神！",
    "author": "礼拜天是只狗",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o588907c0a087ed4d43d0afd7dfdc2d5f~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358539&x-signature=y6X4Q0HE%2BasWIjItDkgT6yspjWM%3D",
    "score": "0",
    "category": "双男主",
    "abstract": "【双男主+无限流+双强成长流+惊悚+克苏鲁】\n\n1v1 双洁，偏传统无限，没有直播。\n\n已完成副本：寿宁第一医院\n\n奉灵荒村\n\n副本连载中：昌禄二中\n\n表面酷哥实际内心戏丰富成长受vs前期相爱相杀后期老婆就是最牛的忠犬邪神攻\n\n莫未乾好不容易拥有个幸福的家，突然不知道哪天起\n\n可爱的弟弟妹妹们相继失踪。\n\n找寻无果的莫未乾卡bug进入了怨罪游戏\n\n查明真相后的莫未乾怒了\n\n拆了副本吸收能量还不算\n\n诡怪有一个杀一个，吓得众诡抱头鼠窜\n\n杀穿副本的莫未乾看着角落里瑟瑟发抖的系统\n\n和拼死活下去刀尖舔血的众玩家：\n\n他们要举报！这里有狗东西开挂！！\n\n莫未乾提着刀正要给造谣的众诡一个痛快\n\n漫天的夏塔克鸟带着地底深渊的白霜和硝石降临副本\n\n虚空中一个异瞳银发高大身影踏空而出\n\n生死间大起大落的众诡众人：呼，这次该轮到你了莫未乾\n\n人太嚣张是要不得的！！\n\n没空理会蝼蚁的邪神径直走向莫未乾\n\n轻轻将人圈入怀中一个柔情似水道：\n\n宝贝，今天晚餐你想吃什么？\n\n下地狱的众诡们满头问号？？？\n\n终于回过神的众诡：\n\n你清高，你了不起，你哄老婆用我们的命？！",
