    "author": "自由的花菇子",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/ffc59bbdd254f8283e28a76195542a0b~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358539&x-signature=b0tLEibUI9AnfcjMMG0K1iLDKec%3D",
    "score": "7.2",
    "category": "双男主",
    "abstract": "【双男主+无限流+养成+甜宠爽+成长型玩家攻x满级鬼怪受】\n\n尸鬼的爸，阴女的妈，生了个天生祭品的娃。娃为了保命，认主大佬玩家。磕磕碰碰苟到满级，金主一朝音讯全无。摸爬滚打三百年，再遇大佬变菜鸟。\n\n嘿嘿～是吃了他，还是吃了他？\n\n祁阳纳了闷了，别人在惊悚世界里见鬼遇怪大逃杀，他却总是遇到小艳鬼向他讨亲亲、要抱抱，一言不合就往他身上贴……\n\n嗯…有点怪、还怪可爱的嘞——\n\nPs：阳光开朗玩家攻x黏人病娇鬼怪受，无限流微惊悚，不会很恐怖，因为作者也会怕。\n\n谈甜甜恋爱，做快乐小狗(*˘︶˘*).｡.:*♡",
