    "score": "8.4",
    "category": "双男主",
    "abstract": "【双男！无限流！逃生游戏！】\n\n【哭的越凶下手越狠泪失禁体质受X老婆一哭就兴奋的战斗力天花板攻】\n\n唐明死后被拉入了一个非常诡异的世界，经历了许多\n\n奇奇怪怪的游戏，但也遇到了想要相守一生的人……虽然，他本质上并不能被称为人。\n\n副本一：转正游戏\n\n副本二：精神病院之大家来找茬\n\n副本三：游乐园大逃杀\n\n副本四：列车凶杀案\n\n副本五：暴风雪古堡之狼人杀\n\n副本六：角色扮演之奇怪的邻居\n\n副本七：图书馆之消消乐\n\n副本八：飞行棋之国王的棋子\n\n副本九：塔防游戏之玩具总动员\n\n……\n\n副本载入中，祝各位玩家游戏愉快！",
