    "score": "8.2",
    "category": "双男主",
    "abstract": "评分刚出～\n\n【双男主➕无限流➕恐怖游戏➕群像➕直播➕双强】\n\n腹黑温柔双标非人类攻×嘴毒心软傲娇少爷受\n\n/\n\n【游戏规则很简单，不要违规，活着通关，讨好观众，别当最后一名。】\n\n自从捡到一个戒指，林羡发现自己好像被一个男人缠上了，不管在哪都能遇见他。\n\n在西方有一种很古老的说法，一开始戒指的出现，其实是爱人下的诅咒，目的是为了困住你。\n\n所以林羡，当你心甘情愿戴上它时，我们已经灵魂交融了\n\n【阅前须知】\n\n1.1v1双男主，双洁双洁双洁！！！林羡×弗洛伽（陆钦斯）\n\n2.不要拆官配，官配只有一个，切片攻，任何和受宝有暧昧的全是攻，不存在1vn，双向喜欢\n\n3.没有逻辑，请勿较真，作者文笔有限，如果有什么奇怪的地方一律当成伏笔。\n\n4.这本书做不到所有人喜欢，每个读者宝宝的口味也不一样，请理智看文，遇到雷点请礼貌退出，谢谢宝宝！",
