    "abstract": "【1v1双强+无限流+沙雕+病娇】\n\n有的人才进逃生游戏就自带bug，比如陆无。\n\n别人都在认真逃命，只有陆无把逃生游戏只当做游戏。\n\n最离谱的是，逃生游戏boss他向陆无自爆了。\n\n为了活下去刀里来血里去的众游戏玩家抑郁，他们要集体举报陆无开挂！\n\n陆无：我不是我没有不要胡说，我只是个送人头玩家。\n\n众玩家和被摧残的副本npc：陆无的嘴，骗人的鬼！\n\n逃生游戏boss圈住作天作地的陆无：我的。",
