    "score": "8.4",
    "category": "双男主",
    "abstract": "【主攻＋切片＋无限流＋万人迷+偶尔扮猪吃老虎】\n\n【简介】\n\n【一对即将步入婚姻殿堂的新人，在婚礼的前一天晚上邀请亲友到家里吃饭，不料在饭局尾声，其中一位新人竟然跳楼身亡。】\n\n【事后，一家人在齐聚为这位行人进行最后的送别，但，诡异的事情一件接着一件，先是有人看见了死去的新人竟然从棺材中坐了起来。随后参加葬礼的人一个接着一个死去。】\n\n【众人意识到，他们之中藏着一个比鬼还可怕的东西……】\n\n··········\n\n时妄，一个被卷入恐怖逃生类游戏里面的老实人，在独来独往的25年生涯中，突然被系统告知，他的多了一个男朋友？\n\n系统纠正：【是前男友。】\n\n时妄望着面前的恐怖怪物发出了灵魂拷问：“我跟它都不是一个物种吧？我怎么成为它前男友的？”\n\n系统：【爱能跨越一切不可能啦，相信你自己。】\n\n时妄：“……这跨的也太多了！”",
