    "book_id": "7195050600722074680",
    "book_name": "顶级玩家杀疯副本，拐跑邪神",
    "author": "白桃呜呜龙",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/df202f0178f85a591b2608584b76a620~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358541&x-signature=PFee80eEPVtG4MajIYvJ2%2FY30%2B8%3D",
    "score": "9.7",
    "category": "双男主",
    "abstract": "实体书已上架，出版名：[神之陨落]\n\n（非人，恐怖怪物，慎入）\n\n殷修在规则小镇生活了六年。\n\n正常玩家进来都循规蹈矩刷副本，为了存活忙碌，只有殷修天天待在小镇不出去，不刷副本，不沾诡怪，每天打鱼晒网，甚至开始养老。\n\n小镇的诡怪们也盯了他六年，每天都咬牙切齿，业绩刷了那么久，唯独没刷到过他。天天看着他在跟前晃悠，却对这个熟背规则的人一点办法都没有。\n\n几天后，小镇大雨，又来了一批新人，一个被塞入殷修屋子做舍友的神秘男人当晚就搞定了小镇诡怪六年都搞不定的事——把殷修拖入了规则副本。\n\n当晚，小镇诡怪聚众狂欢：好耶！终于把那个摸鱼养老人送走了！\n\n同时，副本诡怪开始哀嚎：谁把六年前那个杀穿副本的男人拉进来的？！我们当年好不容易才把他赶出去的啊！！！\n\n殷修进入副本后兴致缺缺，提着刀看了看周围：一成不变，没新意，走了，速通回去养老。\n\n众副本诡怪长舒一口气，刚准备半场开香槟，一排扭曲血红的字忽地出现在了殷修面前。\n\n：你看我有新意吗？\n\n黏腻的寒意瞬间降临到了整个副本，诡怪、玩家无一不开始恐慌。\n\n“它”出来了。\n\n——\n\n满级大佬回归旧本虐菜是常事啊。\n\n杀穿副本后就养老很奇怪吗？\n\n修身养性，喂个邪神也正常吧？\n\n看我干嘛？我的攻略可不兴用啊。",
    "word_number": "1098184",
