    "score": "9.4",
    "category": "双男主",
    "abstract": "（已全本完结）\n\n【欢迎玩家来到赌命游戏！】\n\n【强制赌局已开启！】\n\n【赌局内容为:您是否能在此副本存活到通关？】\n\n【请选择:是/否】\n\n谢楚:……违规设立赌场，没人举报你们吗？没人举报那我来举报。\n\n系统:？哇塞\n\n·\n\n·简介已经够详细请自行排雷→\n\n-Cake偃×Fork楚（真实进食），有短暂失忆梗·\n\n·\n\n1.1v1双男主无限流，偃×楚，演出顺利。\n\n2.攻是切片，但切片可以忽略不重要，双洁。\n\n3.微恐，有大量儿时听过的鬼故事情节，版本不同不用细究，一切不合理的地方算我架空私设。\n\n4.剧情逻辑与科普内容不严谨，作者是文盲不要轻信，不属于高智商剧情纯解密类型，【只是爱看两个人谈恋爱而已】，有漏洞就睁一只眼闭一只眼看。\n\n5.主cp:（偃楚）演出顺利。\n\n【本人不支持、不承认、不同意、不喜欢任何拆/逆官配cp的行为！本文有对象的都不能拆逆，无对象的嗑糖禁止带入正文甚至故意扭曲正文内容，请勿打扰其他读者的阅读环境！】\n\n6.不出意外的话是每晚七点一更，会随机休息一天。\n\n7.不喜欢主角人设/看不下去/不理解/觉得主角ooc/看不懂/哪里怪怪的请→理智看文弃文无需告知。\n\n8.我有自己的节奏，不要教我写小说。",
