    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2od53d6401935adacbc780025a6fecfc24~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=PcJlbnmqgHDXYOzwU6z5FZbIRZ4%3D",
    "score": "6.8",
    "category": "双男主",
    "abstract": "【双男主+游戏入侵+升级流+强强+1v1】\n\n游戏入侵蓝星，人们被迫进入游戏副本，在各种游戏中挣扎求生。\n\n林叙，一个从天灾末世穿到这里来的倒霉蛋，没有道德，没有同情心，有的是绝对的武力和对生存的渴望，他要成为站在这个世界最顶端的独狼。\n\n因为在末世被饿狠了，林叙对美食尤其是甜品没有任何抵抗力，可谁能告诉他，为什么有人的天赋技能竟然是一个甜点师啊，这让他如何拒绝？\n\n“林叙，草莓蛋糕要吗？”\n\n林叙：“要！”\n\n夏翊风：“那就加入我们。”\n\n^-^\n\n林叙：“不要！”\n\n夏翊风：“那蛋糕我就拿走了。”\n\n……\n\n林叙欲哭无泪，我加入还不行吗，这人一定是老天派来克制他的！",
