    "book_id": "7641038802684759064",
    "book_name": "神明设计师，在星际做游戏杀疯了",
    "author": "杭漪禾",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o76db9d555d70b2b0182c7db6acfb835f~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=9dMOXsyTj7toamXK5or08ywnKCI%3D",
    "score": "8.0",
    "category": "双男主",
    "abstract": "【（评分刚出）星际+双男主+双洁++双强+1v1+恐怖游戏+神话系列游戏+文明传播】\n\n星际时代的水蓝星，一个人人普遍精神力暴走的三级文明星球。\n\n直到一个人从长眠中清醒过来。他做的游戏，悄然改变了一切。\n\n他用中式恐怖教全宇宙什么叫真正的心理阴影。\n\n网友非要嘴硬说《棺娘子》不恐怖！\n\n那就上强度，一个《育英学校》副本……所有人吓得吱哇乱叫。\n\n水蓝星玩家通关后，惊奇发现精神力都稳定了。\n\n那些想扒这位游戏设计师的信息？\n\n不好意思，要让你们失望了。\n\n从中式恐游到神话系列游戏，水蓝星人民：原来这就是母星文明啊！\n\n水蓝星、乃至全宇宙的人民都在求：“求求谷大设计师，多出山海经和神话系列副本吧。”\n\n谷衍嗤笑，放出嘲讽：“这就怂了？你们不是每个副本都说不恐怖？”\n\n黑粉们怒而回怼：“＃＆＃……”\n\n*\n\n谷衍作为蓝星存在时就存在的神明，从漫长的沉睡中清醒过来时，他发现自己身处星际时代。\n\n沉睡太久，忘记了一些事情的谷衍一醒来就发现他和人登记结婚了。\n\n结婚对象192，是水蓝星的首席网域构建师，大佬级别。\n\n*\n\n他说：“我的心脏因你的赋予而跳动。”\n\n他说：“谢谢你将我唤醒。”",
