    "score": "8.2",
    "category": "双男主",
    "abstract": "全民求生+基建+双强➕囤物资+HE（100w字已肥可宰）\n\n直球糙狗×冷脸戏精\n\n偏男频风格，不是爽文（但也不用带脑子看），但杀伐果决，不圣母b。\n\n求生向。各种特殊副本，任务等待各位玩家的挑战，全程高能，刺激不断。\n\n残酷的环境，被迫的竞争，唯有聪明的头脑，强健的身体才能活下去！\n\n-\n\n刚步入社会的少年许忘聘请了一位健身教练辅导健身。\n\n没想到这个人居然是他的死对头！\n\n可就在这时，一个名叫全民双人求生的游戏在蓝星降临。\n\n进入游戏需要亲吻才能匹配队友。\n\n可是周围只有裴肖这狗东西一人啊！\n\n严酷的求生环境，简陋的庇护所，一本求生手册\n\n跟着死对头一起进行需要合作才能生存的游戏，真的能活下去吗？",
