    "author": "Fawns",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/5bc595eaa88f3bb88ff9c862f45ee295~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=x46B2j1nkUaW5U2uGTIWuXJYvmo%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主＋1v1＋游戏＋直播＋年下＋强强＋双洁】\n\n【人不狠话不多闷骚野王攻（凌余/LING）X线下温和学长线上戾气喷子法王受（鹿游/游弋）】\n\n游戏是王者荣耀，双主播非电竞，架空背景无原型。\n\n-\n\n凌余和鹿游都是王者分区的头部主播，去年一把对局出了嫌隙相看两厌，两家互相嘴了一年难舍难分。\n\n一朝听闻隔壁主播打pk输了要露脸直播，凌余在直播间冷笑：“走，一起去ob一下，等会隔壁露脸，大伙就把‘哈哈’和‘就这’打在公屏上。”\n\n到点后鹿游在直播间犹犹豫豫的开了摄像头。\n\n谁能想到著名的喷子主播竟然长了一张绝顶漂亮的脸蛋，可爱到直播间的观众疯狂尖叫。\n\n凌余也整个傻掉，谁能告诉他，对家主播怎么会是他暗恋多年的那个人啊。\n\n-\n\n欢迎来到王者荣耀，我还有五秒到你心上。",
