    "score": "9.1",
    "category": "双男主",
    "abstract": "【双男主+万人迷+强强+主受+全洁+西幻+全息游戏背景】\n\n【表面吊儿郎当但遇事很靠谱的大魔法师受（南荣）+满级大佬重回新手村炸鱼】\n\n【篇幅90%以剧情流为主+绝对单箭头的红眼狗狗们哐哐打架预警】\n\n非切片，目前确定的男主有：\n\n傲娇绿茶白切黑玩家：江颂\n\n温柔体贴忠犬竹马NPC：雪莱\n\n心狠手辣病娇反派BOSS：K/维尔里希\n\n-\n\n南荣一朝加班猝死，再睁眼发现自己穿越到了一片异世大陆。\n\n他摸爬滚打苟活了十多年，期间被深山里的猛兽追赶过，被食人藤蔓绞杀过，还在原始部落当过祭品。\n\n终于，他来到了游历这片大陆的最后一站，踏上世外桃源的青石板路，南荣望着村口袅袅炊烟，恍惚听见了退休生活的钟声。\n\n【叮咚——】\n\n【新手任务已接取，请前往村口对话[老村长]开启新手教程】\n\n南荣：？",
