    "score": "9.4",
    "category": "双男主",
    "abstract": "【头部已丢失APP】提醒您:\n\n——脖子上挂着的是您的头，不是皮球，别让人踢走。\n\n——请保护好您的头。\n\n·\n\n【前排高亮→没有替身梗，攻就是一个绝望的oc爹罢了。】\n\n·\n\n1.1v1双男主，双洁，庸×慈。\n\n2.微恐，一切不合理的地方算我架空私设。\n\n3.剧情逻辑不严谨，作者是文盲不要轻信，不属于高智商剧情/纯逻辑解密类型，感情为主，剧情为辅。\n\n4.本人不支持、不承认、不同意、不喜欢任何拆/逆官配cp的行为，禁止带入正文甚至故意扭曲正文内容，请勿打扰其他读者的阅读环境！\n\n5.不出意外的话是每晚七点一更，每个月会随机休息一天。\n\n6.遇见雷点自行退出，理智看文弃文无需特意告知，是你弃书，而不是让我改书。\n\n7.觉得ooc/哪里怪怪的/极端gksk/→请直接退出。\n\n8.不要教我写小说，我想写什么就写什么。",
