    "score": "9.2",
    "category": "双男主",
    "abstract": "主攻\n\n进入逃生游戏，慌乱逃命？那是不可能的。\n\n江淮安一进去，想的不是怎么逃命，而是直接看上了一个游戏boss，不怕死地凑上去撩。\n\n然后，他就撩到了一个强力外挂——\n\n屠夫砍刀追人，他拿电锯反追，大boss陪同；\n\n鬼魂发狂吃人，他拿麻袋套上，大boss踩住；\n\n怨灵惑人跳楼，他拿镜子反照，大boss补刀。\n\n……\n\n对此，玩家和npc们纷纷表示：把你身后的boss带走，谢谢。\n\n——\n\n主攻（攻会女装）\n\n受是boss（非人）\n\n不要ky！也不要空口鉴抄！",
