    "book_id": "7512661266012326937",
    "book_name": "玩女号撩到大神后跑不掉了",
    "author": "加冰茉莉奶绿",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/77938ad856688a6f97a6f7d196cdc71e~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=AaXNlvNUIMm7Wo4G0VfScNosrFw%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "评分低是因为才出，会涨起来的\n\n【双男主➕双洁➕网恋翻车➕傲娇受】\n\n谢燃是联盟最负盛名的中单新人王，长得帅操作强，出道一年就带着HX横扫季后赛拿下两个冠军，风光得不可一世。\n\n直到YK战队的打野江星言回国，比他高比他帅不说，首发第一场就把他打了个负战绩。\n\n更可恶的是，在YK夺冠的当天，他亲耳听到江星言对自己出言不逊，给出了“实在一般，真不知道在狂什么”的评价。\n\n打又打不过骂又不能骂，谢燃憋着一肚子火没处撒，然后当天晚上，他就刷到了一个网恋的帖子，对方男扮女装骗钱骗心，还把博主一个人骗到陌生城市奔现，直接把博主气进了医院。\n\n谢燃对博主的遭遇表示深感同情，然后连夜找到了自己的游戏小号给江星言发了好友申请，开启了白天看不惯死对头，晚上哥哥长哥哥短勾引死对头的生活。\n\n后来—\n\n谢燃被江星言抵在墙上，对方手指轻摸他的嘴唇：“不是喜欢叫哥哥吗？怎么不叫了？”\n\n谢燃欲哭无泪：“我错了哥，我是男的……”\n\n江星言低头吻他：“男的我也喜欢你。”",
