    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/b7d416af7527f746abf2e6a45a6ba052~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=AqNTsW07R%2FCnBLPotwE05wRSaAc%3D",
    "score": "8.8",
    "category": "双男主",
    "abstract": "[评分刚出，不具有参考价值]\n\n【双男主＋1V1＋主角团＋主剧情＋无限流＋道具异能流＋攻受都是玩家＋弹幕流】\n\n祝尧，一个梦想混吃等死的富二代。\n\n终于成功把自己——等死了。\n\n诡异游戏强行上线，死亡倒计时直接启动。\n\n想要活命？行，给你派点队友，自己组队通关吧！\n\n系统提供的【传奇队友】名单如下：\n\n1.疑似中二病晚期的暴力女高中生（？）\n\n2.不说话装高手的高冷酷哥（？）\n\n3.善良到过分的巴黎圣母院在逃圣母（？）\n\n4.方言技能点满的骗子小道士（？）\n\n5.？？？\n\n这是打无限流副本的队伍吗？！炮灰天团是吧？！\n\n【超过三十秒未做选择，以上都是你的队友】\n\n［欢迎来到神明の游戏］\n\n【黑切白纯情莽夫攻＆白切黑but薛定谔的胆子受】\n\n【不知道啊他们喊着什么“来吾道夫先路”就躲到奇怪的地方去了】",
