    "author": "月柒柒",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/7479f43b95df5df5a2263c2b5a17289a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=6PL9qdVuZ4qDJN%2FCIs8jXT7PVVc%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【无女主＆无限流＆微恐＆双强＆反差】\n\n主攻（不适合极端控看）\n\n林清郁进入逃生游戏，每次都异常非酋。\n\n别人的通关奖励最次都是武器或异能，只有他——\n\n玫瑰花，贺卡，小彩灯……一连串鸡肋的东西接踵而来。\n\n所有人都在幸灾乐祸，认为这个人活不了多久。\n\n可面对嗜血可怖的女主人，他绅士地递上玫瑰花：“夫人，愿您的美貌如玫瑰一样艳丽不朽。”\n\n遇到疯小孩过生日，他随手递出贺卡：“小朋友，生日快乐，这是礼物……”\n\n碰到隐身杀戮者之后，他把小彩灯缠到对方身上：“亮闪闪的看着好看多了。”\n\n……\n\n其余玩家眼睁睁看着他用这些东西通关所有副本，瞪大眼睛——\n\n他真的，是非酋吗？",
