    "book_name": "网恋到了讨厌我的人",
    "author": "秋色撩人",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2od761e104d470fa624265f5fbff2b18da~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358543&x-signature=zXX5EdyMVXEvAE5rS36lRaWo8VY%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "【双男主+游戏直播+网恋奔现+酸甜+互宠+非节奏爽文+非狗血】\n\n（文中有私设。）\n\n（游戏版本更迭快，文中可能落后于现实版本。）\n\n游戏小主播母胎SOLO多年，在游戏里遇到了心动对象。\n\n作为平台没什么人气的小主播，邱勒云每天的心愿都是：涨粉、赚钱！吃饱穿暖，然后攒钱把脸上的胎记去掉。\n\n单身多年的穷鬼，老天居然在游戏里给他安排了一个对象，对方温柔有学历，经济独立有存款！反观自己，只是宅在出租屋里的屌丝宅男罢了……\n\n然而，在屏幕之后的人，曾经很讨厌他。\n\n酸甜小故事，从游戏开始，以一生为终。\n\n对抗路甜弟的网恋日常，高超的操作和甜甜的恋爱更配哦。\n\n温覆容vs邱勒云\n\nPS：文中游戏是王者荣耀",
