    "abstract": "双男主+主受+攻重生+公路求生+忠犬+1V1+受欧皇\n\n在天灾降临前，简乐以为自己跟前男友一定会老死不相往来。\n\n结果在天灾降临前两个月，前任哥找上门，后面的一切都跟加速了一样，解释完误会，了解完叔叔婶婶一家恶毒的真面目\n\n他就被前任哥丢到军区训练了!\n\n简乐怀疑自己玩的是加速版地球online，不然为什么他上一秒刚跟前任哥重新亲上，下一秒就穿越异世界求生了啊喂!",
