    "author": "小折子",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/490c6ce711f213701b987aea471c6adf~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358545&x-signature=LZ4p6pM8JftwXy1Pw12ZFsqElvY%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【满级大佬+双男主+惊悚无限流+逃生+强强爽文】\n\n作为逃生游戏的守关boss，季寻从有记忆起就在为主系统打工\n\n每天兢兢业业，全年无休，任劳任怨\n\n然而逃生者从他手下生还的几率位于boss榜最高\n\n季寻：怪我喽？\n\n逃生玩家：这个boss人还怪好嘞\n\n于是逃生主系统大手一挥，将这个吃白饭还得倒贴积分的boss开除并扔到隔壁兄弟系统处打工\n\n季寻：行叭，再就业什么的，我应该可以\n\n到后来无限流玩家中流传着这样一个传说\n\n有一个长相特别漂亮的玩家，他穿着黑色的大风衣，只要跟着他，就没有通不了关的副本\n\n无限流玩家：如果开局没有季寻，那我整个人，我的灵魂，甚至我美好的品质就都毁了\n\n被称为玩家最强战力的那个男人冷笑一声：不好意思，这条大腿我抱了\n\n提问：和人类最强战力谈恋爱是种什么体验？\n\n季寻：谢邀，人在总部基地，刚刚和男朋友从副本里出来。具体的感受就是，我终于不用再努力了\n\n满级大佬boss受vs人类最强战力攻",
