    "abstract": "【双男主、甜宠、1V1、双洁、末世、完结】\n\n海今视角：\n\n从海底上来时，海今也没想到人类会有那么多不可以。\n\n“不可以捡地上的东西吃。”\n\n“不可以假装会写字。”\n\n“不可以一个人偷偷离开。”\n\n“……”\n\n海今：人类，你们真的很复杂。\n\n顾万顷视角：\n\n变成人的小珍珠，捡一个。\n\n【腹黑宠溺人类天花板攻 VS 可爱直球武力值爆表受】\n\n——\n\n我在时间的起点，与你相遇。\n\n在世界诞生前，就开始爱你。",
