    "book_id": "7647817080128949273",
    "book_name": "尸王有格调，直男每天破防",
    "author": "不能说我不行",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/7c9b7031f7670fa5905cd0d0b5e0fd76~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358545&x-signature=cigcJvLWFmRsKkuP27ZSlg5clk0%3D",
    "score": "8.8",
    "category": "双男主",
    "abstract": "【末世丧尸】【异能突变】【群像】【腹黑钓系好色攻 v 脏话炸毛直男受】\n\n陆子初找黎沐飏吵了一架就末世了。\n\n好消息：他俩没死。\n\n坏消息：。\n\n外界丧尸成群，昔日死对头被迫住在一个屋檐下谋生……你特么咬我干嘛！\n\n他一口，他一口。\n\n终于遇到别的幸存者。\n\n“他被咬了！”\n\n陆子初：这特么是人咬的！人咬的！\n\n队友：谁咬的？\n\n陆子初：……我媳妇儿，行了吧？\n\n“他也被咬了！”\n\n黎沐飏：也是人咬的。\n\n队友：谁？\n\n黎沐飏：贱内。\n\n……\n\n行行行你俩挺会玩儿是吧！",
