    "score": "9.2",
    "category": "双男主",
    "abstract": "【双男+美攻帅受+主受+1v1双洁】哭包绿茶×直男\n\n（别名1：哭哭哭，把心软直男骗到手\n\n别名2：太好了，是心机男同，我没救了）\n\n祝砚被新疆炒米粉里的馕给噎死了，为了他那存款，去各个小世界完成任务，虽说每次任务都完成了但画风都不太对劲，不管他是剧情里面的反派，男二，炮灰，\n\n男主总会腆着脸往他面前凑，让祝砚对他负责。\n\n祝砚：？我去为啥？哥们我男的……\n\n男主哭唧唧：宝宝你也知道的，我从小就没有男朋友，啊呜呜呜……\n\n祝砚：。彳亍\n\n——\n\n小可怜的酷帅狸花猫\n\n钓鱼佬被魅魔缠上了\n\n顶级绿茶大小姐A×冷脸情敌A\n\n过气明星x小哑巴\n\n……\n\n……\n\n第二次书测结束，最优书名以及封面已经替换掉第一次的！",
