    "abstract": "评分刚出#末世 #双男主 #aob #双强\n\n#异能\n\n#架空\n\n全城沦陷，病毒肆虐，秩序彻底崩塌。\n\n严肃古板的言叙，栽在了嬉皮笑脸的坏兔子手里。\n\n一场恶作剧般的意外，他被这个疯兔子彻底粘上了！\n\n一路逃亡，一路互掐。\n\n在这座没有希望的末日里，我甩不掉你，也不想甩掉你了。\n\n谁能拒绝疯批粘人攻×清冷禁欲受！宿敌变爱人，全程高甜拉扯~\n\nAO，双洁HE，热脸贱冷脸萌，后面会有崽，崽不是人，感谢理解！\n\n攻占有欲很强，所有出现的配角都不会长久地跟着主角团，攻嫌电灯泡碍眼都会把他们踹飞～",
