    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o39f082f660024b1954191613c273c742~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358545&x-signature=OsIyeDRfmtDwz7og65luR%2BLBT2c%3D",
