    "abstract": "「评分刚刚出，后续会涨，请放心观看～」\n\n扮猪吃虎杀手年下攻vs沉着冷静主心骨队长受\n\n双男主➕末世➕反差➕年下双洁➕双强。\n\n末世来临的第九个月。\n\n城北营地队长陆征程，在一个搜寻物资的夜晚救下被当成肉盾的少年沈雨。\n\n从路人口中得知沈雨体质特殊，就算被咬也不会变异，顶多掉几块肉。\n\n回到营地后，伤痕累累的沈雨表现得十分柔弱，我见犹怜，更令人震惊的是沈雨竟然总是有意无意....勾引他？\n\n但在后面的相处中，这个瘦弱的少年，并没有他想象中那么单纯，他遇事冷静，出手干净利落，甚至没有痛觉。\n\n一次出行任务，陆队等人野外遭丧尸围攻，生死时速救星降临...",
