    "score": "0",
    "category": "双男主",
    "abstract": "【双男主+死对头+末世+双强+群像+公路+异能+双洁】\n\n开朗直球受x毒舌闷骚攻\n\n（攻暗恋来的）\n\n是升级流，有成长线。\n\n2030年，R国突遭“奇怪的病毒”侵袭，死去的人莫名其妙“复生”，末日降临，全球异变，丧尸横行，现代文明被摧毁，社会阶层重组，人类面临生存危机，有人开始建立新的秩序阶级，有人开始为了生存自相残杀。\n\n异能者成为新贵族，普通人沦为蝼蚁。\n\n丧尸病毒在A大爆发，从小到大互为死对头的林池跟沈彦，在图书馆开始被迫一起求生。\n\n一个情绪来的快去得快，一个理智慢热，彼此互相努力适应，在末世中共同进退，相拥取暖，建立新的秩序。\n\n升级流，后期基建。\n\n林池异能：治疗+植物（中后期）\n\n沈彦异能：冰系+空间（中篇之前）\n\n（有群像，有副cp）",
