    "score": "9.4",
    "category": "双男主",
    "abstract": "【双男主1V1 攻受前世今生都双洁，原名《天生罪过》】\n\n【偏执忠犬男大攻X温柔专一总裁受】\n\n【重生追妻+互宠+双向奔赴+天生一对+救赎】\n\n入室抢劫型恋人，攻重生。\n\n楚离为钱做了洛闻声三年金丝雀，大学毕业前夕，主动说了好聚好散。\n\n他坚信自己是直男，坚信自己跟洛闻声在一起没有感情只图钱。\n\n但是洛闻声死后的第十七天，楚离带着害死洛闻声的人同归于尽了。\n\n再睁眼，楚离回到了大学刚开学还不认识洛闻声的时候。\n\n在楚离的想象中，见洛闻声的第一面他要乖巧得体帅气有型。\n\n争取跟前世一样让洛闻声对他一见钟情。\n\n事实上的楚离，见面就扑，生扑，硬扑，扑完再扑。\n\n这一次，他要洛闻声安康顺遂，平步青云。\n\n……\n\n楚离，“我就在这站着，我看谁敢过来欺负我老婆，都给我死！”\n\n洛闻声，“楚离最乖了，不许污蔑他！”",
