    "author": "有一只猫猫",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/3fb1765b4f1f47b6af5b2fcf61fbb4bd~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358546&x-signature=AedckqADrVvcn8MBMiyHr9nvdf8%3D",
    "score": "8.4",
    "category": "双男主",
    "abstract": "【双男主，攻受均非人，团宠，he，微群像，嘴硬心软的疯批玩偶师受X失忆闷骚的人偶大佬攻】\n\n双向救赎，双洁，失忆的听话狗狗，谁会不喜欢啊~\n\n某天，余听被黑色盒子拉进了一款游戏里。\n\n发现自己被一步步的推着往前走，陷入了一个又一个谜团里。\n\n慢慢发现，自己就是创造这个游戏的主人。\n\n传闻中的游戏大神是他创造的人偶，也是他的爱人。\n\n而他也不是第一次进入游戏。\n\n这是一个关于情感的游戏，他在这里找到了真正的自己。\n\n谜团慢慢揭开，那个幕后黑手竟然是......\n\n惹到他，他可不是什么软柿子。\n\n杀戮之神，也能杀给你看。\n\n后来的直播中。\n\n“就是他们，听说这个小队，到处破坏副本。”\n\n小队中，傀儡师运筹帷幄，出手果决。\n\n观众疑惑。\n\n“不是说，他是凌柒大神养的金丝雀吗？”\n\n“这一刀一个小朋友，你管这叫金丝雀？”\n\n“好好好，我在副本拼命，他们在副本里恋爱？”\n\n......\n\n前期略虐，后期报仇，he结局，各位观众老爷们，给个机会，感谢支持~\n\n作者努力ing......",
