    "score": "9.2",
    "category": "双男主",
    "abstract": "【年下美强惨+直掰弯+死遁+追爱火葬场+系统+异能应有尽有，入股不亏～】\n\n（攻对受前期黑装白切黑，不要被他的表面骗啦大家）\n\n穿进小说变成炮灰角色怎么办?当然是抱紧男主大腿！\n\n“叮咚！现已绑定‘我偏要主角讨厌我’恶趣味系统，获得男主100厌恶值即可返回现实世界。”\n\n穿进小说变成炮灰角色怎么办？\n\n抱男主大腿（X）\n\n不断作死让男主厌恶我（√）\n\n易川为了回家，一边费尽心思获得男主厌恶值，一边还要防止在厌恶值达到100之前就被男主杀了。\n\n直到男主以为他睡着了吻了一下他的脸颊，系统却提示厌恶值+5时，易川才感觉到不对。\n\n什么？？这年头，男主表达讨厌的方式已经变成亲一口了吗？？\n\n这是一个看了十年男频文的纯种直男男大穿进双男主小说，变成哑巴文盲路人甲炮灰，被战力爆表美人受攻了的故事。",
