    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/3402f895f2e3329b3dbe50faa01822dd~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358546&x-signature=XH8cTUULtM6%2BimzpCSOWbzOKW5M%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "（架空➕反差互撩➕单元破案➕救赎➕HE➕双强双洁➕群像➕微重口）\n\n【痞帅话痨毒舌队长齐焱✖️耳聋体弱但能打“活死人”天才法医莫问】\n\n24岁天才法医莫问空降支队，齐焱强烈反对“天才”来镀金。\n\n天才什么的只会添乱。\n\n上一个低情商不听指挥没有团队意识的天才法医已经被他打包踹回老家了。\n\n本着给个下马威的心思去，重度颜控齐队长见到第一面直接被硬控到张嘴就是:hi 脑婆。\n\n莫问一脸嫌弃，哪来的傻大个。\n\n众人：哇塞塞琉璃冷美人，得保护好！\n\n莫问歪头：琉璃？我吗？\n\n转身一脚踹翻三个大汉。\n\n-\n\n后来，一桩桩诡谲血案接踵而至。\n\n本该死去的人再度复活，一年前的爆炸案里藏着什么不可告人的秘密？\n\n-\n\n一切尘埃落定，莫问却目不能视耳不能闻，彻底坠入寂静的黑暗里。\n\n齐焱不信邪。\n\n-\n\n两年后，莫问重见光明：“齐焱，我好像，能听见你的心跳了。”\n\n齐焱红了眼眶。\n\n-\n\n“他曾是世界留给我的唯一回响，后来，他亲手为我带回了整个喧闹的人间。”\n\n推推俺的老书《重案调查科》 ＾3＾",
