    "abstract": "【双男主＋无限流＋灵异+直播＋双强＋沙雕＋HE+主受】\n\n【软萌恶劣嘴炮异瞳受VS清冷禁欲腹黑管理者001攻】\n\n南旬生的一副软萌相，天生异瞳，偏偏长了张气死人不偿命的嘴，怼天怼地怼自己！\n\n因极阴体质，撞鬼成日常，但撞一只骂一只就有点过分了吧？！\n\n主打一个鬼怕他！\n\n某天他收到一封诡异邀请函，被强制拽入【回廊游戏】:\n\n观众越多，曝光度越大，打赏力度就越高！\n\n南旬随口吐槽了一句。\n\n\"叮！＊＊用户已获得一积分！\"\n\n卧槽！还可以这样？！\n\n无脸鬼歪在脑袋向他招手。\n\n南旬睁着圆溜溜的大眼睛，乖巧的走过去。\n\n观众：“……”\n\n下一秒，南旬：“小姐姐，需要人造脸皮嘛！仅需500积分，现金也可以哦～”\n\n别人还在副本里瑟瑟发抖，南旬直接开启致富奔小康之路\n\n一路疯嗨了！\n\n观众和副本小怪全被他气到投诉主神！\n\n将一大把年纪的主神气到掀桌，送又送不走！\n\n无奈，派管理者001谢隋砚亲自监督。\n\n他作死，谢隋砚冷眼盯着他：再吵，把你扔去喂诡。\n\n南旬眸子弯弯：管理者大人这么凶，是想亲我？\n\n后来，说好的禁欲呢！！\n\n南旬表示:我只是嘴炮过个瘾而已，没想对方是实操派啊！！\n\n管理者把人按在怀里，嗓音沙哑：\n\n确实想亲，亲到你闭嘴为止…",
