    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/dad95f0c1ffc04155792f87b341bb3e9~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358546&x-signature=NWvHpnnbASD6Lhl4CCJOMwqdN2g%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【已完结】【双男主+主攻+强0弱1+受宠攻+甜宠治愈+年龄差8岁+微群像+无限流爽文+HE+BOSS×BOSS】\n\n【内含玄学、民俗、微恐、西幻等元素】【《副本》系列第三本】\n\n【作者简介废】\n\n【对外高冷·对内温柔热情腹黑·占有欲爆表·反差拉满的心理医生受×年下清冷·抑郁厌世·敏感没安全感多疑·泪失禁体质的纯情美人攻】\n\n骆禹明，自焚于十八岁生日那天，本以为自己能去往阴曹地府，却被拉入了无限流副本成为了大BOSS。\n\n骆禹明：“……”有时候真的很想引爆世界。\n\n因为不幸的童年，又因为被当做怪物，让骆禹明极为自卑敏感，一受委屈就会流泪的体质更让他连为自己出头都做不到。\n\n他总是低着头，想要隐藏自己，却没发现自己早就被人盯上了。\n\n他的同伴对他总是很温柔，让他不开心了会给他道歉，还总是安慰他陪着他，带给他的拥抱也永远那么温暖……\n\n对方就像光一样，突然来到了他的身边，带他走出童年的痛苦，教会他什么是爱，什么是自我。\n\n＊\n\n恶灵娃娃娃娃副本里，对方会温柔地为他擦去眼泪，告诉他，自己再也不是孤身一人了……\n\n挑嫁娘副本里，对方会安慰在黑暗中胡思乱想的他，满怀歉意地道歉，然后掀起他的红盖头……",
