    "abstract": "【双男主+ABO+死对头+A变O+1V1双洁】沈南峤从Alpha二次分化成了Omega，接受不了让Alpha帮忙解决发热的麻烦，他决定买个AI男友来使用。\n\n在设置机器人建模时不小心把死对头照片上传，又不小心把死对头当成了AI男友。\n\n沈南峤看着与昼烬长得一模一样的“机器人”，决定……物尽其用。\n\n“给我穿鞋。”\n\n“揉肩！捏腿！”\n\n“跪下！”\n\n“诶诶……我没让你亲我啊！”\n\n“你的手……别碰！！！”\n\n……\n\n沈南峤发现，AI男友看他的眼神怎么像是要吃了他？\n\n-\n\n在沈南峤眼里，昼烬是不死不休的死对头。\n\n在昼烬眼里，沈南峤是他不开窍的小竹马。\n\n后来，小竹马终于开窍了……昼烬在沈南峤耳边一次次的问：“我和你的机器人谁厉害？”\n\n沈南峤：？\n\n好好的一个人和机器计较什么。\n\n昼烬是在和自己较劲儿，他连自己的醋都吃。",
