    "abstract": "【双男主+\n\n规则怪谈+强强+微群像+直播+1v1+he】\n\n评分刚出，会涨的！！！\n\n避雷：拆官配\n\n！平行世界观\n\n！\n\n私设如山！没看过原著也可以食用！\n\n主CP：林七夜（攻）×安卿鱼（受）\n\n副CP1：王\n\n面（攻）×漩\n\n涡（受）\n\n其他：曹\n\n渊\n\n沈青竹\n\n人物OOC预警！！！\n\n——\n\n副本一：平安公寓\n\n公寓里全是死人，规则真假难分，队友比鬼还脏。\n\n林七夜和安卿鱼把反派骗进鬼窝，用管理员血替自己开门，带着四个被活祭的孩子超度了整栋楼。\n\n观众遭不住了，忍不住问他们凭什么通关——\n\n林七夜：凭我比规则，更懂人心。\n\n——\n\n副本二：槐阴村\n\n误入槐阴村，林七夜被选为献给鬼新娘的“新郎”。\n\n白天，村民们慈眉善目，夜里他们却被鬼童指路、纸钱漫天。\n\n那顶血红的花轿，每晚都在寻找替死鬼。\n\n直到林七夜发现——村里所有人都是死人，而真正的凶手，正藏在神庙佛像里朝他们笑。\n\n既然要玩，那就玩个大的！\n\n他们挖出书生骸骨，唤醒鬼新娘，最后一斧头劈开佛龛——\n\n“村长，你躲了五十年，该还债了！”\n\n——\n\n副本三：苗疆蛊寨（副本进行中……）",
