    "score": "8.6",
    "category": "双男主",
    "abstract": "【诡异降临，无限流副本平行开启，且看恶毒炮灰如何通关副本百分百。】\n\n【双男主+双强+无限流+副本闯关+微恐诙谐】\n\n【觉醒后狂拒恶毒炮灰命运受vs外表冷酷实则人机原剧情主角攻】\n\n全球诡异降临，作为无限流副本小队中的拖油瓶，庄朔行多次作死后终于达成猫憎狗厌的成就。然而在遭众人厌恶被赶出队伍时，他突然觉醒了，并且从此能够看到诡异世界外的直播弹幕。\n\n原来他竟是剧本里的恶毒炮灰，负责在主角攻受的成长和情感之路上添堵来让他们的感情愈加深厚，最终双双成为无限流副本世界的大佬。\n\n并且他很快就要因为这次赌气出走给小队带来第一次灭顶之灾。刚拿到最低级初始能力的小庄：那我还走不走了？\n\n——\n\n副本1：希雅高中规则怪谈\n\n被赶出队伍因此错过回寝时间的小庄蹲在台阶上长吁短叹，路遇另外一个进不去寝室即将受罚的倒霉蛋，十分自来熟地聊了起来。\n\n弹幕：小废柴真是嫌命长了，竟然招惹到副本的最终BOSS，不怕被直接扭断脖子？\n\n对上“小伙伴”核善的笑容，庄朔行：……\n\n副本2：古镇迷影（多人解谜类）\n\n副本3：白雪公主之死（大型剧本杀）\n\n更多无限流副本加载中…",
