    "score": "9.4",
    "category": "双男主",
    "abstract": "【双男主+非/典型规则怪谈+国运+智商流+一点点搞笑+直播+大量弹幕出没+无限流】\n\n高亮排雷：1.本文受视角，主剧情。\n\n2.另一个男主为切片背景板，出场次数少且出场较晚。（121章）\n\n兢兢业业拯救世界大学生x背景板恋爱脑邪神\n\n规则怪谈降临蓝星，宋临风被选中成了代表天朝参加游戏的幸运玩家。\n\n第一次全体游戏，他成了唯一活下来的选手。\n\n宋临风：其实我靠的是智商。全球观众：不信！\n\n第二次全体游戏，他让副本提前关闭。\n\n宋临风：其实我是故意的。全球观众：不信！\n\n第三次全体游戏，他被某邪神强行拖走。\n\n宋临风：我不喜欢男人！全球观众：不信不信不信！\n\n宋临风：很好，微笑摆手.jpg",
