    "book_name": "摔！你是诡异，还是我是诡异啊",
    "author": "cp老骑士",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/e234de390a6e2e04a7688850aa38b25e~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358549&x-signature=JJzxQgDV%2BalUccwr1Y7ZY%2FoTkJk%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【双男主】【都市】【学院】【恐怖】【灵异】【剧情流】【打怪升级】\n\n两百年前，诡异降临，各路妖魔鬼怪横行，人类也随之成为觉醒者，力挽狂澜一举击溃了第一只即将毁灭世界的S级诡异。\n\n两百年后，风云再起，灭世危机再度袭来。\n\n而本文主角·要么咸鱼·要么翻身就变神经病·荆·傲天·白，曾经英雄的后代，却觉醒了最低级资质？啊不是，是觉醒了突破世界记录最低的E级，也就是——F级！！\n\n咸鱼瞪着死鱼眼，挠挠屁股，“啊？F级就F级呗，挺好的，俗话说，天塌下来，头一个砸死的就是高个子”\n\n嗯？斩杀诡异就能升级的好好青年向上系统找上门？\n\n好吧，那他勉强努力一把，争取成为S级觉醒者好了，偷偷发育，猥琐发育，背地发育。\n\n只是……\n\n为什么没人告诉他，这系统特么就是一个坑坑坑坑货啊？！\n\n本文主角·已被啃掉脖子·倒地血流不止·荆·咸鱼·白，享年十八，卒！\n\n故事到此结束。\n\n“嘻嘻嘻，怎么可能”\n\n荆白从血泊中缓缓起身，反手一刀一个诡异。\n\n笑的变态：“听说有诡异想找我玩？嘻嘻，我也最喜欢和他们玩了”\n\n坑货系统：【完了完了≥﹏≤】\n\n【宿主死了几回，人已变成神经病，害怕】\n\n【嘤嘤嘤，抱紧我自己】",
