    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/6bb7112f3f394d14ab987400035643eb~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358549&x-signature=e08wXa2ETuj5gBZeozAw94RzHw4%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【双男主+万人迷+穿书+校园+微恐+灵异+玄学+鬼王】非传统万人迷，所有改观和喜欢都有迹可循。\n\n许朝当了八百年鬼王，是人是鬼都怕他，他过腻了这样的日子，一日心血来潮，自愿踏入轮回，谁知喝了孟婆汤，记忆全无的他，却成了一名位面工作者，在万千世界中扮演小角色。\n\n许朝工作勤勤恳恳，\n\n言情文里，站在街边，对女主吹口哨的街溜子是他；\n\n阴阳怪气，嘲讽落魄男主，嘎的最快的也是他。\n\n总得来说，他是为了衬托出男女主，那能与太阳肩并肩的人格魅力，而存在的……炮灰！\n\n——\n\n一朝，系统bug，他错穿成了灵异文里的炮灰渣攻。\n\n只要渣了主角受，让故事顺利进展下去，则功成身退。\n\n许朝“小问题，不就是戏份多一点的炮灰吗。”\n\n慢慢的，他发现，事情似乎……并不简单！\n\n那主角受，表面清冷温顺，对他言听计从，实则想让他当替死鬼？\n\n替死鬼也就算了，动不动要亲亲抱抱是闹哪样？\n\n……\n\n更奇怪的是，那些鬼都怕他。\n\n其他同学，嘲笑许朝连最简单的平安符都不会画，转头却见许朝随手甩出一张符，那极难对付的厉鬼，老老实实跪在了他面前。\n\n那张符上歪歪扭扭写着一个字“滚”",
