    "abstract": "双男主+怪谈+直播+疯批美人+邪神+恋爱脑+甜宠爽+双初恋双唯一\n\n恋爱脑邪神x疯批无敌美人\n\n怪谈降临人间，诡异横行世界。\n\n和诡异同时出现的，是一个银发异瞳的……人类？\n\n速通副本，单挑诡异。\n\n一手提着长刀，一手拿着牌位，长发随风，美人回眸。\n\n江遇笑的灿烂：我就只是一个失忆的普通人而已，已婚，勿cue。\n\n围观群众：……\n\n你家普通人单手就能剁了诡异？\n\n还有已婚是怎么回事？从来没见过他身边有其他人啊？\n\n＊\n\n直到后来——\n\n某一次副本结束后。\n\n记者：江遇先生，请问您在游戏里亲晕BOSS是什么心态？BOSS脸红逃跑大家速通游戏的时候，您有什么想说的吗？\n\n江遇抱紧牌位闭口不答。\n\n我想跟我老公好好谈谈。\n\n这件事我能解释，真不是我的错啊！\n\n（BOSS也是攻哈～）",
