    "abstract": "【恶鬼攻X活人受，主受双男主，双洁，穿越即回归】\n\n死后穿越，成了一个不知名村庄的祭司，温如安每天的工作就在待在神庙里面，打扫神庙卫生和陪伴神像。\n\n可，奇怪的事接连不断发生，例：没有补充却每天都有着最新鲜食材的厨房，没有打扫过卫生却始终纤尘不染的神庙，还有无故消失的剩饭，每日男鬼准时的控诉，出门时对他态度古怪的村民，时而能跑能跳时而一步三喘的村长……\n\n各类事件不一而足，处处写满了诡异，处于人类对未知的好奇，对着诡异之处，温如安不自觉开始了深挖和探寻。\n\n只是，探寻到最后，他发现，这里是恐怖游戏的一个副本。\n\n而他，原本就属于这里，还有一个被他遗忘了的男鬼丈夫。\n\n至于那被他遗忘了的丈夫在哪，温如安抬头看向庙内两米高的石像，沉默……",
