    "author": "林顭",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/bc4c66ee757dde73b3ce23660336c081~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358549&x-signature=oLMtYxr4r6JS%2BMDUk8DmcpcLwDo%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "「已签出版」冷知识，他的第二人格私底下喊他老婆！\n\n【双男主+悬疑恋爱+捉鬼师+白切黑+盗墓+双洁+群像】\n\n爷爷死前用最后的机遇做局，招来了鬼王入体，护张即知度过死劫。\n\n天生瞎子的张即知在那晚之后，眼睛突然能看到白色的炁。\n\n他身体中住了一个暴躁鬼王，还莫名成为了捉鬼师。\n\n—\n\n“听我的，拦腰斩断，就一挥手的事。”\n\n“不行。”\n\n“快杀了，话是真多，吵的我脑壳疼。”\n\n“不行。”\n\n鬼王褚忌：杀杀杀，通通都杀咯！\n\n张即知：我不。\n\n—\n\n人怎么被砸晕了？\n\n顶号的褚忌从废墟里伸出了手，自行接上错位的骨头，表情不羁：\n\n“哦吼，是哪个大聪明砸晕了张即知这个废物，终于到我表演了～”\n\n“来，给你三秒跑路的时间。”\n\n“跑不掉就死掉。”\n\n—\n\n崩溃的同行队友发出质问：\n\n“张即知你到底在和谁讲话？！”\n\n“我的左脑和右脑在说话。”\n\n鬼圈都传，惹谁都不要惹瞎子，他有第二人格！\n\n—\n\n褚忌前期：死瞎子，解除契约我第一个杀了你！\n\n褚忌后期：小知，你用铁链把我拴住好不好？",
