    "abstract": "老攻被预言能让任何女人生下最强职业者怎么破？\n\n【双男主+无限流+升级流强强+克苏鲁+悬疑惊悚+纯爱+序列+职业】\n\n张文昊：“梦书，记得初见时对我的第一印象吗？”\n\n郑梦书：“身高体壮，看上去很好骗的傻大个。”\n\n张文昊：“？”\n\n郑梦书：“被退货的优质商品。”\n\n张文昊：“？？？”\n\n郑梦书：“有几分颜值的种公男？”\n\n张文昊：“？？？？”\n\n【藏尸红线】\n\n，【黑色羚羊】。\n\n口中尸气挂铃铛。\n\n阴森的白家大院，微笑的红嫁娘。\n\n当一个又一个超出想象的事物出现，郑梦书警觉或许他才是最不应该的存在。\n\n“张文昊，神明预言任何女人跟你一起都会生下最强的孩子，这是真的吗？”\n\n看着笑意盈盈的少年，张文昊心神一动：“怎么？你要不要亲自试试？”\n\n“滚蛋！我是男人！\n\n注：超级大大大长篇，入股不亏。\n\n这是一个很长的故事，一个希望能得到大家喜爱的故事",
