    "abstract": "【双男】只想准点下班暴躁社畜·武力值Max兔耳医生X除了老婆谁都想杀·重度绒毛控双标疯狗深渊病毒\n\n【当你凝视深渊时，深渊只想撸你的耳朵】\n\n作为连接无数恐怖副本的唯一中转站，“S级怪物康复中心”是玩家的噩梦，也是社畜燕随朝九晚五打卡的地狱。\n\n这里的病人很特殊：\n\n007号裂口女因笑容不够标准而抑郁；\n\n5楼克苏鲁邪神有严重的触手打结困扰；\n\n就连刚送来的丧尸王也哭着喊着要妈妈。\n\n面对这群杀人KPI不达标的疯子，院长兼主治医师燕随表示——\n\n如果心理疏导没用，那就实施物理超度。\n\n当噪音超标、听觉过载，长达半米的雪白兔耳猛地弹出。\n\n哪怕是S级厉鬼，也挡不住这一记毛茸茸的暴力耳光。\n\n直到那一天，锁在地下五千年的0号病人“深渊”越狱。\n\n3S级警报拉响，玩家抱团等死。\n\n却见那足以吞噬天地的不可名状之物，正把自己缩成一只委屈的大型犬死死缠在燕随的腰上，脸颊变态地蹭着医生炸毛的粉色耳尖：\n\n“医生，他们好吵，我想吃掉。”\n\n“闭嘴，不准。”\n\n“那为了奖励我忍住食欲，”深渊在敏感的绒毛边吹气，“能不能让我咬一口你的耳朵？就一口。”\n\n燕随面无表情，长耳扬起，将试图乱舔的深渊一耳朵抽进了墙里。\n\n“滚回去。我看你需要",
