    "book_id": "7225122121066744835",
    "book_name": "第四天灾：秩序神座",
    "author": "应歌夜月华",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/9fa8e5605dc06cd2b50f0c60674e68cf~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358551&x-signature=8XT13wL2p6cHSHdaSU%2F7uCZHAnQ%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "（女频双男主+第四天灾网游+群像+腐向！！无女主+强强+白切黑+腹黑领主+异世大陆+种田发展+魔法世界+克苏鲁跑团元素（含二次原创设定）解密副本+伏笔多有逻辑+轻微迪化流+前期设定多，慢热请耐心观看~非一般幕后玩家流）\n\n偏向正剧的轻松欢乐文～适合大众口味，若读者自带与众不同雷点，请务必阅读简介自行避雷！\n\n命运之骰从高塔滚落，弥漫着的滚滚黑雾被银蓝色光芒驱散，分崩离析的世界权柄缓缓归于原位。\n\n交替运行的黄绿双日之下，新继任的大魔法师、异世界的游戏策划、阿姆特郡的领主、世界意识的执行人——莫驭托着世界精灵踏着荆棘而来，背后跟着浩浩荡荡挥舞着章鱼触手的玩家大军，露出善良的招牌微笑：“别怕，他们都是正经玩家，都是来驱散入侵这个世界的邪神的。”\n\n邪神：…？你礼貌吗？\n\n本书又名《邪神驱逐计划》/《克苏鲁侵蚀：异世界拯救计划》\n\n这是个一本正经的普通社畜成长的故事，金手指有但不多。\n\ncp腹黑领主莫驭与白切黑圣子伊亚利恩（骑士）无差。\n\n本文多视角，设定会跟随主角/玩家/NPC视角逐步展示，单方视角未必准确。各位不用急于下结论，可以看完全文再行判断~\n\n有部分游戏梗（ff14/塞尔达/博3）但作者不曾玩过原神（事实阐述）",
