    "score": "0",
    "category": "双男主",
    "abstract": "【末世克系+人外+甜宠爽文+年上】\n\n【外表恐怖实际温柔蠢萌的触手攻（希尔塔）x原本怯懦内向 后逐渐成长人类受（沈砚）】\n\n被怪物独宠是什么体验？？\n\n原本只是普通社畜的沈砚，在26岁这一年突然碰上末日降临。\n\n黑雾蔓延，怪物横行的末日里，他躲在卧室瑟瑟发抖，却等来一只闯入的触手怪。预想中的生吞没有来临，取而代之的是温热紧密的拥抱。\n\n别人在末日里亡命奔逃，沈砚却被最恐怖的怪物贴身守护。\n\n没人知道，祂早在黑雾蔓延前便窥见：这个胆怯内向的人类，将觉醒最强的治愈异能。\n\n（攻会变人形的，黑皮黑发！）\n\n双强副cp：暴躁雇佣兵闻栩×疯批银发美攻伽埃塔",
