    "book_id": "7639416378142772248",
    "book_name": "邪神，你饲养的人类实在嚣张至极",
    "author": "元宵宵",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/dd4ae044788ec6f688da0aa481f3cb2c~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358551&x-signature=znxo8uSbsHJj76lk8s2%2BL8njjws%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "（评分刚出）非人理智引导攻 × 比格型病弱矜贵受 | 双男+人外+HE+年上\n\n“神啊，不管您是哪一位，请救救我，我愿意付出任何代价。”\n\n当现代医学走投无路，宋瑾跪在一众邪神像前，赌上了自己最后的筹码。\n\n黑暗中，一位沉睡的邪神率先睁开了眼。\n\n他扫过满室神像，挑眉看向这位“杂食”信徒。\n\n“拜得还挺全，既然是我先找到的你，也算缘分？”\n\n邪神以为捡到了一只乖顺的小羔羊，从此爱他、敬他、服从他。\n\n可惜，能在十几位邪神之间反复横跳的人类，怎么可能是什么柔软小蛋糕？\n\n第一次动心，对方往自己身上猛撒朱砂。\n\n第二次靠近，对方高价请了道士来对付自己。\n\n第三次想表白，对方递来一沓天师亲笔符纸：“要尝尝吗？”\n\n邪神终于怒了，决定亲自下场，把这信徒所有“坏毛病”一一纠正过来！\n\n至于怎么纠正？\n\n……那就要看自己舍不舍得下狠手了。",
