    "book_id": "7308283355311655998",
    "book_name": "恶意占有【无限】",
    "author": "山白山",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/e4aa69e5373326a8b6f2f64b201f9ab4~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358551&x-signature=J%2BF9pKhQPgsubi3iNDPiwnhTUwo%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【切片发癫神经病攻x厌世仇富社畜受】\n\n【内含偏执病娇、强制占有欲、鬼祟、三观跳舞、恐怖游戏慢穿、古早狗血等情节，小说请勿代入现实】\n\n【作话排雷请看】\n\n季漻川是个勤勤恳恳的麻木社畜，每天上班下班，赚钱还债，不问世事。\n\n有天在食堂打菜，耳边传来一个电子音。\n\n“亲亲您好，这边有个可以快速赚钱的项目亲亲感兴趣嘛~”\n\n“不违法不出境没有996工资立结哟~”\n\n季漻川看着盘子里头的番茄炒蛋，面无表情说：“好。”\n\n下一刻他眼前就成了一片虚无的空间，一个自称零的高冷电子音在耳边叨叨他需要进入一些游戏，完成一些任务。\n\n季漻川没问别的：“好。”\n\n零那句“人身事故概不负责”卡在嘴边。\n\n跟谁打工不是打，往哪卖命不是卖。\n\n季漻川本来以为凭借自己资深社畜的身份可以很快适应并且优秀地完成任务。\n\n没想到每个世界都在撞鬼。\n\n季漻川：“……”没人关心麻木的社畜也会怕鬼。\n\n季漻川捏着鼻子在恐怖游戏里勤勤恳恳工作。\n\n没想到这地方最恐怖的还不是闹鬼。\n\n而是那个如影随形、无处不在的神经病，每一次都会让季漻川麻木的内心经受晃动，并且大受震撼。\n\n——\n\n“我爱你嘛。”\n\n他说。每一句情话都像阴森森的鬼语。\n\n季漻川：“求你滚。”\n\n“我不。”",
