    "book_name": "惊悚游戏里，神明纠缠我不放",
    "author": "疯狂的嘎朵拉",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/b2fd6a7ed2e9ccf1d4242a3187a8cc87~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358551&x-signature=pvxMpbTy4XFqCOtyhdHoO1VD%2F3U%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【无限流+无女主+双强+偏执病娇】\n\n叮！惊悚游戏降临人间啦！\n\n这一刻所有人都觉得这恶趣味的游戏就是为了杀死他们的！于是大家崩溃的崩溃，逃命的逃命，没人知道这游戏是怎么找上他们的。\n\n可实际上这游戏在默默保护着人类，当然，前提是要通关哦！\n\n没多久，大家就发现游戏里有个bug玩家存在，他们逃命，安槐抓鬼，还逼的鬼都跪地求饶，求他放过。\n\n最重要的是安槐自己强就算了，他还带了个外挂。\n\n外挂男友：说吧，杀哪个，我动手，你站着别动，小心被弄脏。\n\n神明靠人类的信仰而活，没了信仰便会陨落，于是有的神便走上了歪门邪道开始屠杀人类。\n\n死神靠人的恶而活，恶意越多死神越强，可惜死神的名头终究不好听，没人愿意当，于是安槐来了。\n\n他明明可以跟着神明杀人获取永生，却偏偏成为了人类的保护神。\n\n天神男友：你保护世界，我保护你",
