    "abstract": "[灵异+破案+双男主]\n\n25岁的陈瑜，在大城市打了两年工后，决定回老家躺平了，结果因为他的特殊能力，和新来的一个叫李泽林的人卷入案件里。\n\n通过触摸死者物品，洞悉死者临死前看见的一切，利用这一特殊能力，陈瑜和朋友们破获了一系列诡异惊险的案件，每一个上门来委托的客户，都将给主角团带来一段意想不到的经历。\n\n陈瑜也从此打破社畜咸鱼状态，开启险象环生的精彩探案人生。\n\n主CP李泽林VS陈瑜，副CP张虎VS牛聪，其他：苏染，谭峰，张龙。",
