    "book_id": "7600211773559409688",
    "book_name": "玄学打脸假少爷，全网跪求我算命",
    "author": "燃灯儿",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/6683310f26151539c9e754a44a83573e~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358552&x-signature=Bmmqd2qwCTcvWudVDuTq73%2BD4XU%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "（评分刚出）天才通灵师穿书娱乐圈炮灰万人嫌～\n\n不吸阴气就会亖天才玄学大佬x跋扈巨富宠妻攻\n\n【灵异+恐怖+悬疑+捉鬼+打脸虐渣+万人迷+直播+小故事+甜宠+1v1双洁+极限拉扯】\n\n穆青玄一觉醒来被陌生英俊男人踢下床。\n\n“穆青，你真让人恶心。”\n\n穆青玄：？？！\n\n穿书这么离谱的事居然发生在了灵界最强天才通灵师头上。\n\n原主身为人气组合ACE的门面担当，十分不爱惜羽毛，是名副其实的万人嫌。\n\n耍大牌，霸凌队长，造黄谣，卖惨骗钱，高调示爱队员等等\n\n穆青玄：……\n\n贼老天这是看我太顺风顺水故意的？！\n\n直到他再次和那人重逢。\n\n对方一张俊脸被晦气遮得妈都不认识。\n\n穆青玄：印堂发黑，恐有血光之灾\n\n凌天纵：呵，这次going的方式挺特别\n\n穆青玄：我说真的，你快死了\n\n凌天纵：除非跟你睡？\n\n穆青玄：......还真是\n\n不久后\n\n穆青玄：说了别再跟着我，你的咒我已经解了\n\n凌天纵：你肯定看漏了，不然为什么我一离开你就不行\n\n穆青玄：呸呸呸，男人不能说不行\n\n凌天纵：嗯嗯嗯，你试试\n\n穆青玄：我直男\n\n凌天纵：不，你不是，你喜欢我的脸\n\n穆青玄：......\n\n......\n\n排雷：万人迷，有副cp，雄竞（包括不限于深情影帝、禁欲判官、阴湿反派、政界大佬、小太阳、甜心、玄门天才等等）",
