    "abstract": "［双男＋甜宠＋双洁＋灵异］简昭作为一个驭鬼师靠捉鬼发家致富，顺风顺水，没啥大愿望，就是在30岁之前买一套大别墅，享受精彩人生。\n\n就当他在为自己的大别墅兢兢业业的捉鬼时，一个突然出现的鬼差抢了他的活。\n\n更气人的是，这个鬼差在人间的生活比他好多了，人比鬼气死人，“远丞你个大烧饼！”\n\n挡了简昭发财致富而不自知的男人，\n\n“别闹，大别墅给你住，我也给你……”\n\n简昭“你别亲我，救命啊~”",
