    "book_id": "7582865888466979864",
    "book_name": "玄学神棍在豪门狗血文里艰难求生",
    "author": "渣渣渣东东",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o455d8c9f080cec4b5373cb7a355f5b27~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358552&x-signature=tiwoMJgLeNBpajU1n8gTd7W46As%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【穿书+双男主+双强+民俗惊悚+悬疑+灵异复苏+对抗路情侣】\n\n一觉醒来，左白穿成了小说里的炮灰男配。\n\n原身被邪术害死，房租交不起，仇家藏在暗处，身边还全是狗血剧情里的疯批主角。\n\n好消息是，他前世是茅山传人。\n\n画符、驱鬼、占卜、布阵、请神，样样都会一点。\n\n为了苟命，左白不得不重操旧业。\n\n在下城区开局破邪符、斩怨童，误入隐藏在现代都市背后的里世界。\n\n人前，他是乖巧无害、被吓得瑟瑟发抖的小可怜； 人后，他一张符纸定乾坤，五路猖兵听号令，把厉鬼按在地上摩擦！\n\n直到他惹上了特管局那位出了名的疯狗裴度。\n\n审讯室内，裴度把玩着打火机，笑得玩味：“左先生，监控显示你一巴掌把僵尸扇飞了三米，怎么解释？”\n\n左白眨巴着无辜的大眼睛，瑟瑟发抖：“由于太害怕，肾上腺素飙升……这很科学，警官。”\n\n后来，万鬼围城， 众人绝望之际，他发现才所谓穿书并非意外。\n\n阅读指南：\n\n1.白切黑演技帝/满级大佬受 VS 斯文败类/混邪/专治各种不服攻\n\n2.副本：镀金婴尸，落花洞女，尸陀林主，肉身菩萨（其他待定中）",
