    "author": "林顭（主播：鹏哥）",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/d4e7e332aa47a25c2e20cc7c95f12b33~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358552&x-signature=rNC2Fn0ZzJw6rkH58vOgdGJqgLo%3D",
