    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主＋灵异捉鬼＋系统+1v1+HE，年下，包甜的】\n\n【假清冷克制真叛逆·正统道门攻x低精力但被迫直播苟命·懒散靠谱受】\n\n【岑非云x终来】\n\n——\n\n终来车祸濒死后绑定了灵异续命系统，低调苟命三年，系统一夜升级，非要他去捉鬼时开直播。\n\n系统：【你好宿主，不直播要倒扣寿命哦！】\n\n终来：“……”\n\n—\n\n第一天开播撞鬼，就有不速之客持剑闯入。\n\n来人眉目锋利、语气清冷肃穆，按住他的肩膀冷冷质问：“灵气混杂，野路子术法，你是哪来的邪修？”\n\n终来：“……”\n\n—\n\n废弃学校、医院怪谈、地库阴煞、鬼市寻宝——系统任务纷至沓来，高冷道长不小心刷成了榜一。\n\n弹幕狂喜：闺蜜！你最爱的双男主小剧场更新啦！\n\n终来：“……哈哈。”（微笑升天.emoji）",
