    "abstract": "（评分刚出，后期会涨～有私设）【双男主+灵异+直播+娱乐圈+捉鬼】\n\n【撩天撩地自投罗网自毁钓系受×前期神秘禁欲后期占有欲强温柔攻】\n\n柯言，一个曾在顶流组合里当背景板，因为解约，被黑粉追着骂了好多年的花瓶糊咖，竟参加了一个灵异探险的节目。\n\n起初大家期待柯言被吓得屁滚尿流，谁曾想他要么和鬼谈心，要么画符驱邪，甚至给两个鬼说起了媒，还教小鬼跳起了女团舞…\n\n观众：你们黑粉管这玩意儿叫废物花瓶？？\n\n-\n\n起初柯言只是单纯觉得宋之昀神秘，所以才会接近他。\n\n可他万万没想到自己居然把一个灵综给撩成了恋综。\n\n柯言：你看那鬼模样真俊，生前应该像我一样貌美如花\n\n宋之昀：所以你百年以后也会是一个貌美的鬼\n\n弹幕：【典型的宋氏夸夸，磕死我啦！】\n\n柯言：这你们也磕的下去？\n\n弹幕：【只有你自己不知道你们两个的气场有多么与众不同！】\n\n-\n\n起初大家只是磕CP，甚至还担心起节目结束后的戒断反应\n\n谁知道节目还没结束就有狗仔拍到柯言和宋之昀在街边拥抱。\n\n看着热搜，宋之昀掐着柯言的腰按到墙角，动作看似强势，语气却卑微：“我没什么话给你套了，所以这个热搜你要澄清吗？”\n\n柯言眉眼一弯，语气充满诱惑：“澄清你跟我真的像他们想的那样，是吗",
