    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/051428c13cb7fd25ccbf7d2878cc2688~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358552&x-signature=iAICSgSItBBwKzQbicFgmPDqKAo%3D",
    "score": "9.1",
    "category": "双男主",
    "abstract": "（已完结）【双男主＋娱乐圈＋灵异＋双强＋非典型疯批】\n\n●大人，你在我墓前送的花，成了我此生的信仰。\n\n白清徐——驱鬼界第一混子败类，一朝穿越，成了娱乐圈十八线小糊咖，还是黑糊的那种，驱鬼界的低保吃不了了，只能努力营业打工混口饭吃。\n\n——综艺直播——\n\n白清徐：各位观众有钱的捧个钱场，有人的捧个人场，我给大家表演个捉鬼魔术。\n\n弹幕：装神弄鬼，娱乐圈毒瘤！\n\n恶鬼退散后……\n\n弹幕：卧槽，还能这样？！白清徐你是我的神！\n\n——鬼界闯关——\n\n白清徐：不好意思，你听过‘古有孙悟空大闹地府，今有白清徐横闯鬼关’吗？\n\n小鬼：什么玩意儿？白清徐谁啊？啥时候闯的鬼关？\n\n白清徐：在下不才，正是白清徐，我打算今天闯鬼关。\n\n小鬼：……日！哪里来的祸害！\n\n——\n\n白清徐所及之处，没有他不砸的场子，他还以为自己只是混口饭吃，依旧是个混子。\n\n但是大家咋都成了他的粉丝？他不是万人嫌全网黑吗？就连顶流鬼王都成了他的cp……\n\n白清徐：前辈，有镜头……\n\n某影帝：哦，刚好撒点糖。",
