    "abstract": "【灵异+悬疑+推理+都市+双男主+无系统+无女主+互相救赎】\n\n平城。\n\n一座有着两千多年的历史文化古城。\n\n这千年的古城，若说没有一丁点的蹊跷事，是不可能的。\n\n有了蹊跷事，总要有解谜的人。\n\n因为一个诡异的案件，我结识了他。\n\n饿得只剩骷髅的尸体、被吸了魂的少女、莫名其妙的自燃、午夜诡异的公交车、亡灵飘荡的老宅、充满怨恨的泥娃娃……我们携手解开了这一桩桩的神秘事件的同时，也救赎了彼此孤独的灵魂。\n\n但是，一个更大的危机出现在我们面前。\n\n这一次，我无意间发现了一把钥匙。\n\n我和他……接下来会遇到什么事？而我们之间的感情又会朝哪个方向发展？",
