    "abstract": "〖双男主，双洁，1v1，无女主，甜宠无虐，顶配玄学大师受VS人前高冷实则中二攻，灵异玄学〗\n\n颜笑救个场没想到救到自己娃娃亲对象，看着眼前这浑身气运，金光闪闪的男人，颜大师表示，不要钱的气运，多薅一薅！\n\n顾岁安对娃娃亲的态度，就是让对方知难而退！可是看到眼前的男人之后...颜大师，我有个贴身保镖的工作不知道颜大师感不感兴趣。\n\n啪啪打脸的顾总：脸？那是什么？能吃吗？不能啊，但是我家笑笑我能吃啊！\n\n顾总每日三省己身：今天的我更爱笑笑了吗？今天我更黏笑笑了吗？今天我尝到笑笑了吗？",
