    "abstract": "【娱乐圈直播+轻松灵异+苏爽甜宠】\n\n【双男主，受强且疯，攻是绿茶娇娇】\n\n江诺，全网黑，要演技有颜值，要路人缘有黑粉。\n\n唯一让人挑不出错的，只有那张堪称女娲炫技的脸。\n\n死后被丢进无限世界闯关，历经劫难终于满级重生归来，开局就遇上恐怖综艺的邀请。\n\n综艺进行时，江诺拳打猛鬼，脚踢僵尸，还和厉鬼称兄道弟，又疯又帅苏爽满级！\n\n某影帝面不改色捏死猛鬼，面对江诺却绿茶上身弱柳扶风。\n\n“诺诺，冷，怕黑，抱抱……”\n\n江诺抱紧他的人型灵力补充剂，双方都觉得自己占了便宜，越撩越上瘾。\n\n而其他嘉宾……早已经被吓到瑟瑟发抖。\n\n网友：这个世界好玄幻啊妈妈！江诺他还有魔法！\n\n粉丝：诺神！你还有多少惊喜是朕不知道的！\n\n缺德CP粉：这是什么！糖！吃一口！",
