    "category": "双男主",
    "abstract": "【已完结】【双男主+快穿+1V1双洁双强+虐渣】\n\n【原书名：快穿：疯批宿主他又被病娇盯上了】\n\n辞影是一个曾经屠尽小世界把天道按在地上摩擦的疯批，成为书灵后在各个小世界做任务。\n\n某天，他的神魂里忽然出现了一个陌生的名字。\n\n从此，每个任务里，都有一个黏人的病娇。\n\n联姻对象：“我的一切都随你处置，别找其他人好不好？”\n\n绯闻影帝：“感情戏？不行，除非和我演！”\n\n太子殿下：“手不方便？孤来喂卿卿用膳。”\n\n式神妖狐：“除妖师所有吃的用的，都必须是干干净净的，不能沾染上讨厌的气息。”\n\n……\n\n辞·小疯批·影：“要不是我正好也喜欢你，你早就成一堆渣渣了。”\n\n桑铭：宝贝说他喜欢我(¯﹃¯)",
