    "author": "飞飞菲",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/9d00f0cc2fe7174a5f8ceea34525ff9a~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=ddQMQTzE7Gk42%2BS7OG0l%2BLUR6so%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【快穿双男主1v1】【双强双洁】【苏爽甜文】\n\n苏临深被一个看起来不是很聪明的小系统找到，要绑定他去三千世界做任务，攻略大反派。苏临深若有所思，随后笑眯眯的答应了。单纯的小系统看着乖乖软软的宿主，非常的满意，却不知道自己绑定了一个怎样的大佬。\n\n在三千世界，苏临深乖巧的看着大反派：“你是不是喜欢我呀?”大反派的心都要被他萌化了：“何为喜欢？爱为单位。”\n\n看着被崩乱的世界线，小系统：“你们清高，你们厉害。”\n\n这是一个打着做任务的名头谈恋爱的故事。",
