    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1bb8b951d53639c6afdfdd7b2f482fd8~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=ICBGPkhJ5l0BSesIGzoTx%2BhPzqM%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "PS：有声书已追平小说最新章节\n\n【双男主+攻受双强+直播快穿+打脸+无脑爽+甜宠+1v1双洁】\n\n深情男配，主角爱情故事中的垫脚石、分分合合play中的一环。\n\n有钱有颜但非要当舔狗，最后一无所有的大冤种工具人。\n\n做满了一千个深情男配，江叙他不不干了，反手接了个男配翻身的活。\n\n小白花清纯主角受被渣攻赶出家门，半夜找他帮忙。\n\n小白花：江叙哥，你能来接我吗，我没地方可去了……\n\n江叙：你打开缺德地图，搜一下酒店，看看还有没有地方去。\n\n小白花：……\n\n骄纵少爷受想利用他让主角攻吃醋，假装摔倒往他怀里靠。\n\n少爷受：江叙哥，帮我一次。\n\n江叙：（默默后退）（仰头看天）（月色真好）（傻x退散）\n\n摔地上一脸泥的少爷受：？？？\n\n然而每个世界江叙都能遇到个人。\n\n江叙：好巧又是你啊，我这边有个恋爱想跟你谈一下，谈不谈？\n\n面容冷峻的男人：……不谈\n\n江叙：行，那我换个人问。\n\n男人（咬牙）：……回来。\n\n闷骚爱盯老婆占有欲极强攻X很会撩钓系貌美男配受",
