    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/a6bd0665d6f5dc10df20c293f47b96fd~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=iJE6oZ9XJ39rFBcZs8tLtSs%2ByHc%3D",
