    "score": "7.3",
    "category": "双男主",
    "abstract": "【评分刚出，后面会涨的】\n\n【双男主+快穿+强取豪夺+小黑屋+he】\n\n【超级无敌美貌受&总是一见钟情的攻】\n\n【攻很狗，强取豪夺费尽心机不择手段，受根本没有招架能力\n\n【攻都是同一个人】\n\n李清徊意外死亡后，被系统选中去各个世界做NPC，系统信誓旦旦这个工作没有任何危险，只要在特定场合露个脸就算任务完成。\n\n可事情的发展超乎李清徊的预料，他每个世界都要被强取豪夺。\n\n系统：啊啊啊！宿主怎么又被强取豪夺了！他明明只是个NPC啊！\n\n世界1：服务生NPC被霸总强取豪夺了。\n\n【你是酒店的服务生，霸总被下药，只要帮忙打个电话就可以了，没想到霸总对你一见钟情，对你强取豪夺】\n\n世界2：背景板秀才NPC被太子强取豪夺了\n\n【你是一个卖画的秀才，只要给主角两个馒头就行了，没想到太子对你一见钟情，对你强取豪夺】\n\n世界3：邻居NPC被变态杀手强取豪夺了\n\n【你是新搬来的住户，旁边的邻居是可怕的变态杀手，没想到他对你一见钟情，对你强取豪夺】\n\n世界4：末世NPC被鬼王强取豪夺了\n\n世界5：军校NPC被联盟少将强取豪夺了\n\n世界6：店员NPC被世家少爷强取豪夺了",
