    "author": "哈欠怪",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/ba2db0d9b7b54e8489f32f8175b68c79~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=Pa3p15E00YWz7fWlW3mV8pNjFow%3D",
    "score": "8.5",
    "category": "双男主",
    "abstract": "【双男主+快穿+双洁1v1+甜宠，直男受vs阴湿男鬼攻】\n\n苏郁和炮灰路人甲系统绑定，去各个小说世界里扮演在主角的全世界路过的路人甲，见证主角发展的每一个关键点。\n\n主角相遇，苏郁在；主角亲嘴，苏郁还在；主角分手，苏郁依旧在......\n\n苏郁兢兢业业地扮演着镜头路人甲，但是——\n\n为什么这些小说都是男通小说？！\n\n主角男通就算了，他一个路人甲，怎么也被男通吻上了！！？？还是个变态！！！\n\n苏郁每个世界都能被这个变态死死地缠上，又被狠狠地欺负。\n\n被欺负狠了，苏郁红着眼给了那人一巴掌。\n\n变态：“宝宝，好爽，这边也来一下。”\n\n苏郁：“......滚呐！！！”",
