    "author": "姒绵绵（主播：高小双）",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/30548a8b81f8631487fcf21e6b0c4485~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=kGpgaM1rHp3Rhybf%2BXxLdLpA3c8%3D",
    "score": "7.6",
    "category": "小说",
    "abstract": "主角:白以尘\n\n【双男主+快穿+主攻+每个世界1V1+不切片(无固定 cp)]\n\n白以尘被名叫小黑心的系统绑定了，任务就是扮演各种男配，做主角的爱情催化剂。\n\n他时刻牢记着男配的四句准则。“主角吵架我安慰，主角痛苦我流泪，主角恋爱我撤退，主角买醉我心碎。”\n\n白以尘一直觉得自己扮演的没问题，可为什么男主变得奇奇怪怪了啊!?\n\n. . . ...\n\n世界一:我那个温柔病娇朋友\n\n白以尘按着剧本兢兢业业，自认为每一次过剧情时的表现都完美无缺，扮演着主角受爱慕者的他，殊不知主角攻看他的眼神越来越炽热。\n\n(我爱的，自始至终都是你。)\n\n世界二:那个占有欲超强的副本玩家\n\n白以尘成了一个苟延残喘还能活几百年的病秧子NPC，看着剧本上自己活不过后期的他，将心放进了肚子里，想必这回很快就能走完剧情了，谁知....\n\n副本重启，那名一直以为他弱小的玩家提前解决了所有人，只为让他幸福。\n\n(嚣张的野兽也会成全。)\n\n世界三:那个傲娇嘴硬的‘虚拟’男友\n\n哪怕是虚拟人的身份，白以尘的阳光与温柔依旧让那个小少爷沉沦。\n\n(甜甜的恋爱，无关彼此的身份。)\n\n世界四:那个禁欲又闷骚的alpha搭档\n\nAlpha与Alpha，太阳与月亮....",
