    "abstract": "【快穿双男主+主受】【会撩会演魅魔受+嘴毒变态神君攻】【超超超超甜1v1双洁！！！】\n\n兰铮身为魅魔，一生勤勤恳恳修炼只求飞升，结果渡劫失败，小命呜呼，临死前连个小嘴都没亲过。\n\n怎么想怎么亏。\n\n不知是不是怨念太重，系统找上他，说只要他能让小世界男主动情，就可以无痛飞升，问他愿不愿意。\n\n这还用问？\n\n喂到嘴的饭哪有不吃的道理？\n\n而且这些饭……不是，这些男主也太对他的胃口了吧？",
