    "abstract": "【已签实体书出版】【同名漫画已上线】\n\n【快穿双男主苏爽甜】【双强双洁1V1】\n\n天界001号囚犯司矜因罪孽值严重超标，被判去三千位面经历各种悲惨人生。\n\n监督系统瑟瑟发抖：大佬乖，你好好走剧情，不然主系统会惩罚……\n\n司矜动动手指把主系统搞瘫痪。\n\n系统：唔！就算主系统没了，天道还会……\n\n司矜一招干翻天道。\n\n系统：可是！就算天道没了，天君也会……\n\n某跪搓衣板的天君：矜矜生的好看，做什么都是对的。\n\n系统赶紧抱紧大腿：大佬！当我没说！！",
