    "abstract": "【双男主+主受+快穿+双强双洁+甜宠】\n\n每个世界都是he。\n\n季星夜执掌仙界星辰之力数年，某天觉得无聊，随手拐走时空局的系统008前往各个世界做任务，扭转崩坏世界男配的命运。\n\n原只是想打发时间，却不料对‘大反派’陆烬川动了情。\n\n季星夜：“008，我想让他当我老婆。”\n\n008：……\n\n确定关系后，季星夜被陆烬川吻的意乱情迷时，瞪大眼睛：“等等，这不对。”\n\n陆烬川埋在季星夜的肩窝处轻笑：“老婆，你好可爱。”\n\n——\n\n星轨绕烬川，爱意千万年，从此天地相合，岁岁不相负。",
