    "abstract": "【双男主+主攻双洁+甜宠爆棚1V1】\n\n很宠很甜很欢乐，剧情多多精彩多\n\n锦辰作为逆袭部大佬，眼看就要完成工作，一道任务直接将他重新送回三千界。\n\n“临时工作调剂，去拯救小世界的反派。”\n\n锦辰：？\n\n某系统：宿主！你要老婆不要！\n\n于是……\n\n清冷自闭小少爷牵住他的手：你……不能离开我。\n\n乖乖少年红了眼圈：你自己说喜欢我的，不能说话不算数！\n\n年上影帝伸手求抱：你救了我，就要管我一辈子。\n\n高冷帝国将军放下骄傲：你曾经说的……可还算数？\n\n锦辰：老婆我来啦！\n\n——\n\n小可怜反派被救赎之后，大佬把他宠上天啦！",
