    "abstract": "【快穿+双男主+主受+双洁+1v1+切片攻+身穿+甜文+he】\n\n意外去世后，闻星昼进入快穿局，前往小世界完成任务。\n\n不过怎么没人告诉他是当炮灰啊！\n\n【世界一:网恋对象总想面基\n\n闻星昼:我是社恐炮灰，不能让你抓到我哦。\n\n攻:正大街左手边穿白色卫衣深色牛仔裤手里拿着奶茶的是你吗？】\n\n【世界二:alpha总想让我……\n\n闻星昼:我是恶毒炮灰，你跪下来舔我的鞋面。\n\n攻:这只舔干净了，另外一只需要舔吗？】\n\n【世界三:苗疆少年总想给我下蛊\n\n闻星昼:我是聪明炮灰，想给我下蛊没那么容易哦。\n\n攻:那你给我下蛊好了。】\n\n【世界四:哨兵总想跟我……\n\n闻星昼:我是傻白甜炮灰，……是什么呀？\n\n攻:就是能让你舒服的事情。】\n\n【世界五:捉鬼师总想捉拿我\n\n闻星昼:我是漂亮炮灰，美貌能让你别抓我吗？\n\n攻:除非你跟我形影不离。】\n\n【世界六:吸血鬼总想……\n\n闻星昼:我是蠢笨炮灰，求求不要……\n\n攻:给一点吧！太香甜了。】\n\n【世界七:邻家哥哥总想……\n\n闻星昼：我是馋嘴炮灰，能不能给我一些吃的？\n\n攻：可以，你来我家我就给你吃。】",
