    "abstract": "【快穿+双男主+主受+双洁+1v1+切片攻+身穿+甜文+he】\n\n闻溪柏熬夜猝死后进入快穿局，绑定救赎系统前往小世界完成任务。\n\n不过系统怎么没告诉他救赎对象是反派！\n\n【世界一：拯救豪门私生子反派\n\n闻溪柏：愿意做我的跟班吗？我保护你。\n\n攻：我愿意，小少爷。】\n\n【世界二：拯救清冷网恋对象反派\n\n闻溪柏：嗨喽嗨喽，网恋吗？\n\n攻：不仅要网恋还要面基。】\n\n【世界三：拯救十八线明星反派\n\n闻溪柏：想成为顶流吗？我当你的金主。\n\n攻：只是金主吗？我想做你男朋友。】\n\n【世界四：拯救假少爷反派\n\n闻溪柏：不想离开家，做我小情人不就行了？\n\n攻：我离开家公司就会破产了，你确定让我做你的小情人而不是你做我的？】\n\n【世界五：拯救残疾总裁反派\n\n闻溪柏：娶我，我能让你站起来。\n\n攻：不娶就不让我站起来吗？】\n\n【世界六：拯救倔强书生反派\n\n闻溪柏：不是想状告不公吗？攀高枝不会吗？\n\n攻：会，求之不得。】",
