    "abstract": "【直男万人迷➕主受➕双男主无cp➕快穿➕修罗场➕全员单箭头】\n\n顾双一觉醒来，发现天崩开局。\n\n别人穿越有系统，有任务，完成任务甚至有奖励。\n\n而他，只有一个即将没电的系统留下的四个字——救赎男主。\n\n很好，所以谁是男主？\n\n于是顾双决定，既然不知道男主是谁，那干脆都救赎一遍。\n\n等系统满血回归后，才发现任务完成度已经百分百。\n\n不愧是他的宿主……\n\n不对！\n\n男主好感度百分百，男配好感度百分百，反派好感度百分百……\n\n等等，怎么还有黑化值？？\n\n系统震惊：宿主，你做了什么？？？\n\n顾双无辜一笑：我什么都没做，他们自己眼巴巴地就过来了。\n\n【现代悬疑文被盯上的猎物】\n\n【异能丧尸文的天才队长】\n\n【修仙文的大师兄】\n\n【男团选秀文的练习生】\n\n【惊悚文被无辜牵扯的男大学生】\n\n【贵族学院误入怪谈的F2】\n\n……",
