    "abstract": "1.双男主，互宠小甜饼，攻受谈恋爱。\n\n2.主攻快穿文，每个世界受都是同一个人。\n\n许多文中有这么一种人，他们外貌出众，他们出身不俗，他们品格纯良，却成为主角成长路上的踏脚石，最终落得个不幸的结局。\n\n而秦逸的任务就是穿梭于各个小世界之中，为他们改写剧本，护他们幸福安康。\n\n①娱乐圈：主打的就是一个甜宠√\n\n②年代：糙汉攻VS小知青\n\n√\n\n③虫族：国家发的老婆，真香 √\n\n④古代：这个疯批太监有点甜√\n\n⑤兽世：兔耳少年他好乖√\n\n⑥协议结婚找我我超甜√\n\n⑦我在异世搞玄学√\n\n⑧和死对头网恋以后√\n\n⑨穿成农家子的炮灰男妻√\n\n⑩金丝雀的职业素养√\n\n⑪末世：小魅魔能有什么坏心思呢√\n\n⑫我在星际直播制卡√\n\n⑬我家赘婿太凶残√\n\n⑭主役CV是真情侣√\n\n⑮……",
