    "abstract": "【评分刚开，快穿+HE+双男主+双洁+微强制爱+一见钟情】\n\n【白芝麻钓系受x阴湿偏执变态攻】\n\n【林墨，一只社畜吃馍馍被其单杀，意外被从天而降的炮灰系统996绑定。】\n\n【还在畏惧龙傲天无cp大男主吗，加入我们炮灰部，一步一步事业路，迎娶CEO走上人生巅峰。】\n\n然而，事情并没有这么简单--\n\n【宿主，我们这样装傻真的能完成任务吗？】\n\n【闭嘴，我为什么躺在男主怀里啊！】\n\n【某位神秘霸总：天呐，这里有流浪的老婆，太可怜了。*掳走*】\n\n【某位万宗俯首，修仙巨能：徒弟还是老婆，我自有分寸；老婆骂我，我自有分寸；老婆咬我，我....*苦立怕ing*】\n\n【某位无限主神：登录游戏就送老婆，是你老婆吗！？*挥舞八百只触手*】\n\n【某位恐怖扭曲生物：■，■■老婆好香■...*疯狂流口水*】\n\n【每一次都没能保住屁股——无能的林墨留】\n\n---更多世界待解锁---\n\n绝对双洁，超级甜文，基本无副cp\n\n*攻的三观不正但绝对恋爱脑*\n\n亲亲读者酱，多多支持",
