    "book_id": "7480204364187978776",
    "book_name": "快穿：路人炮灰也要被轮流啵啵吗",
    "author": "香草颗粒",
    "thumb_url": "https://p9-reading-sign.fqnovelpic.com/novel-pic/dd63df885bda184b92343a630d3a5b86~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=w45QERMpbP%2B6ZnBH2dG4rz%2FTyJ8%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+快穿+切片+团宠+万人迷+一见钟情+弱受+死遁】\n\n陆今安失忆在星际流浪，除了一张脸长的顶级漂亮外没什么特长，为了找回记忆，他和系统签订协议，要到各各世界扮演炮灰，作天作地，凄惨而死。\n\n穿成患有心脏病的恶毒男配，他一边厌恶主角受弟弟，一边觊觎弟弟健康的心脏，欺负被遗失在外的主角攻，还在反派幼年竹马落魄后直接断绝联系。\n\n恶事做尽的陆今安缩在角落，美滋滋的等着迎接自己必死的结局。\n\n然而——\n\n被觊觎心脏的弟弟小心翼翼将陆今安抱进怀里，“哥，别哭了，心脏有没有不舒服？”\n\n被欺负的主角攻趴在病房的玻璃上，虔诚的像个信徒，“小少爷，你可千万不能出事，我还没找你算账呢……”\n\n被抛弃的反派竹马拽住陆今安的后脖领，声音沙哑，“公主，这次别再把我删了。”\n\n早就准备好了死亡脱离的陆今安，“？？？”\n\n………\n\n情感迟钝顶级漂亮受VS无底线宠我醋我自己切片攻\n\n宝宝，你这么可爱是要被轮流啵啵的\n\n万人迷漂亮宝宝文学，土狗收割机，小世界待定",
