    "book_id": "7455605428680936472",
    "book_name": "说好做任务怎么变成谈恋爱了？！",
    "author": "三山花正开",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/01b8902a404888d0e0e67301a21ea9f0~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358554&x-signature=F5ibxLJQ%2BCqwOZfk1VggxO0%2BXkI%3D",
    "score": "9.1",
    "category": "双男主",
    "abstract": "【双男主＋主攻＋快穿＋1v1双洁＋双强互宠】\n\n正文+番外已经全部完结，宝贝们看完打个五星吧。\n\n天然系打架爱好者剑修攻X随波逐流蜃妖受（切片，各种口味都有）\n\n池越，天选剑修，随性洒脱，是司天局审判部的三位副部长之一，剑下斩过无数危害世界的仙魔人妖。\n\n为了还人情暂时借调去了拯救部，可是他却一不小心就看上了任务目标。\n\n那怎么办？当然是用尽各种本事把人拐回家！\n\n委托人：……人是回来了，但又嫁出去了，我谢谢你啊！\n\n除了编剧世界和第八卷if线有一丢丢玻璃渣以外，其他纯甜无虐。\n\n英武沉稳的将军攥着他的手腕：你的感情问题，只需要向我交代！\n\n外谦内傲的霸道总裁：“书比我好看？”\n\n天之骄子仙门小师弟：“师兄~他们说你偏心！”\n\n偏执敏感编剧：……我恨你，为什么不早点来？\n\n风流矜贵的帝王：青史与我何加焉？\n\n毛绒绒大老虎山君X误入妖鬼世界的采药人\n\n内敛温柔词曲作者x张扬乐队主唱\n\n脆弱敏感的小侄子：你罚我吧，别不要我。\n\n民国粗莽军阀X学院派军官：与你共守山河\n\n………\n\n池越：一生一世是他承诺我的，来生三生还能携手那是我的本事。\n\n万般过眼成空，有你便不同。",
