    "author": "木屿乔",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/81cd924d43ff83b04a46d9878943d265~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=xQ8AJcHkmnASoKnyC96JOVacF78%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+娱乐圈+1v1+穿书+先婚后爱+双洁】\n\n【禁欲闷骚总裁攻vs骚话连篇直球顶流受】\n\n一觉醒来，谢妄发现自己穿成了一本纯爱小说中的死炮灰。\n\n眼前站着个帅的惨绝人寰的大帅批，正是他的联姻对象霍西辞。\n\n帅批冷冰冰：“谢妄，如你所愿，我们离婚。\n\n离什么离？\n\n这脸，这腿，这气质，简直就是极品天菜。\n\n谢妄身体比脑子快，一把抱住男人大腿：“霍西辞，其实我早就对你情根深种。”\n\n霍西辞满脸写着：你在耍我？\n\n谢妄一脸痴汉：这个男人，就该是我的！\n\n霍西辞不明白，上一秒还跟自己提离婚的谢妄，下一秒就抱着自己大腿不撒手。\n\n而他的肌肤接触过敏症这次却没有发作。\n\n那不妨看看谢妄还能怎么折腾？\n\n后来，谢妄洋洋得意：我就说我挑的男人错不了！\n\n霍西辞心中暗爽：老婆真香！",
    "word_number": "374244",
