    "abstract": "【双男主】【真香预警】程熙因为意外，穿成了一个为了得到男主，作恶多端，下场凄惨的恶毒炮灰，还附赠了一个便宜系统。\n\n为了苟住小命，程熙立志做一个善良的炮灰，保住程家家产，为主角们的感情添砖加瓦。\n\n对于黎阳的试探，程熙立马表明立场：好马不吃回头草，兔子不吃窝边草，你占了两样，咱俩没可能。\n\n不过，为什么黎阳看他的眼神越来越奇怪？被男主盯着的压力很大的好吧。",
