    "score": "8.6",
    "category": "双男主",
    "abstract": "【双男主+穿书+主受+1v1+双洁+甜文+原书受转攻】\n\n清冷腹黑美人攻x阳光放飞乐观受\n\n凌燃从小到大都是他人眼中的别人家的孩子，好学生，可唯独不是他自己。\n\n一个意外，他穿入一本古早狗血虐文，成为了一个出场三章不到，调戏了清冷主角受，最后被炮灰的风流纨绔，还被告知必须拯救主角受才能在这个世界活下来。\n\n凌燃：呵呵，谢邀，也不是很想活。\n\n可他看着原文书中的坚韧不屈的清冷美人，高岭之花被各种强取豪夺，囚禁虐待，伤身伤心，最后还跟渣男美美HE时，真的绷不住了！作者你出来，这是人干事？\n\n我现在求生意志真的异常强烈！让我活！我真的还能再活五百年！打倒渣攻，拯救坚韧清冷受义不容辞！\n\n可是救着救着，主角受看自己的眼神怎么越来越不对劲了？\n\n咦？主角受你亲我干嘛？不行不行，两个受是没有未来的，我不想含泪做攻啊！\n\n谢清辞：……别再乱动了！",
