    "author": "禾宿",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o5701d88475ee92aa31093df5f8372291~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=mtesCzWWoPwVILFrs8h5DKdF4dQ%3D",
    "score": "6.8",
    "category": "双男主",
    "abstract": "（双男主，穿书受vs重生攻，）\n\n林序秋一觉醒来发现自己穿书了，还穿成了大反派宋明煜的冲喜男妻。\n\n但好在他是穿到了故事还未开篇之前，现在的宋明煜还是一个惊才绝艳的状元郎，并不是什么反派摄政王，林序秋觉得他可以再活一活。\n\n宋明煜上辈子被赵锐杀死后，原以为自己这样手上沾满鲜血的人，死后定然会下地狱。可没想到再次醒来后，竟回到了过去，看着自己活着的爹娘，弟弟，宋明煜感慨万分，这次一定不能让宋家得悲剧重蹈覆辙。\n\n只是，自己这冲喜男妻好似有些不对劲，不过既然已经娶了，那便好好养着吧。\n\n不过越养越不对劲，宋明煜似乎还养上瘾了。",
