    "book_name": "双向沦陷！这个凄惨男三我要了",
    "author": "一两打包",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/be10e1a208babfcffbea9b27010bc061~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=GtsEK8y56u1CqzwD9xrOL9SaGAI%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【双男主+穿书+1v1+甜宠+强强+双洁】\n\n凄惨男三惹人怜，你们不要我要！\n\n（此心不渝将军攻 x 耐心开朗强大受）\n\n-\n\n肖衍穿书后，第一件要做的事就是捡走男三大将军！\n\n书里，他唯一欣赏的男三不仅瞎了残了，还被作者写死了！\n\n所以穿书后，他就决定要改变男三的命运。\n\n伤要治，冤要伸，仇要报！\n\n可渐渐地，他心里竟对男三生出了另一种情愫……\n\n直到一天夜里，男三抵着他的额头颤声问道：\n\n你不是来救我的吗？为何不救到底？\n\n-\n\n赵承煜在即将坠入黑暗的时候，幸运地遇见了一个小太阳。\n\n小太阳对他独有一份的好，让他克制不住地心动。\n\n可爱这个字很陌生，他该怎么做，才能不吓到小太阳，让小太阳永远地待在他身边？\n\n-\n\n穿书的契机是你，终点也是你。",
