    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/64e325a90568570d727e732480e6f767~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=quBK0EkKRSDsLGVNn4QOoXcUI5Q%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "【双男主+豪门世家+微群像+甜宠+年上】\n\n【表面冷酷无情实则偏执深情反派大佬攻VS表面乖顺安静实则清醒理智穿书炮灰受】\n\n沈清弦穿书了。\n\n穿成被家族抛弃的炮灰私生子，开局就被派去反派霍聿川身边当卧底。\n\n系统还在一旁发布任务：获取反派大佬霍聿川的信任，扭转死亡命运。\n\n惜命的沈清弦当场反水，对反派大佬坦诚相待：“我想和您做个交易。”\n\n大佬同意了。\n\n第二次见面，反派大佬对他说：和我结婚。\n\n沈清弦：？\n\n有点突然，但沈清弦决定抱紧反派大腿。\n\n沈清弦把这一场婚姻看作是合作和交易，可他没想到，那个原著里冷酷无情的反派，会把所有的温柔都给他。\n\n没谈过恋爱的沈清弦心动了。\n\n他以为这只是自己的一厢情愿，直到霍聿川把他圈进怀里，低声说——\n\n“不只是合作，不要再躲着我。”\n\n后来沈清弦才知道，从他答应协议结婚开始，霍聿川就没打算让他离开。\n\n他以为的交易，其实是男人一见钟情的羽翼。\n\n******\n\n随着原书剧情的展开，沈清弦越来越触及到这个世界的真相。\n\n穿书、主角、系统、反派……\n\n当旧尘因果被层层剥开，沈清弦才惊觉，原来他来到这个世界，从来不是意外\n\n要扭转的死亡命运，也不是他自己的\n\n沈清弦：等等，我一个炮灰，你让我拯救反派！？",
