    "score": "8.9",
    "category": "双男主",
    "abstract": "【双男主+穿书+甜文】\n\n（依旧自割大腿肉之作，全是作者本人的xp，大概是：表面温柔实则冷漠的腹黑大师兄攻×不想努力早早躺平的咸鱼受）\n\n牛马何时节一个意外，穿进了一本自己只读过简介，连小说名字都没记住的修仙文小说中。\n\n好在他一下就认出了小说的男主角，对方还是自己的亲亲大师兄！\n\n只是……就算认出了实力强悍的男主角又如何，何时节才懒得升级打怪抱大腿。上辈子他打工打到几乎快要猝死，这辈子他只想安然过着自己的咸鱼生活。\n\n不过…大师兄怎么离自己越来越近了啊喂！\n\n何时节：只是一个简单的贴贴！\n\n大师兄：嗯？五师弟想和我关系更亲近一点？\n\n何时节：只是简单的表达了一下自己对大师兄的崇拜……\n\n大师兄：嗯，他喜欢我。\n\n何时节：+_+？？？",
