    "score": "8.9",
    "category": "双男主",
    "abstract": "（双男主，穿书打脸逆袭，双洁，互宠，妥妥小甜文）\n\n昔日商界大佬赵平川惨遭破产，一夜跌落谷底，走投无路时，被还没入职的小程序员季然捡回了家。\n\n季然用一双狗狗眼看着他，说要养他：“赵总，我没有家人，你当我哥哥好不好？”\n\n赵平川本心如死灰，却被少年的温柔一点点捂热。\n\n他东山再起，一路逆袭，两人的日子越过越好。\n\n直到那年初雪，他将季然紧紧拥在怀里，嗓音低沉：\n\n“然然，不当哥哥了，我要当你的爱人。”\n\n长路漫漫，幸好是你。",
