    "book_id": "7494232680171588670",
    "book_name": "一不小心把龙傲天竹马钓成翘嘴了",
    "author": "琴岭",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/8191e65b60e6aa13ca7120dd614e2e9d~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=xJcMlNJ1E%2Bs%2FM6E%2FlzY8wmRcM%2Bs%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "（真人有声已出，已完结）【双男主+竹马+穿书+修仙+双洁HE】\n\n【人前龙傲天·人后老成忠犬攻×人前大美人·实则搞笑欢脱受】\n\n尤雨穿进龙傲天修仙小说，喜提三件套：\n\n穿错时间线、绑错角色卡、系统还掉线。\n\nok，天崩开局也没事。\n\n那就试试搞好关系，跟男主当兄弟吧！\n\n男主长大了，男主出息了，看他的眼神怎么也越来越奇怪了？\n\n以前是“莫挨老子”现在是“你跑试试”。\n\n-\n\n后来，尤雨真心夸赞：“燕哥实乃门派楷模！”\n\n燕万舟悄悄擦掉剑上的血，温柔一笑：“嗯。”\n\n尤雨真心感叹：“燕哥真是光风霁月！”\n\n燕万舟自然地揽住他的腰，温柔一笑：“嗯。”\n\n尤雨真心疑惑：“燕哥……你，呃，刚才是不是在非礼我？”\n\n燕万舟抚摸他的脸，凑得很近很近，“嗯。”\n\n-\n\n尤雨为好兄弟龙傲天两肋插刀，正准备事了拂衣去，男主拉住他，眼底翻涌着浓烈的情绪。\n\n“小雨，我喜欢你，你愿意……做、做我的道侣吗？”\n\n尤雨：啥，我们不是兄弟吗\n\n高大身影将他逼到角落，往日的温和荡然无存，泪珠滚落。\n\n尤雨惊诧地抬起头，男人脸上的神情，是自己从未见过脆弱的模样。\n\n“少爷，我不会走的，哪怕您恨我恨到骨子里，厌我厌到极点，我也绝不会离开半步。永远。”",
