    "author": "银河梦",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o87575b3ec4f105af32cbc1f7e04fb6fc~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=YUMaIIZW7fIwPnRveZ73JIZSzQg%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【嚣张跋扈嘴硬心软受vs美强惨温润腹黑后期直接发疯攻】【双男主+穿书】\n\n凌当归穿成了手术前追的小说中的恶毒反派，还有了个积分系统。\n\n只要他作恶多端、嚣张跋扈、作天作地，就能获得积分，如果达到一定积分，甚至可以重获自由。\n\n凌当归捋起袖子：干就完事！\n\n他勤勤恳恳地欺负此时因为真假少爷一事被逐出家门的美强惨主角陆观南，包括不限于嘴贱、让他罚站、抄书、劈柴、扫地等等。\n\n勤勤恳恳攒积分，终于！在这个世界重生了，十七岁！他自己的样貌！甚至连耳垂下的红痣都跟前世一模一样。\n\n凌当归过了八年逍遥自在的生活，直到上元夜，已成帝王的男主出现，一袭玄衣，浑身透着阴鸷危险，将他逼到角落里，发了疯似的一遍又一遍地咬着他耳垂下红痣。\n\n明明咬人发疯的是他，最后他还哭了。\n\n凌当归试图跟他讲讲道理，但后来腰酸背痛的他才想明白，跟一个忍了八年的人，是没有道理可讲的。",
