    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/c35f070f13cad02a328b7b3a1407d6d8~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=ptKifriwRCMRIUP4S47brTJfOtI%3D",
    "score": "9.6",
