    "abstract": "（完结）双男+双洁+穿书+修仙+小黑屋\n\n直男宁珂一觉醒来穿进了亲妹妹写的修仙小说里，开局就要作为反派被男主虐杀！\n\n还好关键时刻冒出了个系统，将其绑定，开启时间回溯，让他穿越到男主的过去，修复剧情漏洞，好给自己续命！\n\n于是，宁珂身披马甲，先后扮演起了传给男主狐火的“漂亮姐姐”；\n\n为救男主挖眼自爆的小师弟；\n\n帮助男主消除心魔的妖僧……\n\n等再回到正确的时间，马甲全部掉落。\n\n只见那曾经想要将他虐杀的男主，此时双眸猩红，哽咽着质问他:阿珂，你知不知道，我找了你多久？\n\n宁珂扯了扯被锁链铐住的手:QAQ不知道！不了解！小爷只想做完任务赶紧回家！\n\n*\n\n戏精吊儿郎当小太阳直男受X前期小白花后期求而不得疯批攻\n\n【多伏笔，1V1，受是绝美反派九尾狐，没心没肺爱玩爱闹，一心想回家；攻是养成系，成长流，前期可爱，中期黑化，后期爱而不得变疯批。】",
