    "abstract": "正文已完结：【双男主+穿书小甜饼+沙雕毒舌+病娇疯批+团宠年下】\n\n冷傲话少美强惨反派男二VS沙雕毒舌情商低纨绔男三\n\n沈钰手滑打开了一本女频言情文，结果穿进了文里同名同姓的舔狗男三，最后还被美强惨反派男二下令处死了全家一百零八口。\n\n为保小命，沈钰决定先下手为强。\n\n不过，这个后期牛逼闪闪的大反派男二，前期属实有点惨啊！\n\n正所谓：同是女主狗，相煎何太急。\n\n沈钰一时心软嘴贱，决定抱反派大腿，给反派送温暖，劝其莫做舔狗，一心一意搞事业。\n\n眼看一切发展顺利，他心中甚慰打算再给自己找个官配。\n\n岂料某人面色一变：“劝我回头是岸，为何转身娶别人？”\n\n沈钰：“？？？”",
