    "score": "9.4",
    "category": "双男主",
    "abstract": "【刚开分，评分会涨，放心食用】\n\n【双男主+双强+穿书+搞笑+1V1双洁】\n\n【嘴强王者·实力也很强·受X表面君子端庄·实则偏执占有欲极强·攻】\n\n晏阳生穿书了，发现自己穿成某文男主，吓得连忙找了个正直大佬抱大腿。\n\n当晏阳生身份暴露时，温润如玉端庄自持的少年持剑挡在他身前，挡住众人觊觎的眼光，声音低沉：此人由我来护。\n\n晏阳生两眼泪汪汪：果然我没抱错大腿！\n\n……\n\n很久之后，司望北将人堵在墙角，眼底是疯狂的占有欲。\n\n晏阳生瑟瑟发抖：到底从哪一步开始错了？\n\n……\n\n后来晏阳生终于明白了，搞修仙的谁不疯呢？\n\n来啊，大家一起疯啊！",
