    "abstract": "全文完结【双男主+穿书+师徒年下+双洁+死遁+救赎＋有强制（不喜慎入）】\n\n嘴上骂背地里宠的真直男师尊受X表面乖巧内心阴暗偏执反派年下攻\n\n温时卿熬夜猝死后穿进了一本修仙小说。\n\n系统说只要他扮演好所穿越的人物，就能复活回现实。\n\n温时卿接受了任务，却发现要扮演的竟然是男主和反派的变态师尊。\n\n表面和男主是师徒关系，背地里却疯狂恋慕男主。\n\n甚至为了消解欲念，找了个男主的替身，也就是反派，并在反派身上发泄自己对男主的各种阴湿念头，羞辱、折磨都是家常便饭。\n\n最后再为了救男主而死。\n\n温时卿不是变态，又想复活，于是只能钻系统空子，嘴上骂反派，行为上疯狂对反派好，主打一个刀子嘴豆腐心。\n\n这样过了几年，终于等到秘境之行，他完成最后一步，为男主而死。\n\n功成身退，得以回家。\n\n却被小系统找上门，告诉他，他死去后，反派疯魔了，实力还强大地超越了男主，如今正要灭世招魂，小世界岌岌可危，只有他能去救场。\n\n温时卿：？\n\n心软重回世界，不等温时卿说什么，便被反派打包锁进了宫殿。\n\n那个被他训斥了数年的反派，紧紧拥着他泣不成声。\n\n“师尊，求你，不要再丢下我",
