    "abstract": "已完结。【双男主+修仙+1v1+双洁+双强+青梅竹马+伪穿书+重生】\n\n【龙傲天醋王年上攻x深柜迟钝竹马受】\n\n沈崇鹤穿进《济苍生》这本龙傲天小说里，本想躺平当咸鱼，谁曾想一朝测验灵根发现跟自己相处了十来年的竹马竟是龙傲天主角!\n\n那能怎么办，宠着呗，反正他无系统无惩罚无强制走剧情的限制。\n\n本想像其他穿书者一样走个剧情的流程，但主线还没开始走，后续剧情就开始各式各样的崩。\n\n包括不限于：\n\n--狂炫酷霸拽的龙傲天变成了哭包小醋精？\n\n--到底谁是龙傲天？为什么你把天材地宝都送给我啊？\n\n--停停停，你是说无cp大男主龙傲天喜欢我，要跟我结为道侣？\n\n--等等，你说龙傲天是重生的？\n\n排雷：\n\n1.主受。\n\n2.身心双洁，互为唯一，双相暗恋。\n\n3.剧情有反转、反套路，要带脑子看，不无脑。\n\n4.伪穿书，受有隐藏身份。",
