    "abstract": "【双男主+主受+修仙+直男万人迷+穿书+群像】\n\n谢云鹤穿越了。\n\n系统说要他做助攻，帮助万人迷龙傲天找道侣。\n\n为了防止他被主角团的魅力俘虏，影响做助攻，还好心给他加载了一个颜值屏蔽系统。\n\n从此，美人身边绕，助攻他眼瞎。\n\n谢云鹤勤勤恳恳做任务，老老实实做助攻。\n\n龙傲天和正宫股在一起时，总是识趣地不做电灯泡。\n\n股票们找他聊天谈心的时候，总是不着痕迹地为龙傲天说好话。\n\n在龙傲天不开窍的时候，做他的情感导师。\n\n不知不觉，在谢云鹤的不懈努力下，他的身上插满了单箭头。\n\n某天，主角团们把他堵在了角落里，满脸通红地和他告白。\n\n谢云鹤：是不是有哪里不对劲？靠，别离我太近，有点光污染，眼睛要瞎啦！！！\n\n（PS：主角非常的钢铁直男，全书唯一的直男，大概率掰不弯，所以浑身单箭头。）",
