    "category": "双男主",
    "abstract": "【双男主+修仙+群像+双强+穿书+搞笑热血爽文】\n\n开挂装逼永远兜底沙雕骚包0 X修仙界第一天才冷脸萌天然呆1\n\n非典型帅0美1 强双箭头 主角团有挂不受委屈\n\n作为一个FPS（射击游戏）明星选手，谢未醒斩获无数冠军，一朝穿进万人迷修仙文\n\n以为是耀祖男频，没想到是恶俗BL\n\n人家当万人迷，他是旁边那个永远在憋坏水儿的恶毒反派炮灰\n\n遇到主角的舔狗挑衅，要挖他灵核\n\n谢未醒拿出弓箭，睁一只眼闭一只眼：来，跟你12个冠军的谢哥比瞄准\n\n明明五灵根天赋点满，却因为没有足够的灵力灌溉而变成众所周知的废物师兄\n\n谢未醒：一个bug是bug，一堆bug能work，我说能赢就能赢\n\n遇见原书中对主角爱而不得的战力天花板——龙族小太子，谈随亭\n\n看着对方哪哪都符合自己审美的脸、腰、腿……\n\n谢未醒：师兄，你芳龄几何啊？\n\n这是他老公他宝宝他心肝他亲爱的\n\n系统：等等，这是万人迷的男主之一……\n\n谢未醒：我管他七主八主，炮灰也有情，炮灰也有爱，我喜欢就是我的\n\n弹幕狂刷：大哥哥你是真心想当耀祖男频文主角吗，我怎么觉得有点不对劲呢？\n\n【弹幕体 网络热梗 任何极端控都请跑步离场 第一章末有详细排雷 不接受任何迎雷而上的写作指导】",
