    "category": "双男主",
    "abstract": "沉稳霸总攻vs穿书机灵受【穿书+1v1+双洁+甜宠】\n\n宋挽生了重病，抢救无效死亡。\n\n再一睁眼，他穿到了一本狗血虐恋文中，变成了那个跟他同名同姓，不断阻止男女主谈恋爱的反派搅屎棍。\n\n为了防止书中反派的悲惨结局落在自己头上，宋挽决定改邪归正。\n\n就像系统Siri所说，原主是作恶太多才会下场凄惨，只要他不阻止男女主谈恋爱，不针对男主，不就可以——\n\n可以个屁！\n\n人家穿书都是穿到开头或者中间，他都快直接穿到大结局了！\n\n原主坏事做尽，还给男主下药意图毁男主清白。\n\n要死！宋挽两眼一黑，直接一个百米冲刺，就算踹门也要把男主从放了催情药的酒店房间里解救出来。\n\n可是房门一开，一头栽进沙发里的宋挽傻眼了。\n\n什么情况？\n\n房间里中药的不是男主，怎么是女主她哥啊！！！",
