    "category": "双男主",
    "abstract": "【双男主+穿书+娱乐圈+沙雕甜宠+双洁】\n\n嘴硬大佬攻x沙雕作精受\n\n周舟睡前看了一本连载狗血耽美文。\n\n书中主角攻在一次饭局上遇到了和自己同名的小糊咖周舟。\n\n白月光出国后，为了应付爷爷，娶了小糊咖做挡箭牌。\n\n两年后白月光回国，主角攻为了尽快离婚去追白月光，甩下两亿补偿。\n\n可小糊咖却已经情根深种，下跪求他不要离开。\n\n于是他逃他追，他虐他卑微。\n\n看着同名小糊咖被渣男弃若敝履，周舟怒了，在作者评论区怒骂八百条。\n\n一觉醒来，周舟穿书了……\n\n想了想即将拥有的两个亿……问题不大！\n\n他喜欢温柔白月光，那自己就做作精黑狗血，争取早日喜提两亿分手费。\n\n可是谁能告诉他，他每天作天作地，渣男看他的眼神怎么越来越黏糊了。\n\n渣男的底线在哪里？两亿在哪里？\n\n谢澜亭觉醒了，发现自己身处的世界是一本小说，而自己竟然是个渣男？\n\n觉醒后的谢澜亭想要摆脱剧情控制和小替身离婚。\n\n可为什么看着每天叉腰撒泼的小替身越来越喜欢了？\n\n剧情崩了以后，白月光提前回了国。\n\n谢澜亭看着小替身手机上的搜索记录沉默了……\n\n[老公的白月光回国了，如何让他们快速破镜重圆]\n\n[老公给的分手费需要交税吗]\n\n[两个亿存到银行有多少利息]\n\n谢澜亭：“？”",
