    "author": "绿夏新枝",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o2478aaf4a357278daac019871300a592~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358555&x-signature=OUDX2XZhVr8MIupABtU74fCfcIA%3D",
    "score": "8.3",
    "category": "双男主",
    "abstract": "（评分刚出，会涨）【双男主+双洁1v1+甜宠】\n\n【钓而不自知自以为直男受VS一秒忘本又争又抢绿茶攻】\n\n宋彻一觉醒来发现自己穿书了，穿成一本无脑狗血虐文里对男主强取豪夺的恶毒大反派。\n\n穿来第一天，就在自家地下室和被五花大绑的男主对上视线……\n\n本想着只要不招惹男主就能苟住性命，奈何剧情之力过于强大，不招惹不行。\n\n没办法，宋彻只能将男主顾南川留在身边刷刷好感，顺手帮一把。\n\n-\n\n可情况似乎变得奇怪起来了……\n\n谁能告诉他，为什么本该对原书官配一见钟情的顾南川会将人视为情敌？\n\n在宋彻又一次试图给二人制造机会时，被顾南川压在了门边，委屈地质问道：\n\n“是我对你的喜欢表现得还不够明显吗？宝宝，正常朋友不会像我们平时那样的……”\n\n顾南川俯身贴近，宋彻这才惊觉不对劲……\n\n-\n\n顾南川意外被绑，本想鱼死网破，却在见到那人的第一面时秒速忘本。\n\n他主动沦陷，却发现那人似乎真的不喜欢他……\n\n顾南川：不是对我有意思吗？不是吗？\n\n哈哈哈原来不是（破防）\n\n-\n\n意外得知宋彻得了怪病，顾南川心甘情愿当起了不知道宋彻发病时肯不肯要的解药；\n\n他本以为宋彻对他没有意思，直到宋彻发病时性情大变，十分恶劣地将他一把推到……\n\n-\n\nPs.发病前后均为同一人",
