    "score": "8.2",
    "category": "双男主",
    "abstract": "【双男主｜ABO | 双洁 | 双重生｜养崽｜偏执追妻】\n\n扮猪吃虎疯批大佬攻 × 贪财惜命绝美美人受\n\n前世顾舟欠了三千万巨款，绝境之中捡回个心智十岁还乖巧听话的顶级Alpha。\n\n少年温顺、漂亮、任他拿捏。\n\n他贪念上头，死缠烂打，妄图攀高枝还债翻盘。\n\n结果惹怒蛰伏疯批，惨死收场。\n\n一朝重回捡到痴傻大佬的这天。\n\n顾舟彻底幡然醒悟。\n\n远离明烛南，远离豪门纷争，保命搞钱，安稳度日！\n\n疯批大佬，谁粘谁死！\n\n这一世拿钱、拉黑、连夜跑路。\n\n三年后重逢。\n\n昔日温顺少年彻底黑化，阴鸷偏执，独占欲蚀骨。\n\n死死扣住顾舟手腕，眼底翻涌疯狂：\n\n“怎么不拼命纠缠了？还避我如蛇蝎？”\n\n顾舟心有余悸：“贪财好色会死的很惨……”\n\n看着顾舟身边软乎乎的小奶娃，不可一世的京圈大佬放低所有身段，小心翼翼试探：\n\n“单亲家庭不利于孩子成长，你带孩子太辛苦了……”\n\n顾舟不耐挑眉：“直说，你想干什么？”\n\n明烛南眼底盛满偏执深情，轻声诱哄：\n\n“介不介意，让孩子多个后爸？”\n\n“我有钱有颜有实力，只宠你，只疼崽。”\n\n圣人藏私心，烂人动真情。\n\n甜宠文，入股不亏。",
    "word_number": "321403",
    "chapter_count": 145,
    "last_chapter_title": "145、爸爸喜欢小钱钱",
    "creation_status": "连载中 (Đang ra)",
