    "book_id": "7512409078920907800",
    "book_name": "霍爷，您的闯祸精重生回来了",
    "author": "七点钟",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/455405243b1f3967b4db922622876026~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358557&x-signature=lvKeXhUu1QCDrCZzAq%2F%2BwP7rLRk%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【成熟稳重大佬攻V惹是生非炸毛受】HE+酸甜+双洁+撩宠+甜虐\n\n凌泽予是被害死的。\n\n回顾半生，最恨两个人。\n\n一个是害死他的，另一个是无法宣之于口的名字，霍渊。\n\n他是霍渊豢养在身边的一条狗，招之则来挥之即去，想要就要，不想要就弃。\n\n一场车祸毁了自己一张脸，所以霍渊给了他大笔分手费，让他滚。\n\n他恨死霍渊了，日日夜夜诅咒他。\n\n可濒死之际，真相却如淬毒的匕首穿心脏\n\n对方说：谁都有资格恨霍渊，唯独你没有\n\n那场车祸，他和你可是同乘一辆车。\n\n为什么在你醒来之后他一面都不肯见你？\n\n为什么在霍家访谈之中不曾露面？\n\n又为什么会给你一笔天价分手费？\n\n你可有想过？\n\n重生后。\n\n管家慌慌张张：霍爷不好了！凌少爷他赖着霍家不走了！\n\n霍渊：“……”\n\n管家满头大汗：“霍爷不好了，凌少爷一晚消费上千万没付钱！”\n\n霍渊眼皮都没抬一下：“给他送钱。”\n\n管家声音发颤：“霍爷，凌少爷跟人打起来了！”\n\n霍渊终于放下文件：“……保镖过去，护着他。”\n\n“可…可现在是少爷在打别人啊。”\n\n霍渊沉默片刻，指节轻叩桌面：“他这么做肯定有他的道理。去善后。”",
