    "abstract": "（重生+双男主+双洁+权谋古言+欢喜冤家）\n\n上辈子父兄战死，楚南池提刀上马，凭着手里一把剑踏过尸山血海为父报仇。\n\n却在功成名就那天，听到了事情的真相。\n\n原以为的真情实感，没想到却是虚情假意。\n\n他满腔怒火，和敌人同归于尽。\n\n这辈子，他要护住父兄，护住南平王府，护住所有他爱的人。\n\n如果只有见血，才能护住自己在乎的人。\n\n那他不介意血流成河。\n\n只是，这个哭着嘤嘤嘤求抱抱的男人是哪来的？",
