    "author": "卿非",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/898345bf082de5f5ccbc81957da5003d~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358557&x-signature=PavxSGZACGhowgYa8ryOjWZleGk%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "双男主，1v1，双洁，甜宠爽文。\n\n上辈子末世，姜年被囚禁在地下室，丧尸潮来临时被家人抛弃，最后惨死在赶来救援的前任哥程境怀里。\n\n再次睁眼，姜年重生回到末世前半个月，为了苟命当即决定厚脸皮吃回头草。\n\n首先，跟前任哥借点钱囤物资：\n\n姜年：“程境，你能不能借我点钱？”\n\n程境：“点名道姓的跟我借钱，你怎么不让我跪下！”\n\n姜年：“境哥我错了……”\n\n再次上位成功后，他安心抱紧前任兼现任哥大腿开始末世躺平生活。\n\nPS：\n\n看文带入角度不同观感就不一样，尊重他人看法尊重作者设定，不要过度带入现实三观去共情。\n\n喜欢就看，不喜欢就弃，自己的标准自己用，不要恶言相向。\n\n作者写文不易，请高抬贵手别恶意差评，谢谢。\n\n祝大家都能看到自己喜欢的小说。",
