    "score": "6.8",
    "category": "双男主",
    "abstract": "【双男主+重生+破镜重圆+追妻火葬场+先虐后甜+双洁+HE】\n\n【嘴硬心软深情攻vs家道中落病弱受】\n\n◎重生前：顾景川以为余文岁害死他的母亲后畏罪潜逃，扬言要将这个人碎尸万段，不曾想，重逢时却看到余文岁带着五岁的侄子过着吃不饱穿不暖的日子；\n\n◎真相大白之际，余文岁被顾景川亲手送到敌人的手上，残害至失明，一个人孤零零冻死在荒山野岭之中。\n\n曾经恨不得余文岁去死的男人，如今只想追随爱人的脚步……\n\n◎重生后：重活一次，顾景川将这个宝贝紧紧抱在怀里，这一世，一定会好好爱他。\n\n——宝贝，我带着虔诚的心，来赎我前世的罪",
