    "book_name": "冷暴力五年，他死了你殉什么情？",
    "author": "酒酿核桃",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/04876947fc54298e6092d81ea8dff06a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358557&x-signature=o61k2hx7SbssrdMUA4X4hdjtRzk%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "【双男主·主攻·双洁·重生·酸甜·救赎·追妻火葬场】\n\n刚开分会长哒～脑婆们❤️\n\n蒋逾大学期间在会所兼职，被自己帮助过的被霸凌的同学谢岑下药灌醉，强迫他发生关系，还用家人威胁必须要跟他在一起。\n\n蒋逾被迫跟谢岑在一起五年，五年间他冷脸相对，面对谢岑所有付出都无动于衷，对当初的事更是耿耿于怀。\n\n甚至没有给过谢岑一个好脸色。\n\n一个普通的清晨两人缠绵结束，谢岑搂着他问。\n\n“阿逾，可以吻我的唇么？”\n\n蒋逾没有理会，冷冷看了他一眼出门。\n\n中午在公司楼下吃饭，却看见电视上通报一则消息。谢岑突然跳楼身亡。\n\n谢岑死后蒋逾才醒悟过来，他早就爱谢岑爱到骨髓里，只是过不去心里的坎，绝望之际却意外得知当初的药的另有其人，那杯是下给谢岑的，只是被蒋逾不小心喝了。\n\n谢岑初中开始就患有抑郁症，蒋逾在谢岑的独栋别墅里看到他藏在抽屉里的报告。\n\n谢岑死后将名下财产全部留给了蒋逾。\n\n蒋逾得知所有真相崩溃不易，在谢岑去世的第三天在两人第一次看日出的地方殉情。\n\n——·\n\n蒋逾再次睁眼竟然回到了校园，回到了谢岑被霸凌之前，重来一次蒋逾决定救赎爱人。\n\n探寻爱人藏在心里那些没告诉他的秘密。\n\n也要为那五年冷暴力的赎罪。",
