    "abstract": "【双男主+重生+甜宠+拉扯+死对头+HE】\n\n·水火不容×难舍难分√\n\nK市人人都知道，沈然和程翊是死对头。\n\n沈然看上一瓶酒，转眼就被程翊截胡。\n\n沈然被他人表白，程翊嘲讽他眼光太差。\n\n如此种种让沈然坚信，这个腹黑毒舌绝对是他的一生之敌！\n\n----\n\n然而程翊的毒舌竟是真理，\n\n被渣男男友出卖，沈然被稀碎地塞进行李箱。\n\n灵魂飘荡，他亲眼目睹，那个他一直视为死对头的毒舌总裁程翊，竟为他不惜自毁前程，手刃仇敌。\n\n原来程翊早已把他放在心尖默默守护，他却一直把对方视为水火不容的人!\n\n----\n\n得已重生，沈然誓要试试程翊的那张毒嘴到底是什么味道。\n\n“尝过了，怎么样?”\n\n“是有毒。”沈然一脸深情:“你对我下了爱情的毒。”\n\n“……少看点网上那些土味爱情梗。但我允许你可以再尝一下。”",
