    "author": "墨酒云卿",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2oc87c3ac310201efecbfa808b5b9f3701~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358557&x-signature=WF1w9WdH0eUjp85piGM5kZlM4bw%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "【温柔宠溺大佬攻+傲娇作精小少爷受+双洁+HE】\n\n谢遇死了。\n\n孤身一人死在厉南沉送给他的豪华大平层。\n\n火光冲天，临要被烧死之际，他想的不是求生，而是追随那个男人而去。\n\n他这辈子，六岁开始就跟在厉南沉身边，一直到23岁死亡。\n\n外界传言他是厉南沉的小情儿，是他养在身边的玩意儿。\n\n他不在乎，因为厉南沉把那些人都解决了。\n\n厉南沉护了他17年。\n\n前世他爱而不自知，叛逆期时还因此调侃，撩过那个老男人，不知死活的跟人表白。\n\n被厉南沉按着狠抽了一顿。\n\n那时他也不知道，他的反复试探，一步一步的想要得寸进尺，到底是为什么。\n\n看着厉南沉，克制隐忍，他反而觉得自己胜利了，在厉南沉面前扬起自己的小爪子，沾沾自喜。\n\n最后厉南沉为救他而死，那时的锥心之痛，才让他知道，那到底是为什么。\n\n明白了，厉南沉能容忍他那么多年，在他心尖上反复横跳，到底是为什么。\n\n他恨自己的迟钝，更是服气老狐狸这么多年的隐忍。\n\n这一世，他到是要看看厉南沉这只老狐狸，还能不能像以前一样，做忍者神龟。\n\n他不是前世的谢遇，这一世他要做，厉南沉怀里的那条谢小鱼。\n\n他不要厉南沉为他牺牲，此生只想与他共白头....",
