    "score": "8.0",
    "category": "双男主",
    "abstract": "【评分刚开，后续会涨！】【双男主+abo单攻重生+偏执黏人霸道攻+冷戾A×软萌体弱O+暗恋成真+追妻火葬场+双洁+先婚后爱】\n\n顾郁亓重生了，回到和虞清初新婚次日。\n\n前世他高冷寡情，笨拙又冷漠，弄丢了满心都是他的软萌老婆，抱着他冰冷的身体，悔恨至死。\n\n重生新婚夜，看着被他标记、怯生生满眼慌乱、张口就道歉的老婆，他彻底破防。\n\n从此，帝国最冷漠的少将，彻底变了。\n\n不再冷淡疏离，化身偏执黏人恋爱脑。\n\n占有欲拉满，宠溺无度，满眼满心，全是他的老婆。",
