    "score": "8.7",
    "category": "双男主",
    "abstract": "【双男主+重生+修仙+张扬恶毒自私美人受VS带点痞气傲慢黑心肠龙傲天攻】\n\n曲英本是受尽宠爱的曲家少主，在父亲死后一切都变了，他吃够了苦头，知道了修为的重要，想要拼一把吞服丹药突破结果爆体而亡。\n\n老天爷给了他机会再次回到父亲还在的时候，他如愿以偿杀了上辈子欺辱他的人，可是父亲的危机还在，他也依旧是资质平平的双灵根。\n\n但那又怎样，老天爷是眷顾他的，让遇到了上辈子在修仙界大放异彩的天才。\n\n所谓的天才，不过是个披着张正直人皮其实心眼都黑了的好色之徒，曲英看出来了他很喜欢自己这张脸，为了变强，他什么都可以利用，包括自己这张脸。\n\n训狗嘛，他擅长，谁知道这只“狗”的胃口越来越大...\n\n一开始\n\n曲英：“宫文山，秘境里的那件防身法宝可不可以给我。”\n\n宫文山：“你别太贪心。”\n\n曲英出卖美色，曲英得到。\n\n后来\n\n曲英：“宫文山，我...”\n\n宫文山：“只要给出我满意的奖励，要什么都可以给你。”\n\n曲英生气，曲英得到。",
