    "score": "6.2",
    "category": "双男主",
    "abstract": "【双男主+受重生+总裁+追妻+双洁】\n\n前世，段律川和竹马司珩在一起五年。\n\n他满心欢喜，一直沉浸在这段关系中无法自拔，却又隐隐约约觉得不对劲。\n\n后来他听到司珩跟别人说：“当初是为了报恩才和他在一起的。”\n\n段律川泪流满面，却来不及追问这一切的时候便坠入大江，车毁人亡。\n\n意外重生，段律川回到了司珩告白前几天。\n\n重来一次，他才不要没皮没脸的跟着司珩呢！\n\n他拒绝两家的合作，切割双方的利益捆绑，斩断自己这些年对司珩的情谊。\n\n把自己归放在朋友的位置。\n\n直到有一天，司珩发现他在段律川那里的所有特殊待遇全都消失了。\n\n看到自己没有了热情的拥抱，属于自己的房间被占领，吃饭不会迁就自己的口味，更没有每日的分享……\n\n一向沉稳自持的司珩酒后红着眼看着段律川喃喃道：\n\n——“小川，你在冷落我”\n\n——“小川，你在欺负我。”\n\n——“小川，我让你生气了吗？如果是，我道歉好不好？”\n\n——“你不要看别人，你理理我好不好？”",
