    "score": "9.4",
    "category": "双男主",
    "abstract": "【重生/甜宠/死对头/互撩/拉扯】\n\n上一世，沈榆一直把联姻对象谢宴州当死对头。\n\n可众叛亲离时，只有谢宴州，不厌其烦照顾他，将他捧在手心。\n\n他死后，谢宴州为他报仇，葬身火海。\n\n*\n\n重回和死对头确定联姻那天。\n\n沈榆一脚踹开小人，毫不犹豫扑进死对头怀里——\n\n“谢宴州，带我回家。”\n\n*\n\n谢宴州暗恋沈榆多年，为了吸引他的注意力各种挑衅，终于把自己作成死对头。\n\n本以为这辈子没机会，沈榆却忽然变了性子，疯狂撩他。\n\n谢宴州眉头一皱：天底下怎么会有这种好事？陷阱！一定是陷阱！\n\n他发誓绝对不能让沈榆轻易得逞！\n\n可后来，有人亲眼撞见——\n\n夜色浓郁处，谢宴州扣着沈榆手腕将人压在怀里，咬牙切齿地说：\n\n“婚戒戴上，老子随便你玩。”",
