    "abstract": "【双男主+重生+日常恋爱甜撩宠+强强+双洁】\n\n碧落宫宫主封谕翻车了。\n\n不仅被人抢了杀人灭门业务，还被迫背了黑锅。\n\n就连原来的香软玉，都变成了夺命剑。\n\n追杀、跳崖一条龙服务，还附赠了重生险。\n\n咋的，一次不够，还想再来第二次？\n\n封谕抱着云铮一撩眼。\n\n美女都是断肠草，不如本座的影卫好！\n\n人家的影卫，别想杀我主上！！\n\n本座的影卫，别想抢我主上！！\n\n人家的影卫，主上今晚选哪个美姬？？\n\n本座的影卫，主上今晚我就是美姬！！\n\n咳……\n\n谁说木头影卫不够香？\n\n只要主子手段强，忠犬撩成小野狼~\n\n又美又撩又会宠的江湖霸主 X 又冷又强又忠犬的贴身影卫\n\n咱就主打一个日常甜宠谈恋爱，顺便重生复仇杀坏人~！",
