    "category": "双男主",
    "abstract": "【双男主+双强+重生+双洁+甜宠+HE】\n\n心狠手辣西厂督主攻x外柔内刚腹黑太子受\n\n燕承昱，从出生起就被封为太子，一生顺风顺水，历朝历代的太子所面临的困难他完全没有。\n\n可他后来却被自己一向疼爱的弟弟所陷害，因谋反之罪入狱，最后死在了狱中，发现自己高兴的还是太早了。\n\n他肉身虽死，灵魂却还在，他看见对他慈爱的父皇对他的死漠不关心，温柔华贵的母后说他终于为弟弟让路，一起长大的弟弟嘲笑着他的愚蠢，原来偌大一个皇宫里竟无一人真心待他。\n\n在心灰意冷之下，他却看见那位令人闻风丧胆的西厂督主为他报仇，手刃仇敌，血洗皇宫，把他的尸体带走安葬，在他的坟前落泪。\n\n燕承昱看着他的背影，只恨自己识人不清。若有来世，他一定要问问他，他一向与他不合，为什么要帮他报仇……\n\n重生后：\n\n燕承昱：戚砚，你为什么要帮我？\n\n戚砚：臣只是想为殿下分忧。\n\n燕承昱：是么，可孤怎么觉得你喜欢我呢？\n\n戚砚：殿下，臣不是……\n\n燕承昱指着戚砚的心口的位置，可它在说，你就是喜欢我。",
