    "abstract": "【双男主+万人迷+穿书+一点娱乐圈+1V1+双洁+沙雕】\n\n季余穿成一本娱乐圈爽文里同名同姓的炮灰兼舔狗。\n\n女配攀高枝他当垫脚石。\n\n女配搞女主他背锅。\n\n女配出事他先死。\n\n季余：……剧情你高贵，我走！\n\n为了不搭上自己的小命，季余撂担子跑了，决心远离所有剧情人物，继续苦逼的打工还债生涯。\n\n好在老天似乎待他不薄，给他送了个财大气粗的男朋友。\n\n就在季余犹豫着要不要躺平的时候，系统姗姗来迟。\n\n【我是编号9527，你可以称呼我为系统，作为小说前期的重要炮灰配角，你需要根据小说剧情完成你工具人的作用。】\n\n【当前剧情是女配唐意打算找人散播对女主不利的谣言，请宿主配合女配，完成这段……剧情！！！！】\n\n系统冰冷冷的话还没说完，就被眼前画面震惊得数据乱窜。\n\n本该围绕在女配身边当一条资深舔狗的季余此刻正依靠在一个男人肩膀上。\n\n【你怎么会跟男主的表叔在一起！！！】\n\n角色由真人主播演绎：御龍饰卞兆伟，铃紊墨舟饰小陈，沐思漓饰唐意，咸鱼邱饰袁盛和，柠檬冲浪饰季余",
