    "score": "9.3",
    "category": "双男主",
    "abstract": "（已完结）【双男主+穿书+末世+丧尸+异能+双强+金手指+甜到爆炸+醋王占有欲+快节奏+系统+双洁1v1+HE】\n\n简郁白穿书了，穿进了一本末世文里，被系统要求完成任务，改变男主死亡的结局。\n\n简郁白：无语，谁爱上谁上。\n\n系统：【如果任务失败，惩罚为：死亡。】\n\n简郁白：我行我上！\n\n为了不被系统嘎掉，简郁白下定决心，要拯救男主于危难。\n\nS级异能、双异能者……不断出现的福利让简郁白表示：诶，好像装到了！\n\n只不过在男主身边待的时间越长，简郁白越是觉得，这个男主好像有点奇怪。\n\n“简郁白，你是我的，听话，不许对着别人笑。”\n\n瞧见男主搂上自己的腰，简郁白觉得与其救男主，倒不如先救救自己。",
