    "author": "暴富加发财",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/60ee5eb7b4cb8ac9cb4895bf3f209b92~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358559&x-signature=IYHmib2XiAlUNvla5d4NXdu0%2Bq8%3D",
    "score": "8.8",
    "category": "双男主",
    "abstract": "【双男主+系统+暴富+老套路打脸文】\n\n靳阳突然被一个暴富系统绑定了，本来以为是天降祥瑞，结果没想到是给他拉了坨大的。\n\n谁家暴富系统花不完钱还要被抹杀啊？\n\n这简直太强人所难了吧～\n\n靳阳大学毕业后面临着毕业即失业的困境，幸好突然天降暴富系统。\n\n本以为可以就此躺平，没想到还要做花钱任务？\n\n天哪，不是吧，花个钱怎么这么难呢？",
    "word_number": "538313",
