    "score": "8.4",
    "category": "双男主",
    "abstract": "【双男主+系统+双洁】\n\n【前期讨厌受，后期疯狂吃醋的傲娇攻付昀卿×被攻反复无常的厌恶值气到摆烂的受江予笙】\n\n江予笙在公司午休遇地震，同事拉其往消防通道逃生被挤下楼梯，系统8号带其到编号8577的世界，任务是降低男主付昀卿的厌恶值，江予笙一查，天崩开局，99.5%的厌恶值，系统，这降不了啊！",
