    "author": "飞天带鱼",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/9636cfdef067ece14b64cb9e9f14027e~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358559&x-signature=meDTwxab1PZBHyQHFG7lRTNL1W4%3D",
    "score": "8.1",
    "category": "双男主",
    "abstract": "双男主 神豪 主攻 1V1 大佬 年下\n\n可奶可狼直球攻VS外冷内热年上编剧受\n\n大学刚毕业两年的陆鹤舟没想到自己有一天也会遇到，老板卷钱跑路公司倒闭这种只会在社会新闻里看见的事。\n\n被迫失业，陆鹤舟还来不及为未来的生活发愁，却又在回家路上一跤将自己摔了个踝骨骨裂。\n\n靠着自己之前工作存下的积蓄，勉强度过了养伤这段日子的陆鹤舟刚打开招聘网站准备找工作时，脑子里突然想起了系统的声音……\n\n陆鹤舟：“你是说我每花一块钱就能获得一万块现金返现？”\n\n系统:“是的，宿主”\n\n陆鹤舟:“那你还说自己不是神豪系统！”\n\n系统:“系统是消费返现系统不是神豪系统！”\n\n陆鹤舟:“哦～～我悟了！！！”\n\n系统:“你到底悟了些什么！！！”",
    "word_number": "503259",
    "chapter_count": 218,
    "last_chapter_title": "婚前焦虑了",
    "creation_status": "已完结 (Hoàn thành)",
