    "book_name": "穿成反派被气运之子看上了",
    "author": "我不是晓七",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1d3bee5a73a7aaf08148c40e677e0666~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358559&x-signature=io6TewTyLcSXc02Jv7sISjTgjk8%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "(全文已完结。)\n\n注意：本书为男频文风的双男主文！介意的朋友慎入！\n\n【双男主】【系统】【反派】【单箭头】【友情变质】【有糖！】【微群像】\n\n穿越玄幻世界成为魔道少宗主，陆沉觉醒反派自救系统。\n\n本欲脚踩气运之子、迎娶各族圣女，走上人生巅峰！\n\n却被系统告知自己是这个世界的最终反派，将来注定会成为主角踏脚石，被主角噶掉！\n\n陆沉：“什么！我竟然不是主角？”\n\n系统：“宿主是这个世界的铁反派，本系统致力于帮助宿主达成反派自救，只要完成帮助主角成长的任务，刷满主角好感度即可避免死亡结局。”\n\n别人的系统帮助宿主走上巅峰，陆沉的系统逼着他去做舔狗刷好感度！\n\n为了保住小命，陆沉决定全力跟主角搞好关系。\n\n谁知随着好感度逐渐增加，主角看陆沉的眼神越来越不对劲。\n\n谁家主角喜欢一整天盯着反派的脸傻笑啊！\n\n陆沉：主角你放在我腰间的手能不能不要乱动啊喂！\n\n多年以后当主角成为正道魁首，发现魔道魔君竟是对自己如父如兄的陆沉时，他拿剑的手微微颤抖：“这可是我的挚爱亲朋，手足兄弟啊！”",
