    "author": "趁风不注意",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/c168a815cadf3dff97d6f1a72c1071a4~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358559&x-signature=YvL5Z6vyQqLzR4jaiZyQrERxyms%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【无女主，双男主！！！系统，甜宠】\n\n顾涣将一生贡献给了国 家，最后死于辐射。本以为会进入天堂，结果没死成 ，绑定了一个红娘系统，致力于帮他寻找灵魂伴侣。\n\n不过，这个灵魂伴侣确实合他心意，怎么办？\n\n好好宠着呗。\n\n科研大佬vs娱乐明星\n\n蛇兽vs兔子\n\n大师兄vs小师弟\n\n农门状元vs丞相公子\n\n锦鲤vs知青\n\n软饭雄虫vs将军雌虫\n\n……\n\n不按顺序，按灵感\n\n(不霸总，不冷酷，甚至有点搞笑)",
