    "book_name": "替嫁炮灰他有矿！",
    "author": "罐头不好吃",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/f3d374eea37fe6fe7066bd1469ad941f~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358559&x-signature=ecK56beDOo1iX7qzfUE8a811%2FS0%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【双男主+系统+金手指+外挂+逆袭】\n\n1.洛北时从小就被养父母万般嫌弃，亲生父母对他更是只有嫌弃和不耐。\n\n在他人眼里，洛北时永远都是一个嚣张跋扈，只知道欺负人的鸠占鹊巢的假少爷。\n\n无论他怎么努力，都是用来衬托真少爷的对照组，得到的没有认可，只有嘲讽。\n\n2.就在他20岁后，养父母的公司遇到了问题，又不舍得亲生儿子，于是将他送去了霍家。\n\n洛北时想离开，不料却在途中觉醒了！还拥有了一个外/挂般系统！\n\n因为觉醒了，他也知道了他生活的世界，是一本书的世界，而他连配角都算不上。\n\n可现在！他是拥有了挂的人！那些亲情？他统统不需要！只有变强和偶尔咸鱼才是王道。\n\n3.京都，所有人都不看好他洛北时，可偏偏洛北时去了霍家后，像是换了个人，对霍辞霄以外的人都毫不在乎，甚至连面都难见到。\n\n4.后来，养父母后悔了，没用。\n\n亲生父母和哥哥们知道真相后，恳求洛北时原谅，依旧没用。\n\n5.霍辞霄是一个植物人，昏迷一年多了，有天，他的意识恢复了，但是却动不了，身边还多了个人？哪来的小话唠？",
