    "score": "0",
    "category": "双男主",
    "abstract": "【双男主｜偏执大佬攻谢临渊×桀骜野性受黎骁｜强强拉扯｜宿命博弈｜1v1 HE】\n\n野性少年，雨夜把大佬捡回出租屋，莫名被顶级大佬盯上。\n\n清冷腹黑年上攻步步为营，不动声色将年下桀骜少年圈入自己的领地。\n\n表面平淡相处，内里极限拉扯，都以为自己在演戏，偏偏动了真心。\n\n满心抗拒逃离，却次次沉溺温柔掌控。\n\n原来从相遇那一刻起，他就早已成为大佬此生唯一，再也无从逃离。",
