    "author": "一颗团子呀",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/ba3515c90885582f49f5d6ccaa352e0e~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358560&x-signature=fSVgDeSeDUWEOe6GwyCMJGIsDAM%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "【双男主+烧攻+清冷受+死对头+双洁1v1+年下双强】\n\n【清冷美人魅惑受X烧里烧气张扬肆意攻】\n\n丞相府嫡子·沈暮雪与将军府独子·谢燃仿佛就是天生的死对头。\n\n幼时在茅房初见，沈暮雪就被谢燃认成了女孩子，谢燃两眼放光，追着说：“长大了我娶你当媳妇吧。”\n\n沈暮雪：“……”\n\n眼瞎、有病。\n\n抬脚就给人踹湖里。\n\n—\n\n长大后，谢燃扒沈暮雪衣服？沈暮雪就把人摁马粪里。\n\n此刻，谢燃发现沈暮雪心口惊现神秘数字【1】，紧接着数字变成了【0】\n\n谢燃：“！”\n\n这究竟是什么东西缠上了沈暮雪！！！\n\n—\n\n后来……\n\n谢燃：我拼命勾引！！！\n\n沈暮雪：他在挑衅我。",
