    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/e8cbd0daf6274c868a06079be4e42d8d~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358560&x-signature=sUbCa%2FnJeHudypKGZNEnkKx0SyI%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【直球受VS宠溺攻】\n\n【双男主+双洁+甜宠+暗恋成真+双向奔赴】\n\n林序然是林家没什么存在感的二少爷，从小体弱多病，安静话少，他第一次见到斯文矜贵的霍祁宸，就被吸引了目光，第一次生出了念想。\n\n后来，林序然鼓起勇气想要走近霍祁宸，却被那人轻描淡写的一句“恐同，勿扰”逼退……\n\n京市豪门霍家的唯一继承人霍祁宸，斯文矜贵，温文尔雅，但手段狠绝，说一不二，让不少心生爱慕的人望而却步。\n\n一次好友聚会，有人提了一嘴林家那位体弱多病的二少爷，霍祁宸随意吐出一句，“真难养。”\n\n后来，霍总每天捧着医书研究药膳，嗯，难养，所以要好好养！\n\n*\n\n林序然（受，23岁）&霍祁宸（攻，28岁）\n\n林序然的视角下暗恋成真，得偿所愿；霍祁宸的视角下见色起意，甘心沉沦。",
