    "abstract": "（双男主+电竞+强强+甜宠+双洁）\n\n沈秋辞作为一代顶级代练，一朝猝死穿进书里！\n\n作为老实本分的当代好青年决定重操旧业却被书中大魔王一把抓住。\n\n“我缺个中单，就你了”\n\n“什么就我了，我们两个可是敌人！”\n\n后来，敌人变队友，队友变情人。\n\n全球比赛结束那天，有人在后台看见堂堂国服第一FMVP打野堵着他队伍里的小中单，语气暧昧，撒娇意味十足。\n\n“宝贝，说好的，冠军归你，你归我！”\n\n（正文已完结）",
