    "score": "8.6",
    "category": "双男主",
    "abstract": "【微病弱腹黑绿茶反差哭包1x清冷温柔宠攻0】\n\n【双楠➕一见钟情➕双强➕快节奏➕受宠攻】190x185\n\n傅氏和谢氏的联姻并没有人觉得意外，但所有人都认为他们两个没有任何感情可言，一开始就连正主也是这样认为的。\n\n…\n\n直到有人撞见在外杀伐果断的傅总在内因为自家伴侣不给他吃小蛋糕而闹小脾气，世界观都要爆炸了。\n\n同样，谢总对自家伴侣的眼泪完全没有任何抵抗力（原则性问题除外，例如受伤！！！）\n\n从订婚宴后的那个抱抱后，某人就彻底沦陷了～",
