    "author": "暴走野猪头",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/3761f23ef6ff4b60e0fc53dcbe1f21eb~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358560&x-signature=aubtqVLSbSYdvX7bsAkhinyD6qU%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "【双男主+EA+双强+双洁+死对头】\n\n（腹黑闷骚爹系Enigma VS 暴躁傲娇少爷Alpha）\n\n作为帝都唯二最受omega追捧的alpha，时宴和陆京辞做了整整二十二年的死对头，从娘胎里打到大的那种。\n\n所有人都以为两人势如水火的关系永远不会有所改变。\n\n直到一次意外，事情逐渐变得怪异起来。\n\n双方的好友发现，有时宴在的地方，陆京辞总会在。\n\n然而通常情况是这样的。\n\n时宴：“陆京辞你能不能离我远一点？！”\n\n陆京辞：“远不了一点。”\n\n-\n\n时宴一直以为陆京辞讨厌他，就像他讨厌陆京辞一样。\n\n直到有一天，时宴无意中看到了他的日记本，才知道某人原来对他早就有所图谋。\n\n-\n\n“世界无边无际，宇宙浩瀚无垠，可在这样的太阳月光，山川河流间相爱的我们，胜却万千美景。”",
