    "score": "9.1",
    "category": "双男主",
    "abstract": "【双男主+ABO+穿越+双洁+强强】末世大佬陆忱来到abo世界收集反派值，可一天晚上没注意，被房间里冒出来的alpha咬了一口。\n\n他没在意，不就是在后脖颈啃了一口吗？反正不是丧尸啃的就行。\n\n很快他接到消息，自己和帝国太子信息素匹配值100%，要去帝都星。\n\n可是没人告诉他，那天啃了他一口的竟然是帝国太子啊！\n\n陆忱随便逗弄了两句，太子殿下就说什么都不撒手了。\n\n完蛋，甩不掉了，那咋办？\n\n结婚呗！",
