    "abstract": "【—双男主—双强—权力博弈—掌控与臣服—年下—商战—追夫火葬场—白切黑受—HE】\n\n一场意外的碰撞，让两个人从商场死敌变成秘密关系。\n\n商业上的互相算计，私下的臣服与支配，再加上一场陆琛全然不知的股权暗斗，把两人牢牢绑在一起。\n\n———————\n\n三年追逐，半年算计，到底是他在驯服江彻，还是江彻用另一种方式将他绑架。",
