    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/978858ce74e837e0c2f51458cee875fb~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358562&x-signature=kMuv1EOKbo030c2wwVWjmT5p2BA%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【双男主，双强，闷骚，强撩】\n\n震惊！\n\n那位身份尊贵，令帝都权贵闻风丧胆的大佬竟被人当街堵在了车上？\n\n谁啊！\n\n谁这么大胆？\n\n据说是个穿病号服的少年！\n\n那人不但当街调戏那大佬，还大言不惭的说大佬是他的舔狗！\n\n少年的原话是这样的：\n\n“五年后你会爱上我，而且爱的死去活来！”\n\n“为了得到我的心和身体，你煞费苦心。”\n\n“怪我开窍太晚，才没明白你的心意。”\n\n“这次，换我来追你。”\n\n天呐！这神经病太不要脸了吧！\n\n他脸呢？这话怎么说得出口啊！\n\n可不嘛，还有更不要脸的呢。\n\n他还对大佬说：“我是你以后白天想亲，晚上想爱的男人！”\n\n他到底是谁啊？\n\n大佬就没当场弄死他？\n\n最新消息。\n\n调戏大佬的人是A市首富家的纨绔小少爷！\n\n是那个不学无术，成天就知道欺男霸女的小废物姜沉？？\n\n是的，没错。\n\n这姜家也不知道造了什么孽，居然摊上这么一个儿子。\n\n如今这小纨绔当街得罪大佬，姜家怕是要破产了。\n\n于是，所有人都等着姜家破产的消息。\n\n结果。\n\n姜家没破产不说，小纨绔的话却一一应验了。\n\n那天，大佬当众吃醋抱走了小纨绔，还把调戏小纨绔的富家少爷给揍了。\n\n当夜，大佬委屈的把头埋在姜沉肩头，声音暗哑：“我等不了五年后了。”",
