    "author": "南天阁的极恶魔王",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o71eb0c242b25271c2a11fa6425942385~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358562&x-signature=5rGN6Urfff4kZNtwf0b7wGF2Dig%3D",
    "score": "8.1",
    "category": "双男主",
    "abstract": "【双男主+玄学直播+真假少爷+疯批大佬+苏爽甜】\n\n满级天师季星河一睁眼，穿成了鸠占鹊巢的豪门万人嫌假少爷，正被五花大绑扔在双腿残疾的京圈“活阎王”陆渊面前等死。\n\n看着陆渊身上那浓郁诱人的极品黑煞之气，季星河咽了咽口水。\n\n陆渊转动轮椅，眼神狠厉：“最后一句遗言。”\n\n季星河不仅不躲，反而一把按住男人的残腿，在全场惊骇的目光中，低头吻住了他脸上的黑死咒印。\n\n“你的煞气真香。这极阴之体，我馋了。”\n\n众人：？？？\n\n陆渊：……你把我想杀人的节奏都打乱了！\n\n后来，假少爷没死，反而开启了算命直播。\n\n绿茶真少爷暗中养小鬼？直播超度送他踩缝纫机！\n\n豪门父母气运败光跪求他回家？算命一次一千万，亲属翻倍！\n\n全网都在等季星河翻车，却等来了令人闻风丧胆的疯批活阎王从轮椅上站了起来，将人抵在墙角，声音喑哑。\n\n“再亲一下，命都给你。”",
