    "author": "鲜橙柠檬多",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/38c9f1541ed1990040afb2979fa87c69~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358562&x-signature=RbxLiyG%2BnRSYwjQUNmx06SlQytg%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "【双男主+一见钟情+双洁+年下+受宠攻+he】\n\n【无限宠溺大佬受vs绿茶爱作妖没安全感攻】\n\n正文已完结，番外持续更新中，放心入吧～\n\n慕阡寻作为一个战场横扫无敌，商场大杀四方的大佬，捡到一个漂亮的小可怜。该怎么养呢？当然是宠他，宠他，宠他！\n\n苏霭每天一睁眼就是雄竞，哥哥只能是他。遇见刁蛮秘书，苏霭：“是我不配肖想哥哥了”泪水啪啪掉。慕阡寻看着监控里可怜的大宝贝，秘书可以被辞了。\n\n遇上把自己当做实验品的家人，苏霭拉着衣角：“哥哥，我疼～”慕阡寻表示，苏家可以炸了。\n\n遇上想要抢走哥哥的，苏霭会压住慕阡寻“哥哥，只有我一个，好不好？”慕大佬会揉揉头“好，崽崽想要什么都可以。”",
