    "score": "8.7",
    "category": "双男主",
    "abstract": "【已完结】【双男主+1v1双洁+双强+末世+异能+满级大佬+炮灰+甜宠+无限游戏】\n\n他被好兄弟坑进无限游戏，死里逃生后又被队友各种出卖陷害。\n\n好像全世界都不想他活着，他就偏要活下去，还一口气杀穿了游戏。\n\n从游戏里出来，他找了个好看男人，过了两年悠闲的退休日子。\n\n两年倒计时结束，一觉醒来他才知道这是一个小说世界。\n\n而他是小说里一开局就会蠢死的炮灰！",
