    "author": "参天甲木",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/5b5a102cf082e8d5f9343e51e9a8412a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358562&x-signature=KWwA5cXdLqzUFNSYsH5fiTrmLkY%3D",
    "score": "8.4",
    "category": "双男主",
    "abstract": "【双男主+年龄差九岁+娱乐圈+苏爽打脸+穿越+豪门+久别重逢】\n\n【内骚满级大佬攻vs明骚爱打架受】\n\n郁舟穿越到了与他长得一样，姓名也一样的原主身上。想要在这世界活命必须要攻略男主。\n\n他的攻略对象太狗，害他短短一个半月从三线流量，变成恋爱脑三十八线小糊咖。\n\n结果，攻略进度却还是零。\n\n然后，系统告诉他，他的攻略对象弄错了，是男主他叔薄星彦，一切从头再来。\n\n虽然新的攻略对象太配合，让他感觉不真实。\n\n可系统提示，攻略进度太慢。\n\n系统9999：【郁舟，坏消息是你攻略错对象了，好消息是再也不用受那神金的气了。】\n\n郁舟：【……那我还得谢谢你咯？】\n\n薄星彦：【解释解释？郁舟没来攻略我，反而去攻略那小子？】\n\n系统001：【啊……统子马上去查！】\n\n他呕心沥血攻略成功后，却发现现在的一切都不是他想的那样美好。\n\n是一见钟情，还是蓄谋已经，\n\n是真情实意，还是别有用心，\n\n攻略成功是揭开真相的开始……",
    "word_number": "372650",
