    "score": "9.3",
    "category": "双男主",
    "abstract": "【外冷内热自我攻略护短腹黑攻VS实力超强睚眦必报白切黑受】\n\n祁珩×淮枝\n\n祁珩，S级空间系异能拥有者，异能执行局一队队长，被称为“第一人形兵器”，A级以下的异种在他手下都如蝼蚁般不堪一击。\n\n偶然外出，却碰上一支联盟小组在异种清绞任务中发生意外，本该被制服的异种暴走发狂，实力成倍增长，他立即出手，可解决完异种后却恰巧碰上后遗症发作，人瞬间失去意识跌入海中。\n\n再次醒来，他早已躺在岸上，身旁还多了个长相出众的青年。\n\n青年出现的时间跟地点都太过于巧合与奇怪，不禁令人生疑，可无论他如何询问，都只得到了青年不带任何情绪的对视。\n\n他好像…不会说话…\n\n祁珩带回了他的救命恩人，是个漂亮的哑巴青年。\n\n可自他留下后，越来越多怪事发生。\n\n有人嘲笑一队多了个哑巴累赘，当晚出任务时竟被异种啃掉半张脸，有人以虐杀无辜异种为乐，第二天就被发现惨死家中，有人企图在任务途中联手除掉祁珩，下一秒就异能失控身亡……\n\n不少人认为这是祁珩暗中立威。\n\n直到一次异种潮爆发，那个总是跟在祁珩身后的沉默青年抬手就灭了S级异种……\n\n异能者们：他不是空有美貌没有攻击力的普通人吗？\n\n正在逃跑的异种们：哦，你们说他啊，平平无奇世界唯一真神罢了。",
