    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/0e6c332fafa38696eebc2f6a1b721dd3~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358562&x-signature=HhT5R4GGZ4vYL8p5NLwXq%2FeEj%2B0%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "[双男主+强制爱+病娇偏执+双强虐渣+甜宠+1V1双洁]\n\n上仙简安因为打碎了天帝的琉璃盏被贬下凡间，必须要攻略每个世界的男主，才可以重返仙界。\n\n霸总，对他偏执宠溺:“你想要什么我都给你。”\n\nEnigma颜值爆表的高岭之花，把他从Alpha变成omega:“你是我的。”\n\n人气影帝天花板，给他至高无上的宠爱:“我是你最忠实的信徒。”\n\n京圈贵公子，先婚后爱，宠他入骨：“你逃不掉的。”\n\n禁欲教授，斯文清冷大佬偏执成性，暴戾残戮：“你是我的宝物”\n\n病娇暴君，将天下送给他:“你是我的王。”\n\n偏执魔尊徒弟，拉紧他的手苦笑：“安安，你要去哪？”\n\n....\n\n简安迷茫了，他只是想完成任务而已，为什么每个世界的大佬都对他强制爱？\n\n迷雾中走来一个人，向他伸出了手。",
