    "abstract": "——已完结——\n\n【双男主＋1V1双洁＋双强（受更强）＋算命除妖杀鬼（不恐怖）】\n\n偏执长情外冷内热受×温柔深情忠犬攻\n\n沉睡多年的孤魂终于寻找到合适的身躯得以重生，却被牵扯进狗血豪门恩怨之中。\n\n他占用了这具身体，便该为枉死之人讨回公道，不过在此之前他得找一个靠山，省时省力。",
