    "book_id": "7418977677618465817",
    "book_name": "老婆，你理一理我啊",
    "author": "羊羊不咩",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/71f8558b0b4814768c2c2982afa1399a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358563&x-signature=yuQqXkYv3sxcBIsyI5feCGCqgd4%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "（真人有声已出）\n\n【双男主＋双洁＋年下＋恋爱脑＋三部曲2】\n\n恋爱脑黏人醋王妻奴攻x儒雅矜贵钓系美人受\n\n季清衍对陆祁一见钟情，谈恋爱后，才发现他们俩撞号了。\n\n季清衍:以为找了个老婆，没想到找了个小老公。\n\n陆祁：他老婆竟然把他当老婆?\n\n陆祁，陆氏集团太子爷，权贵见了都要尊称一声陆少，在外桀骜不驯，做事张扬，有钱有权还长了一张帅脸。\n\n刚大学毕业，他二叔就让他负责一个重要项目，没想到勾搭上了对方公司总裁，还把人家拐回家当老婆了。\n\n陆祁不仅是个顶级恋爱脑，还是一个醋精，吃个醋都能生一天闷气，私底下是一个大哭包，黏人又喜欢撒娇，凭着一张脸把季清衍吃的死死的。\n\n他把季清衍管的很严，查岗更是家常便饭，而季清衍也纵容他对自己的占有欲和小脾气，陆祁吃醋生气了，也会第一时间哄他。\n\n他天不怕地不怕，最怕的就是季清衍，对方一个眼神，他就知道回家又要挨老婆训了。\n\n在外是生人勿近的小狼崽，在老婆面前就是黏人听话的大狗狗。\n\n陆祁：平等的嫉妒接近老婆的任何人。\n\n陆祁（攻）x季清衍（受）",
