    "score": "8.8",
    "category": "双男主",
    "abstract": "［双男主+直播+恋综+日常+甜文］\n\n温禾受邀参加了一档恋综，可就在恋综开播的前一天晚上他做了个梦，梦里他是一本小说里的男……炮灰？\n\n小说的主角叫周思羽，与主角攻在恋综上重遇，两人在恋综里经历了一场酣畅淋漓的极致拉扯，吸取了众多cp粉也给节目播出上升了极大的热度\n\n而他温禾便是炮灰甲！小说里就是个纯工具人，重要镜头里没有他，别问，问就是在做饭\n\n自古恋综有一大定律那便是厨子没有爱！\n\n不过温禾对此并不感兴趣因为他本来也只想当个路人甲\n\n只是……\n\n为什么小说里总是围着主角受转个不停的纨绔男二会缠着自己啊喂！\n\n季迟本是被家里人逼迫来参加了一档恋综，本来他就对这些毫无兴趣，可直到有一天他忽然发现…恋综里有个小木头人\n\n小木头人很呆，无论自己做了什么他都只会说没事，于是季迟为了想在小木头的身上看到更多情绪便天天缠着他，烦他，只为在对方脸上看到恼羞成怒的表情\n\n只是随着时间的过去他已经不在满足这一点情绪了，他还想要更多更多…别的感情\n\n情感迟钝木讷受x公子少爷纨绔攻",
