    "book_id": "7549464913412885529",
    "book_name": "穿书怒甩渣男，睁眼在男主床上",
    "author": "格桑兔",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/c71d2b15bd9ad8cf14ff52bf38ca5353~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358563&x-signature=%2FExZMjCv6oDTDSj3uvp2ab5OFHM%3D",
    "score": "9.1",
    "category": "双男主",
    "abstract": "【双男主双洁，男二追夫火葬场，太子爷上位。】\n\n【掌控欲拉满爹系攻x洒脱自由直球受】\n\n黎殊，一个活力男大，平时除了上学，还是砍一刀的忠实用户。\n\n意外穿越，睁眼就在跟男的亲嘴儿。\n\n黎殊两眼一黑。\n\n！\n\n刚把人推开，就绑定了系统。\n\n被告知自己身处的世界实则是一本无cp爽文，必须要在每个关键节点推动剧情发展，帮助男主裴颂安坐稳太子爷的位置。\n\n-\n\n【你暗恋竹马多年，晚宴上看见竹马带着漂亮男孩出席，终于破防。】\n\n【给竹马下药，还伸手脱他裤子——】\n\n剧情介绍一半，身下的男人忽然用力捏住黎殊的脖子。\n\n月光落在男人俊美的脸上。\n\n系统一顿，突然乱码。\n\n【重新整合剧情中。】\n\n【杀伐果决的太子爷裴颂安被你下药，你脱他裤子未遂，正被人像鸡崽子一样按在床上。】\n\n？\n\n谁？\n\n我在脱谁裤子？\n\n还没搞清楚，系统又补一刀。\n\n【三分钟以后，房间大门会被踹开。】\n\n【届时，你会被裴家丢进海里喂鱼。】\n\n黎殊：。\n\n哈，哈哈，哈哈哈。\n\n抽象搞多了，终于轮到世界抽我了。\n\n-\n\n后来传闻，黎殊把太子爷招惹够了，直接跑路。\n\n被人抓到，三天三夜没出房门。",
