    "score": "9.3",
    "category": "双男主",
    "abstract": "【久别重逢/ABO/电竞/直播/双洁小甜饼】\n\n【傲娇漂亮小坏蛋x情有独钟野王攻】\n\n因为一些陈年旧事，栗知格外热衷挑衅各种联盟职业选手。\n\n比如在直播时毫不留情地单杀，并且在对方死亡点位附近绕着圈跳舞。\n\n十分嚣张，十分狂妄。\n\n一度在网上声名狼藉，人人喊打。\n\n直到签约了RAK战队开启第一场露脸直播后，网友才震撼发现：\n\n这个冷酷无情的中单王——\n\n皮下居然是一个萌萌的Omega。\n\n—\n\n刚斩获世界冠军回国的谢寂川参加了一场线下娱乐赛。\n\n然后就在舞台对面看见了那张令自己朝思暮想的脸。\n\n再定睛一看，那张脸的主人优雅地冲他比了个中指。\n\n谢寂川：？\n\n家猫混成了野猫怎么办？\n\n当然是抓回来重新养。\n\n—\n\n全A战队突然加入了一个Omega，联盟狗仔队都激动万分。\n\n莽足了劲想要挖点炸裂新闻。\n\n直到某一天，他们在平日里不苟言笑的RAK队长的房间阳台上。\n\n拍到了印着队内中单代言照片的内酷。\n\n网友：！\n\n栗知：？\n\n谢寂川：没错，我们是真的。",
