    "book_id": "7473869841921756222",
    "book_name": "暗恋死对头不说？共感了你爽什么",
    "author": "余桃子",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/bb38a00f507116f4915bb389d362023d~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358563&x-signature=NNDuog5PLeEYWPAzq5ryQc7pLmQ%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "『正文完结』（评分刚出，会涨哒！宝宝们别抛下我呜呜）【双男主+死对头+单方面共感+暧昧拉扯+双洁+HE】\n\n【瘾大爱装酷哥攻x傲娇炸毛美人受】\n\n-\n\n南城出了个大新闻，沈家破产了，曾经骄矜桀骜的小少爷沦为茶前饭后的谈资。\n\n沈迟放下身段打工还债，却被屡屡刁难。\n\n小少爷不惯着，酒瓶把人脑袋抡开花，唇角勾着，眉目狠戾，“信不信老子废了你。”\n\n可老天爷偏要跟他对着干。\n\n破产就算了，沈迟突然发现自己跟死对头共感了！\n\n死对头喝酒，他醉眼朦胧。\n\n死对头生病，他头晕目眩。\n\n死对头洗澡，他面红耳赤。\n\n苍天啊，沈迟要崩溃了！！！\n\n-\n\n谢景尧发现沈迟最近不太对劲。\n\n躲着他，不愿意跟他有任何接触。\n\n调查车祸案子时，他不小心受了伤，自己还没哭呢，就见嘴硬的小少爷红着眼眶狠狠瞪他：“看什么看！”\n\n谢景尧：“ber，受伤的是我，兄弟你哭什么？”\n\n难不成....沈迟也暗恋他？\n\n-\n\n跟死对头共感了怎么办？在线等，挺急的。\n\n排雷：微群像，有副CP，不能接受误入",
    "word_number": "390787",
