    "score": "9.7",
    "category": "双男主",
    "abstract": "【已签实体出版】【星际+abo+年下+双强】联邦最高级别指挥官时霁，冰冷美丽，禁欲杀伐，是朵碰之即死的高岭之花。\n\n大家对待指挥官的态度只有尊敬、再尊敬。\n\n直到皇家学院新生入学第一天——\n\n谢灼一身冲锋衣站在人群中，一头灿烂不羁的银发，出挑的让人挪不开眼：\n\n“指挥官，您还记得我吗？”\n\n“在上周医院门口马路边的花园，花园里有一片秃了的草，您就蹲在草里红着眼眶嗦手指尖尖……”\n\n“啊，那可怜见的，我还给您递了纸和草莓牛奶呢！”\n\n“………”\n\n现场一片死寂。\n\n指挥官一言不发，面色冰冷的睨着他。\n\n谢灼福至心灵，恭敬的九十度弯腰：“……对叭起。是我认错人了。”\n\n……\n\n出生在ABO性别的第八星系，时霁在某天迎来了二次分化。\n\n战无不胜的指挥官本以为自己会由Beta分化成顶级Alpha，谁知……\n\n他看着化验单上的Omega，平静将单子扔到垃圾桶里。\n\n他不需要Alpha，他想。\n\n*清冷禁欲美人指挥官×骚话连篇银毛狼狗",
