    "book_id": "7481172045003246616",
    "book_name": "直男也要在虫族救赎疯批雌君吗",
    "author": "不辞辞",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/c8935081d3fada5b643ea0c7fab66f3e~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358565&x-signature=XrCdqxeYZeHVZu2opgd9OO3i2Zs%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+虫族+主攻+1v1+救赎+双洁】\n\n坏消息，林厌是个钢筋直男，但他穿书了，还穿成了反派的恶毒雄主。\n\n更坏的消息，反派即将因为产下死虫蛋而黑化，并且会把他这个恶毒雄主剁碎了喂狗。\n\n林厌：“……”\n\n天杀的，他没有吃多了红豆，他不相思啊！\n\n原主的死是因果轮回报应不爽，但林厌是万万不敢触碰对方霉头的。\n\n从反派怀崽起，啃砖头厚的《虫产科学》。\n\n一日三餐，早起做营养餐。\n\n甚至，在他们结婚两周年纪念日时，林厌给反派准备了特别的礼物——\n\n一份离婚协议书。\n\n为了还反派自由，并保住自己的小命，林厌屁颠屁颠给他递钢笔：“到时候审判庭会把家里的钱判给你，虫崽也判给你，你看还缺点什么？”\n\n反派合上钢笔。\n\n掀起眼皮，看向林厌：“你。”\n\n林厌：“？”\n\n反派：“把你也判给我，行吗？”\n\n林厌果断拒绝反派的请求。\n\n谁知反派表面同意离婚，在就在林厌要离开时，门锁被反派咔嚓一下弄坏了。\n\n反派站在他背后，似乎要跟他在这个房间里生活到天荒地老。\n\n林厌：？\n\n林厌：我们老实直男也要在虫族被强制吗？",
