    "book_id": "7644891236368649240",
    "book_name": "疯了吧！你们管这个疯批叫废物？",
    "author": "爱吃土豆的肥宅",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/932ca7b016025262714462c87ea39820~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358565&x-signature=A7ZyzwITOYxLnMnSdndi8wLP28s%3D",
    "score": "9.1",
    "category": "双男主",
    "abstract": "（评分刚出）【bl双洁+星际军校+相爱相杀+剧情流慢节奏+微群像】\n\n星际讯文，南溪星谢家二少诈尸后彻底疯了\n\n开局火烧灵堂险些将渣爹一家烧死在里面\n\n入学第一天被人找茬\n\n谢琢：一脚踹出二里地\n\n面对绿茶的茶言茶语和渣男的癫公发言\n\n谢琢：直接一个暴扣\n\n开学考核被人偷袭\n\n谢琢：他要我命我只断他一臂，我真是太仁慈了\n\n后来谢琢被黑塔的执法者带走\n\n所有人都以为谢琢死定了\n\n时隔数日他又回来了还转去了战斗系\n\n到战斗系第一天他嚣张喊话\n\n我不是来加入你们的，我是来打趴你们的\n\n结果惹了众怒，后来他们惊恐的发现，他真的是来打趴他们的\n\n谢琢：众生平等\n\n他平等地创死所有人\n\n……\n\n初见，沈衔因任务意外失控，抓着谢琢的脚想求救\n\n谢琢一脚踩在他脸上\n\n结果沈衔直接一口咬住了他的脖子\n\n再见，谢琢掉进渊族的“巢”内，失去控制遇到沈衔\n\n沈衔抬手就往他胸口捅了一刀\n\n又见，两人一个是黑塔典狱长，一个是黑塔罪犯\n\n沈衔直接将人丢进了斗场，最后谢琢满身血从里面杀了出来\n\n沈某：初见吾妻张嘴就咬，再见吾妻反手一刀\n\n谢某：路边的男人看不得，会咬人，可怕得很，就该一刀砍死\n\n后来有人发现，不死不休的两人背着众人亲得难舍难分…",
