    "abstract": "【双男主+双强+天才升级流+有脑爽+1V1双洁】\n\n乐观坚韧小师弟VS偏执剑修大师兄\n\n一朝穿越，苏曜成了鸿元界一个十八线小世家在世俗界分支的三房嫡子。\n\n8岁时，他被检测出惊人的雷灵根天赋，进入了家族依附的潮云宗修炼。\n\n从此，万境珠内种灵草，紫霄神雷劈坏人，红莲业火诛罪恶……\n\n闯秘境、夺造化、斩妖邪、败天骄……\n\n一步步立身大道之巅。\n\n咦？等等！\n\n怎么大师兄看他的眼神越来越炙热？\n\n不仅一路相随，还对他又撩又宠。\n\n这谁扛的住呀？\n\n苏曜：大师兄，快到碗里来！\n\n顾景渊勾唇：好。",
