    "score": "7.6",
    "category": "双男主",
    "abstract": "【慵懒嘴毒护短·京圈太子爷攻】×【清冷孤傲·外冷内乖疯批美人受】\n\n【电竞+双强+救赎+双洁】\n\n电子竞技没有爱情，但我有你。\n\nPGC全球总决赛，绝命梅花桩，TCG战队落后欧美豪门15分。\n\n全网黑粉都在等着看那个“假赛废物”沈星迟的笑话。\n\n枪林弹雨中，国内公认的步枪大魔王陆焰，拼死挡住所有火力，对着麦克风哑声低笑：“Star，开枪。”\n\n漫天毒圈中，清冷消瘦的少年跃起，AWM狙击枪破空咆哮！\n\n砰——！盲狙视野盲区，爆头，极限一穿四！灭队！\n\n漫天金色的雨落下，陆焰在亿万观众的直播镜头前，将冠军奖杯塞进少年怀里，对着麦克风笑得嚣张极了：“我夸自家小朋友长得乖、打得狠，犯法吗？有本事你们在赛场上干碎我。”",
