    "score": "8.7",
    "category": "双男主",
    "abstract": "【双男主+末世+囤货+双重生+空间】\n\n（躺平日常，主角有仇必报，但不是打打杀杀那类，适合减压观看的温馨小甜文）\n\n极寒末世，陆丞重生归来。\n\n上一世，他在基地救助无数幸存者，最终却被冻死。\n\n这一次，他只爱自己。\n\n他要打造属于自己的安全屋，和裴聿一起迎接新世界到来。",
