    "book_id": "7617724024923114521",
    "book_name": "救命！穿书末世重生男主人设崩了",
    "author": "废废竹",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o5770c7a5cdb4b9ac1a0965f29e5d37bf~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=%2BeSVtIcMYuC1ygrmUfLWpCzR7ww%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【女频双男主+两对主CP+末世丧尸+各种天灾+多元化异能+宠夫】\n\n末世来临，丧尸横行，动植物变异，人类生存成危。江安觉醒空间异能，空间自成一界，成为末世救世主，为此在楚晏的保护下，努力救世。\n\n江安：上一世江安为了幸存者，天天在空间中种植粮食，建立生存基地，却没有想到，被亲人背叛，为了夺他异能，剖开他的头颅，害死他，救助的那群人，更是想要吃他的肉喝他的血，逼得他的爱人自爆而亡。重活一世，救世什么的，与他无关，他只想好好补偿爱人。\n\n楚晏：任务成功就差一点，任务对象死了，任务对象可是他一见钟情的爱人，不能忍！气的他自爆炸死所有人，让系统吞噬世界能量，重开一次，和爱人再次团聚。\n\n池宣：因为好奇圣父救世主人设，看了一本书，看到结尾的时候发现，作者是为了表达圣父没有好结局，气的他怒骂作者五百字，就被吸入书中，成了一个活到最后的路人甲！来都来了，当然是帮助主角努力成为救世主，活下去，只是这救世主怎么和书中写的不一样？\n\n季方臣：他从小就有读心术，能够听到别人的心声。为了研究项目，他复刻了一具身体，跟随他，直到某一天，他突然听到了实验体池宣，传来了心声……",
