    "score": "7.8",
    "category": "小说",
    "abstract": "双男主，1v1，双洁，甜宠爽文。上辈子末世，姜年被囚禁在地下室，丧尸潮来临时被家人抛弃，最后惨死在赶来救援的前任哥程境怀里。再次睁眼，姜年重生回到末世前半个月，为了苟命当即决定厚脸皮吃回头草。首先，跟前任哥借点钱囤物资：姜年：“程境，你能不能借我点钱？”程境：“点名道姓的跟我借钱，你怎么不让我跪下！”姜年：“境哥我错了……”再次上位成功后，他安心抱紧前任兼现任哥大腿开始末世躺平生活。PS：看文带入角度不同观感就不一样，尊重他人看法尊重作者设定，不要过度带入现实三观去共情。喜欢就看，不喜欢就弃，自己的标准自己用，不要恶言相向。作者写文不易，请高抬贵手别恶意差评，谢谢。祝大家都能看到自己喜欢的小说。",
