    "author": "穿堂枫",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/8bc09d3338721a81cc716e5d60dfefe2~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=wE7Dsut2AkaVle0K6YWgx8ecGyQ%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "（刚开分）【双男主+1v1+年上甜宠+末世+双强+救赎+宠物+囤货+空间+房车+微群像】\n\n深情忠犬大爹攻x白毛小疯子受\n\n身心双洁\n\n闻人泪刚脱单一个小时，老攻就变成了丧尸。\n\n老攻虽然尸化，但是深情，一拳一颗丧尸头，围着闻人泪360度无死角守护。\n\n闻人泪：我很心疼你，但你现在也太丑了。\n\n傅严：……\n\n闻人泪最终决定带着丧尸老攻闯荡末世。\n\n唉，将就过呗，还能离咋的。\n\n————\n\n日常belike：\n\n闻人泪：牙刷拿好，刷牙会吗？\n\n傅严：……（放嘴里嚼嚼）\n\n再belike：\n\n闻人泪：你恢复触觉是好事，但能不能别老捏我屁股。\n\n傅严：……（撕开老婆的裤子）",
