    "abstract": "【评分刚出！！！】\n\n【双男主+末世丧尸+空间+1v1+双洁双强+主受+年下】\n\n谢云徊（攻）vs 萧燃（受）\n\n萧燃被雷电劈开的空间裂缝卷到修仙界，历经百年，还在修仙界找了个道侣，结果最后被劈了一顿后被丢回蓝星\n\n萧燃：……\n\n完了完了完了，他家谢绿茶要疯了\n\n好不容易找到的对象没了，没想到更糟糕的事还在后面。\n\n回到蓝星，他的未来居然是凶\n\n好家伙，那就看谁比谁先倒霉吧",
