    "book_id": "7581135301683203096",
    "book_name": "末世重生后：当然是抱紧主角大腿",
    "author": "随三鬼",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/fd33c07ca99267ba45008e2f2c4640f2~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=o4WLhTCXXIPJz27BSqMg4JjhkAo%3D",
    "score": "8.5",
    "category": "双男主",
    "abstract": "【完结】【双男主1V1，末世，空间，重生，双洁，群像】\n\n手握空间在末世挣扎了一年的宁原，在逃离队伍时一朝不慎被丧尸咬伤。\n\n即将尸化时，队伍里那个沉默寡言的男人找到他直接出手结束了他的生命。\n\n再次睁眼宁原发现自己重回末世前半个月！\n\n什么？原来自己的世界只是一本小说，而他是书中的恶毒男配？\n\n这一次宁原决定远离主角团，利用空间疯狂囤货，拯救末世什么的就交给主角他们吧，这辈子他只想远离剧情好好活下去！\n\n但……一切的一切好像和上一世有所不同。\n\n队长的偏爱，队友的真挚，还有……还有那个男人看向自己的眼神，为什么一切都和自己知道的不一样？\n\n重生的秘密、世界的真相，在找回队友后逐一揭开。\n\n原来我从来就不是一个人。\n\n【主cp：宁原X刑风野，副cp：官还恩x南和(攻)】\n\n【受非传统意义上的好人，前期不算讨喜角色，主角团也非爽文定位，攻杀受是误会，群像，穿插众多普通角色求生，人物塑造不是非黑即白，任何一个角色都不会为了衬托谁而被随意消费，不喜勿喷。】\n\n【排雷：非爽文，受非独狼，对上一世攻的选择并没有很深的恶意，他更恨他自己，内耗型人物，还是跟着上一世团队一起行动，重生智商不变，性格也不会立刻改变。】",
