    "abstract": "【末世+双男主+丧尸+异能+甜宠】\n\n末世来临的前一天，褚彦被人打包送给了大学校园男神宋司宴。\n\n事后他暗暗发誓以后见到这位大佬一定绕道走。\n\n谁料丧尸病毒忽然爆发。\n\n那位他避之唯恐不及的大佬，在危急时刻竟坐着粉色宝宝车逆着人群，直奔他而来......\n\n褚彦:呵，别说绕道走了，根本甩都甩不掉！\n\n——\n\n面对陌生人的搭讪。\n\n褚彦头都不抬：“抱一丝，我喜欢男人。”\n\n宋司宴：“好巧，我也是。”\n\n褚彦:……\n\n他现在改口说自己是直男还来得及吗？",
