    "score": "8.6",
    "category": "双男主",
    "abstract": "【重生＋末世＋空间＋双男主＋金手指】\n\n天灾:酷暑，地震，暴雨，洪灾，疫病，严寒，饥荒，人祸等。\n\n末世来临，人类将何去何从?\n\n物竞天择，适者生存，优胜劣汰!\n\n邱秋的一生是不幸的，父母离婚，各自重组家庭，对他不闻不问，邱秋只得半工半读，养活自己，好不容易坚持到考上大学，进校报道时，遇到儿时的邻家哥哥萧晗，本以为幸运降临，却遭遇末世，两人一路艰辛走来，好不容易进了避难所，却遇到昔日父母，二人对他冷漠异常，生怕被他缠上，之后，父亲邱志明，无意中得知他觉醒了空间异能，为了生存将其出卖，萧晗为救他而死，他为了给萧晗报仇，在研究所人员围上来时，选择自爆而亡，却不想重生回到末世前两个月，邱秋发现他的空间还在，这一次，他要提前做好准备，找到萧晗，和他在这末世好好生存下去。",
