    "category": "双男主",
    "abstract": "双男主+双强+丧尸+异能+空间+团队+零元购囤物+年下养成\n\n前世的简承有空间却无异能，在基地破防那天，被异种丧尸兽撕咬而死，死前发现空间的秘密，带着遗憾重生。\n\n回到丧尸爆发前一天，发现流落在他家院子的落难美少年，竟是前世基地老大林海尧。\n\n末世的林海尧有多项异能，是人类战力天花板，而此时的林海尧不知为何，比同龄人瘦弱矮小，还被亲人追杀，十足的小可怜。\n\n简承熟知末日进程，决定担下风险，养成大佬和囤积物资两手抓。\n\n在保护雏鸟期大佬的过程中，不仅朋友觉醒了水系异能，还相继捡到‘金刚托尼’‘音波杀手’‘驭兽大佬’‘冰雪女王’等后世战力超强的异能人。\n\n在基地争夺战中，靠林海尧等一众强悍小弟，轻松获得老大之位。\n\n本以为这一世他能安稳养老，却不想狼崽子养大了要噬主。\n\n基地众人：“多少天没见简老大出来，以后恐怕没有简老大，只有林老大喽。”\n\n房间内，变大的林海尧对简承说，“你的空间和物资我都不稀罕，我稀罕的只有你。”\n\n——\n\n主角非孤狼，有团队，囤物资不是一个人用，有更大的目标。\n\n受开场就强大，攻君成长型，人格实力都在成长，得到身体异能会当天长大。",
