    "book_id": "7527974916566567998",
    "book_name": "末世：呵，陆队长你不矜持",
    "author": "惟有杜康",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/1d0a3f07432c2451f4444130803f0d48~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=pldmUQVGFvgjjaciqJP1CzPS98k%3D",
    "score": "7.7",
    "category": "双男主",
    "abstract": "(双男主+双强+空间屯粮+双洁，群像 ，彼此为对方初恋，相互扶持。)\n\n近未来科技时代，一场突如其来的\"红雨\"灾难引发全球性变异危机。\n\n主角意外获得一个可以升级的异次元空间小屋，成为末日中的生存关键。\n\n空间会升级，有种植的农田，流淌的小溪，满是果树的小山，还有畜牧的草地。\n\n在末世别人连草根都吃不上的时候，主角带着队员们天天吃肉。\n\n同时还有变异的植物。\n\n别人:“怎么办，我们都是普通人没有异能。”\n\n程墨:“最新品变异植物——屎包苹果，散发的臭气可以减速丧尸50%行动力，你值得拥有。”\n\n末世艰难的环境中，程墨与陆骁不期而遇。\n\n人性在灾难中显露，爱意如藤蔓肆意生长，\n\n因为遇见了你，我于废墟中看到了玫瑰。",
