    "author": "伯黛",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/ae4bd3ec0d5eb0ebea469df49fd4bd6e~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=hh6PBfJQ4%2FHFopcEuRLFvbc7P4U%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "【疯批反派vs伪斯文君子】\n\n【末世+重生+双男主+双强+以恶制恶+1v1双洁+冷兵器无异能】\n\n【副CP一：白切黑狼少年x年上救赎】\n\n【副CP二：世家公子x清冷“美人”】\n\n林寂死了，但等他再睁眼，发现身在敌营。\n\n他所属歼灭小队的顶头上司，就是沈玉书。\n\n前世亲手置他于绝境之人。\n\n他被无数变异体撕碎，连片衣角都不曾留下。\n\n而现在，他回来了。\n\n-\n\n到了沈玉书身边他才知道，沈玉书一直有个爱人，爱而不得的爱人。\n\n-\n\n我想和你在一起很久很久。\n\n久到世界荒芜，久到恒星陨落，久到朝阳和晚月也有相见的一日。\n\n-\n\n淬炼过生与死的爱意，永不枯萎。",
