    "author": "打发时间的兔兔",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/7ff37de3a6f25fd57607c999a7716933~tplv-snk2bdmkp8-superreso-double-rz:400:0.image?lk3s=64477e16&x-expires=1795358567&x-signature=c%2BsnQCVTDNjZGXp7uPYLrAzX9Ao%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "【末世+双男主+异能+团宠+掩藏双强】\n\n评分刚出，所以低\n\n小丧尸洛凡第一次见到男人，“这么凶残！”只能安详躺下等死！\n\n结果男人是个睁眼瞎！\n\n小丧尸洛凡第二次见到男人，没事，睁眼瞎啊！找掩体躺下就好！\n\n小丧尸洛凡第三次见到男人，有点可怜啊！干脆投喂下吧！龇牙！\n\n......\n\n再一次见到男人，还好还好，对方是睁眼瞎，躺到在地的小丧尸洛凡暗暗想。\n\n见睁眼瞎再次离开，小丧尸洛凡高高兴兴的往家回。\n\n结果被睁眼瞎连尸带家底打包带走......",
