    "book_name": "末日圈养：高冷丧尸王要亲亲",
    "author": "路左",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o4ed2e76e78b8e012ab91005680e7a0e7~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358568&x-signature=0Qkvz90yU78TO2F%2Fao18veL3%2BjM%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "【大佬攻+美人受+年上+双强】\n\n厉漠南在抵御丧尸潮的时候力竭而亡，重生到还是小菜鸡的时候，睁眼闭眼就被丧尸王带回家。\n\n厉漠南震惊：“你再说一遍！要我干什么？！”\n\n乌鸦系统：“请宿主尽快亲亲噢，亲得越多，好感度越高，你加的异能值就越多呢！”\n\n于是厉漠南为了活命，亲了，还不止一口。\n\n结果真香了。\n\n乌鸦系统：“我就没见过亲丧尸上嘴这么快的。”\n\n厉漠南暗暗搓手：“他长这么好看，还是我占便宜了呢！”\n\n宋白：“脸好帅，好喜欢，亲亲......”\n\nps：\n\n宋白：好看，喜欢，锁起来，我的。\n\n厉漠南：长得真好看，嘿嘿嘿，占大便宜了。\n\n系统：两个死变态。",
