    "book_id": "7380921819936590872",
    "book_name": "末世大佬的乖萌小丧尸",
    "author": "甜文写手一枚",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o86f27f13e3f276117eb2feb5814b718a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358568&x-signature=Q4kgr%2BJ7oeAog%2F4seuecmOq634M%3D",
    "score": "7.7",
    "category": "双男主",
    "abstract": "【双男主＋甜宠＋双洁】\n\n大佬双系异能者攻vs乖巧可爱懂事受\n\n林安岁是一个丧尸，腿又短跑的又慢胆子又小，经常三天饿九顿，直到遇到一个大佬，大佬对他好好，喂香香的血给他喝，带他去吃烧烤，给他一袋子又一袋子的晶石，林安岁尸生好不幸福。\n\n一次出任务大佬对抗丧尸王受伤林安岁拼命救下大佬，大佬意外小丧尸这样为自己拼命，莫非是喜欢自己？\n\n就这样大佬精心的喂养小丧尸，把小丧尸喂养成了自己无比宠爱的媳妇……",
