    "author": "甜文写手一枚",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o558e3ab1f27cbd8e30cb7476cdad5f22~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358568&x-signature=Vk1dzN9iJqdOHHRRsosumAgwAgc%3D",
    "score": "6.8",
    "category": "双男主",
    "abstract": "【评分刚出，后期会涨】\n\n【双男主＋双洁＋甜宠＋高冷攻＋软萌受＋末世】\n\n裴执捡到一只奇怪的小丧尸。\n\n他不吃肉，不咬人，还会自己囤货，遇到危险还会丢物资保命。\n\n裴执觉得有意思，决定带着。\n\n可小丧尸似乎不太乐意，逮住机会就跑，裴执一个雷系异能过去，直接给人劈了个爆炸头，小丧尸浑身黑黢黢的转身，委屈巴巴的朝他：“嗷……”\n\n小丧尸不敢跑了，像个小尾巴似的嗷嗷叫着跟在男人身后……\n\n慢慢的他觉得男人挺好的，总是时不时的给他投喂，小丧尸终于能吃饱肚子啦！\n\n“你是我见过最特别的小丧尸，我喜欢带着你，一辈子跟着我好不好？”\n\n小丧尸捧着肉肉边啃边狠狠点头：“嗷嗷！”",
