    "abstract": "【两男+甜宠+双洁】陆笥他因为吃泡面被呛死穿书了，穿到末世文里，是主剧情十八线配角，为了生存，他艰难存生，抱大腿抱大腿，还真的抱得一个大佬的大腿，成为其的小跟班，本以为大佬就是大佬，结果对方是书中的最大反派boss。陆笥瑟瑟发抖。男人勾唇一笑：不是抱吗？给你抱，呵。\n\n本书又名《那个丧尸皇别过来！》",
