    "book_id": "7645935689397193752",
    "book_name": "末世手滑囤多了，养个大佬过分吗",
    "author": "雨声缠",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o8f4972d328a40f4210654b0c9c7cd39b~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358568&x-signature=B0jb%2Bbao4UOSiPaaB8nQgdJ8ApE%3D",
    "score": "8.4",
    "category": "双男主",
    "abstract": "（评分刚开）【双男主+空间+囤货+异能+丧尸+双强双洁+群像】\n\n谢席言死了，死在弟弟的升学宴上。\n\n前世丧尸爆发，谢家三人开着他的车逃离了丧尸潮，同父异母的弟弟更是制造火海将他困在宴会厅。\n\n死之前他还看见了一双桃花眼的男人，朝他使劲挥手。\n\n“喂哥们，你不跑我先跑了！”\n\n什么鬼啊大哥，你说的跑就是带着一堆丧尸跳楼吗！！\n\n而再次睁眼，他竟重生了！\n\n还意外和空间里的小猫绑定，觉醒了空间异能。\n\n于是——\n\n好吃的，囤！\n\n好玩的，买！\n\n亲爹后妈？碳烤一下喂丧尸去吧！\n\n至于隔壁楼住的那个桃花眼…\n\n长得倒是不错，留着吧。\n\n后来尸潮大规模涌入城市，谢席言不得已开始寻找新家园。\n\n他与周景末结伴，一路扶持，在意识到异能者的强大后，两人抓住风口提升实力。\n\n同时还捡到了一堆实力强劲的小伙伴——\n\n好端端的逃难怎么变成小学生春游画风了喂！！\n\n饲养员谢席言又多了几张馋嘴要养。\n\n“周景末，你等会带他们去把晶核吸收了”\n\n“不要，我饿了，我没力气了。”\n\n“你就净瞎说，刚刚吃的是空气？”\n\n“咸哥，你没喂饱。”周景末意有所指，眼神又开始乱瞄。\n\n“臭不要脸！”\n\n……",
