    "abstract": "【双男主+友情变质+轻松】\n\n全球异能！\n\n穿越蓝星世界的时澈，又帅又高身材又好又有钱，又觉醒了S级异能复制之书。\n\n又冒出来一个系统异能，强化了复制之书，只需要刷S级异能者的好感度，就能复制S级异能。\n\n瞌睡遇到枕头，同市的苏泽正好觉醒了S级异能。\n\n时澈为了刷好感度，尽心竭力的帮助苏泽。\n\n苏泽也相当懂得感恩，滴水之恩，当涌泉相报。\n\n报着，报着，不知怎么，就抱上了时澈...",
