    "author": "吹梦一辞九万里",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/9e360c923b52fe6acd089a21f60b9243~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358570&x-signature=P83u%2BCbdREtn1hS%2BNLgrMXDFjy8%3D",
    "score": "7.3",
    "category": "双男主",
    "abstract": "（双男主+玄幻+强强+天才+闷葫芦战斗力爆表忠犬+建势力+金手指+辅助+御兽）\n\n身心1V1，天才辅助系兼御兽魔法师×更天才冰系爱吃醋战斗力爆表木头忠犬\n\n【主剧情流】\n\n五好文冰轩一夜投胎，孟婆汤都没喝直接穿越到魔法世界。\n\n开局觉醒辅助魔法，没关系，我有免费的打手。\n\n遇知己（最后变超级醋包忠犬老攻），建势力，一步步窥探这个异世隐藏其中的秘密。\n\n文冰轩：宋耀辉，我看他不顺眼！\n\n宋耀辉：嗯！我帮你打他！\n\n文冰轩：宋耀辉，我好累啊！\n\n宋耀辉：嗯！我帮你按摩……\n\n文冰轩：宋耀辉我喜欢你！\n\n宋耀辉：嗯！嗯？嗯～\n\n文冰轩：宋耀辉，你是不是又吃醋了！\n\n宋耀辉：没有！\n\n（某个被冻在冰雕里的倒霉蛋瑟瑟发抖！）\n\n阅读指南：\n\n1.开局觉醒辅助系，后续会搭配契约兽！走辅助流和御兽流",
