    "score": "8.8",
    "category": "双男主",
    "abstract": "【双男主+异能+反穿+现实与异空间交错+主受+非人攻】\n\n清冷疏离受x占有欲强冷血白蛇攻（受驯化攻）\n\n苏雪辞因身体不好到云城休养，却意外进入异空间中，里面满是各种巨大的生物。\n\n好不容易穿越结束，回到现实世界，他意外发现自己觉醒了异能，身体也因此变好。\n\n之后，苏雪辞惊觉，回来的不只他一人……\n\n吸血虫、被异化的人类等等事情不断发生。\n\n苏雪辞：什么都好，就是这条蛇太缠人了。\n\n埃尔维斯（笑）：蛇的特性就是死死缠住猎物啊。\n\n主剧情，感情线少自己品，主角受微万人迷。",
