    "author": "卿清无鱼",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2od690e35a5a9f744894d34c5b1542aeeb~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358570&x-signature=B2CSOI6g1T7wVHSPvoo%2B%2FQgB7z8%3D",
    "score": "6.2",
    "category": "双男主",
    "abstract": "【双男主+丧尸末世+穿越+1v1双洁+空间+异能+双强+群像】\n\n【自我攻略高冷攻 vs 坦荡率真直球受】\n\n·\n\n文砚舍了一身修为，穿越时空只为寻一人的转世。\n\n到了异世，他因记忆受损忘了那人的样貌，只记得他叫“阿yu”。\n\n·\n\n末世前一周，南昱“好心”救了一个人。\n\n再次见面，那人竟想和他“套近乎”，叫他“阿昱”。\n\n他一脸高冷回怼：“我们不熟，请叫我南昱。”\n\n·\n\n后来，南昱一脸委屈，“阿砚，你为什么不叫我阿昱？”\n\n文砚乐了，悠悠吐出一句，“我叫过，是你拒绝了。”\n\n·\n\n副cp：\n\n又凶又痞嘴欠攻vs社牛心大直男受\n\n正直负责年下攻vs傲娇嘴毒御姐受\n\n爱不自知医生攻vs高武力低智力受\n\n笑面狐狸年上攻vs直不自知年下受\n\n一见钟情逗比攻vs装丑装乖漂亮受",
