    "author": "破啊",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/f98e9a7dde33b82008a8d77f1bc15e80~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358570&x-signature=N7MsJgFeI08Gz%2BFDBHiL8SPgh2c%3D",
    "score": "9.4",
    "category": "双男主",
    "abstract": "【机智毒舌冷脸萌天然呆受VS闷骚男鬼白切黑重生攻】\n\n【双男主+双强双洁+ABO+星际+先婚后爱+甜宠+养成+主受】\n\n散修季昭千辛万苦苟到渡劫，却被天雷所灭，成了星际顾家那万人嫌的小可怜……\n\n假少爷被父母兄长关怀备至，他却在家中受尽白眼？\n\n季昭：为了大家都有美好的未来，你们就当我死了吧\n\n实战队友故意孤立，虫族在后穷追不舍？\n\n季昭：剑气纵横三万里，一剑光寒十九州！\n\n众人嘲他全家AO，他这破Beta不如死了算了\n\n季昭：谢邀，人在荒星，突变Omega，有点慌\n\n陆曜，帝国最年轻的3S上将。\n\n与虫族一战舍身重创虫皇，精神海却濒临崩溃，再也无法驾驶机甲。\n\n未婚妻决然退婚，追捧者翻脸相向。\n\n有人说他因此性情大改，连精神体巨狼都变得弑杀残忍。\n\n对此，季昭推了推某只一直拿头蹭他，还嗷呜舔他手心的巨狼。\n\n“啊？它吗？”\n\n直到大战再次爆发，季昭以顶级治愈系Omega身份扭转战局，全帝国都沸腾了。\n\n眼看请他做治疗师的人排起长队，季昭却被高大强势又缠人的男鬼Alpha抵在墙角，叼着白皙脖颈低声诱哄道：\n\n“昭昭，你是谁的？”\n\n季昭呜咽：\n\n“你的。”",
