    "score": "9.0",
    "category": "双男主",
    "abstract": "【双男＋强强+哨向+he】刚开分所以分数低\n\n顶级木系异能者从末世穿到了星际元。\n\n1\n\n卫沐阳就这么静静的看着，身体里的异能运转。\n\n他的精神体跳出来，坐在桌子前，在巨狼冲过来的时候，一个起跃跳到了它的鼻尖上。\n\n“阿欧！”\n\n使劲咬了一口。\n\n赵谦忍不住冷笑，一个B级向导，对他的伤害几乎是微不可察：“你这精神体是来卖萌的吗？你……”\n\n下面嘲讽的话再也说不出来，因为他发现自己精神力像是被捅了一个大窟窿，疯狂的从巨狼鼻头上的洞往外倾泻。\n\n他控制不住！！\n\n赵谦的脸色有些白，惊恐的看着卫沐阳：“你做了什么？”\n\n卫沐阳：“做你大爷。”\n\n二\n\n褚铮昊进来提着老虎的后脖颈就走了，只是冷冷看了他一眼，一句话都没留，看着格外的不好惹。\n\n卫沐阳一脸莫名其妙的关上了门。\n\n褚铮昊捏着老虎的耳朵：“不许你再靠近他。”\n\n老虎别过头，一声不吭。\n\n褚铮昊：“他有可能是别的星球送来的奸细。”\n\n老虎翻了个身，屁股对着他。\n\n褚铮昊：“我们要保持冷静多观察观察，他不可能不知道你和我的联系，他那么摸你，就是为了勾引我，你明白？”\n\n老虎跳下桌子，朝着红彤彤的苹果张嘴就要咬上去。\n\n下一秒，被强制收回。\n\n褚铮昊：好险，差一点，我老婆给的我还没吃",
