    "abstract": "(双男主)……大灾变时代，三世界大融合，只有治疗技能的蓝星人类只能依靠召唤已经沦陷的灵界幻灵协同作战抵御魔兽入侵，苦苦支撑着守护为数不多的主城净土生存空间。\n\n独孤怀获得了名为云.御的强力幻灵，却因为幻灵资质太高，晋级所需材料极少而被人盯上，惨遭青梅出卖，被蹲守复活点，最后同幻灵一起死亡。\n\n重生到一切开始前，独孤怀发誓这一世要保护云.御和老爹，让伤害他们的人付出代价！\n\n（听书的宝子请选择真人讲书版本，其中第二集到第五集设定界面请跳过）",
