    "book_name": "废土基建：半瓶水买下战力天花板",
    "author": "该用户正在码字",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/291cd21d3522778464c0ea72a8953e3e~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358572&x-signature=RXx6iDbIK4KE%2B2zpP5gj%2Fx%2FjTaU%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "末日废土，双男主，1v1，非主流种田基建美食（伪）文\n\n怂批腹黑资本家受vs忠犬保镖疯狗攻（受穿越，攻重生）\n\n乔澈一睁眼穿越到废土末世，幸好绑定【领主模拟器面板】！\n\n放置核心石，解锁一平米安全区！\n\n【叮！净化土壤一平米，种下变异西瓜种子】\n\n【叮！收集废铁一百斤，合成全自动空气制水机】\n\n外面的幸存者为了半块干巴面包大打出手，乔澈躺在地下基地的沙发上，吹着空调，吃着冰镇西瓜，愁着今天的烤肉怎么吃不完。\n\n重生归来的废土杀神江夜，带着毁灭世界的恨意从地狱爬回，却在不起眼的沙丘，被一个铁皮屋屋主救了回去，他原本想杀人夺宝，却被一句奴役的话怼了回来。\n\n“喝了我的水，就是我的人了！员工管饭。”\n\n从此，令人胆寒的杀神，成了乔领主的专属头号打工仔。",
    "word_number": "724796",
    "chapter_count": 236,
    "last_chapter_title": "第237章 乔澈：真是想屁吃！",
    "creation_status": "连载中 (Đang ra)",
