    "score": "7.5",
    "category": "科幻末世",
    "abstract": "【双男主+废土拾荒+日常+冒险+天灾人祸】\n\n刚出来的评分，别在意，偏群像，主角有家人，家人不是累赘，一起成长\n\n废土出生的杨忍因为发烧意外觉醒了属于末世的上辈子记忆，随着记忆的回归，上辈子的木系异能也跟着回来了，利用记忆和异能，他带着家人一起奋斗，在混乱的废土有了一席之地。只是他以为就那么大的世界，当一步步向上后，才发现自己竟然是井底之蛙。",
