    "author": "林安庭",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic-r/c35166f7df9e09aa4089fb81696634d0~tplv-shrink:1200:0.image?lk3s=64477e16&x-expires=1795358572&x-signature=UIj2RW64R3SURFtoVPKY4Pcj1Ww%3D",
    "score": "8.4",
    "category": "双男主",
    "abstract": "【ABOE/末世/基建/废土/轻松向】\n\n【受】脑回路清奇跳脱乐观怪物受｜人前柔弱人后超强怪物受\n\n【攻】道高一尺魔高一丈基地最强人类执法官攻｜偏执腹黑恶劣邪恶……冷酷一体攻\n\nS级校霸alpha江川穿越了\n\n穿成头长犄角、拖着尾巴的怪物\n\n开局饿疯了对着执法官傅渊流口水\n\n结果被当场反压带走\n\n为了活命，他装弱卖惨\n\n成了基地众所周知的“执法官配偶”\n\n人前：嘤嘤嘤人家好怕\n\n人后：一脚一个怪物\n\n顺便用特殊能力把基地的荒土种满了粮\n\n——我在废土搞基建，把这里建成最强基地\n\n偏执执法官早看穿了他的伪装，却不说破\n\n因为这只小怪物\n\n能安抚他失控的信息素\n\n小剧场：\n\n江川：“你演我？”\n\n傅渊捏住他后颈：“宝宝演技真好。”\n\n江川：“……”\n\n傅渊：“晚上回屋慢慢‘对戏’。”",
