    "category": "双男主",
    "abstract": "【双男主+双强+末世天灾求生+宠物+异生物图谱】\n\n天灾末世，各种灾难接踵而至，山河倒转，星辰陷落。\n\n各种奇奇怪怪的变异生物自未知的地方走来，人类陷入食物链最底端。\n\n长着鱼尾的蜘蛛，百米长的巨兽，刺球一样的兔子，巴掌大的蚂蚁，绿色的老鼠……\n\n世界仿佛被重新打乱排序般，一切的一切，仿佛都不再一样了！\n\n节选:\n\n莫鱼:“你帮我救人，我答应你一个要求！”\n\n秦离:“人我救了，让我想想让你做什么好呢~穿女装？”\n\n莫鱼:“……不行！”\n\n秦离:“不愿意啊，那能让你干嘛？要不、跟我混~”\n\n莫鱼:“……好！”\n\n王八那只鳖:“跟谁混呢？你们都得跟我混！”\n\n【避雷:\n\n双男主，无金手指无空间无丧尸，异种生物出没，讲的是各种天灾后，两人一起与异种生物抗争寻求未来的故事！\n\n异种生物为变异物种，与现实生物有差距！】",
