    "abstract": "【双男主+双向暗恋+校园+甜文+双洁+年下】\n\n（真人有声改编）\n\n狼犬年下体育直男攻x对外清冷对内温柔钓系受\n\n秦景宁藏了一个秘密，他喜欢上了失而复得的好兄弟兼舍友。\n\n他可能是弯了，而且没救了。\n\n但秦景宁觉得，号称钢铁直男，拒绝一切死gay靠近的好兄弟最近也不太对劲。\n\n·\n\n霍鸣发现，最近好兄弟秦景宁好像在暗恋隔壁系花，为此日夜心神不宁，还刻意冷落自己。\n\n可怜的直男霍鸣，打游戏时怀中抱不到好兄弟，吃饭一个人走，打球没兄弟送水，万分不习惯。\n\n为了让秦景宁老实交待，霍鸣做出以下一系列手段——\n\n亲手做浪漫烛光晚餐，把烛光当审讯灯，步步试探：“秦景宁，听说隔壁系系花最近和你走得挺近？”\n\n秦景宁：“她有对象。”\n\n把人拐上摩天轮，在最高点强势壁咚：“挖人墙角更不对了，你喜欢谁都不能喜欢她！”\n\n秦景宁沉默：“你知道就好。”\n\n为了守护好兄弟的道德底线，睡觉都黏在秦景宁身边：“今晚我睡外边搂着你，以防你借半夜上厕所去偷偷挖墙脚。”\n\n秦景宁：“……”\n\n直到一天霍鸣发现，他兄弟竟就是多年前救他狗命的“梦中女神”。\n\n而且暗恋对象不是别人，是他。\n\n秦景宁要搬走，霍鸣疯了。\n\n——\n\n秦景宁：兄弟，我只是搬宿舍，占有欲能不",
