    "abstract": "（已完结）【双男主+大学校园+救赎+学霸+甜宠+双洁1v1+he】\n\n大学开学前，姜屿辞第一次遇到温遇，是在酒吧。\n\n那时温遇在酒吧打工，遇到傻逼，遭人欺负。\n\n姜屿辞不是个爱管闲事的人，但在看到温遇红红的眼角时，他承认，心动了。\n\n于是别人英雄救美，他英雄救帅哥。\n\n后来，姜屿辞再遇到温遇，是在大学宿舍里。\n\n看着连着几次出现在自己梦里的人，姜屿辞觉得，自己该学学怎么追人了。\n\n*\n\n温遇从小被虐待长大，每一次回家，身上都要多出几道伤来。\n\n总之，没人疼没人爱。\n\n直到后来，他遇到了一个会在他无处可去时把他带回家的人，叫姜屿辞。\n\n温遇不明白姜屿辞为什么对他这么好，直到他看到了姜屿辞的笔记本。\n\n一整页，写满了他的名字。\n\n“我也说不清为什么会这么爱你，我就是莫名地会被你吸引，如果非要解释，那可能因为我是注定会爱上你的人。”\n\n“我好像被你锁住了，”姜屿辞轻轻握住温遇的手，目光温柔又坚定，“链子的另一头，你会松开吗？”",
