    "abstract": "【双男主】【大学校园】【双洁】\n\n【小心眼的作精傲娇少爷攻*超绝钝感力的坚韧漂亮直男受】\n\n被室友表白了怎么办？\n\n拒绝！\n\n拒绝后被强制爱了怎么办？\n\n算了，那就谈呗。\n\n白棠，一个纯正的直男，好不容易从小山村考入大城市，却没想到，城里人玩的真花啊，连男的都可以找男的谈恋爱了，怪不得他那个室友看他的眼神越来越不对劲，糟糕！\n\n强制爱\n\n✘\n\n谈恋爱\n\n✔\n\n——\n\n前期\n\n老婆伺候我\n\n后期\n\n上赶着伺候老婆",
