    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o13ba9c87ee8acf793d4d2d10740afa67~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358573&x-signature=Ax6fq1VChlMJQ4pgzqhUPggnKvg%3D",
    "score": "8.2",
    "category": "双男主",
    "abstract": "【双男主＋校园＋1v1＋双视角＋群像＋he】\n\n（简介无能，请看正文）\n\n“他就是江昭？他爷爷因为他去世了，他怎么不哭？”\n\n“江昭，你就是个害人精，都是因为你我没有爷爷奶奶了！”\n\n“呜呜呜～都怪我，不是小昭的错，是我，是我，呜呜呜～”\n\n“你没错阿瑶，谁知道那个孩子会说谎。”\n\n“阿星，阿月，阿阳，是这世上最亲的兄妹。”\n\n江昭：他们都有最爱他们的人，唯独我没有\n\n你们都说我冷心冷情，那我就做给你们看，我江昭不爱你们任何人！\n\n“江昭昭”“江小朋友”“江傲娇”“江别扭”\n\n“江昭，你既握住了我的手，这辈子你若放开，我们此生决不相见！”\n\n顾翎野对于江昭是太阳，是最璀璨的光\n\n江昭对于顾翎野是浮萍的根，是他心中的港湾\n\n这是一个在最好的年纪遇到最爱的人的故事。",
