    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/358dae69b8001ca20a6721daf4e9f718~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358573&x-signature=VfSebTZT3pYQ4xYUiAoMp6z4KNQ%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "（已完结）【双男主+日常+温馨+甜宠+校园+双洁+双向奔赴】\n\n主：夏辞 唐纪舟\n\n懵懂直率清爽受*气质矜冷美人攻\n\n甜宠！甜宠！甜宠！\n\n受只在攻面前会乖软撒娇，攻只对受温柔。\n\n夏辞的喜欢，纯粹又贪婪，羞怯又大胆。\n\n唐纪舟的喜欢，隐忍又热烈，温柔又霸道。\n\n*\n\n夏辞曾经护了个阴郁怕生的同学，他忘了。\n\n后来在图书馆重逢，同学摇身一变高冷帅哥，夏辞以为是初遇。\n\n再来大学两人成为室友，夏辞以为是重逢，其实是对方费尽心思的接近。\n\n干部竞选的新生班会上，夏辞说：“我们是高中同学。”\n\n唐纪舟：“也是初中同学。”\n\n别人眼中的唐纪舟：寒山远调，生人勿近，不苟言笑，冷血贵族……\n\n夏辞眼中的唐纪舟：他好帅，他好美，他好温柔，他好好哦，他是睡美人，他笑起来很好看……\n\n群众：确定说的是同一个人？？？？\n\n别人眼中的夏辞：爽朗阳光，帅气逼人，可酷可爱……\n\n唐纪舟眼中的夏辞：老婆，宝贝，我的。",
