    "author": "肖月亮",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o4b6845668f2059dec56a3ad91d51e694~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358573&x-signature=9LsZRCkzlj3eoIT4DlG996GiI4I%3D",
    "score": "9.0",
    "category": "双男主",
    "abstract": "[双男主+死对头文学」开局即睡+日久生情]\n\n[阳光开朗社交达人受vs冷漠醋缸高岭之花攻]\n\n-\n\n沈凛，一个七分运气考入A大的幸运儿。\n\n本以为即将开启美好的大学生涯，\n\n谁知，第二天他醒来的时候，发现身边躺着的是从高中就不对付的——林叙白。\n\n沈凛懊悔丛生。\n\n现在退学还来得及吗？\n\n-\n\n周围人人皆知他们是死对头，纷纷押注第几天能打起来。\n\n然而隔壁寝室的同学盼啊盼，盼来了他们牵手出入。\n\n咦？这个发展不太对哦。\n\n-\n\n刚搬进宿舍，林叙白并不知道自己的室友是谁。\n\n等到晚上熄灯，浑身酒气的人爬上了他的床。\n\n有洁癖的他本想把人踹下去，却在月光照进来的那一刻，看清了室友的脸。\n\n沈凛不知道喝了多少，掀开被子呼呼大睡。\n\n林叙白停下了踹人的脚，把人搂紧。\n\n黑暗中，他看着醉意的脸庞，满眼深沉的占有欲，\n\n“这可是你自己送上门来的。”\n\n攻：林叙白\n\n受：沈凛",
