    "book_id": "7627824468458474521",
    "book_name": "渡你盛夏时",
    "author": "诗孓",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o1151f74c3a98244f929e52046920686c~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358573&x-signature=zWfQxcHMJ2gWT%2Fsunpju%2B5%2FTBUk%3D",
    "score": "0",
    "category": "双男主",
    "abstract": "【双男主+校园+救赎+破镜重圆+HE】\n\n【敏感暴躁带刺受 × 温柔闷骚心机攻】\n\n五年前离散，五年后再见，顾祁撞了秦穆一个满怀。\n\n秦穆愣住了，连掉落的试卷都忘记了捡，“顾祁？”\n\n顾祁浑身不自在，皱着眉头。五年不见，形同陌路。\n\n“你……不记得我了？”\n\n“没有。”\n\n后来毕业季的假期，两个少年窝在沙发上。\n\n“顾祁，亲我一下好不好。”秦穆引诱着顾祁，看着人在他怀里，耳尖红得能滴血。\n\n“嗯……”\n\n没想到分离总是在盛夏——\n\n“秦穆！你接电话啊！！”\n\n“不要我了，至少告诉我，我也不会纠缠的…”\n\n顾祁满脸泪痕，一个人跪坐在飞机场的地板上低吼。\n\n秦穆我恨你——\n\n转眼间七年过去，研究生毕业的顾祁，跟着导师参加一个国内合作项目，他不经意扫了眼合同，合作人：秦穆。\n\n“这次，还要离开吗？”\n\n“离开，但是我要你陪。”顾祁扯住秦穆的衣领，吻上他的嘴角。\n\n这次，他们都不放手。\n\n从前，我要你回来这里，我在等你。\n\n往后，隔山跨海我陪你，你等着我。\n\n（秦穆内心OS：有点心机都使给顾小朋友了）",
