    "score": "8.6",
    "category": "双男主",
    "abstract": "【双男主+拉扯+直掰弯+校园1V1】\n\n林亦安有一个打死不能让人知道的秘密：他喜欢自己的发小闫宁。\n\n那天，闫宁的室友宋聿珩对他说了一句话。\n\n“闫宁把你当朋友，你呢？”\n\n林亦安后背发凉——他知道了。\n\n为了不让宋聿珩说出去，他决定先发制人：用小号假扮女生，拿到他撩骚的把柄。\n\n到时候他要是敢说出秘密，林亦安就把聊天记录甩他脸上。\n\n证据攒够，准备摊牌。\n\n结果发现，宋聿珩根本不知道他喜欢闫宁。\n\n林亦安：？？？\n\n哦莫？玩大了！",
