    "abstract": "你像一束光，坠入我的孤岛。\n\n【双男主+校园文+治愈系日常+HE】\n\n温柔（前期带病）攻×孤僻乖张受\n\n—\n\n景冬十多年来都在灰暗中度过。\n\n旁人都怕他，都对他避之不及。\n\n不过没关系，反正他不在乎。\n\n他我行我素，对所有人都很冷淡。\n\n直到高二那年分班，季洛成了他的新同桌。\n\n从此，他的世界中有了另一个人。\n\n他独自消化情绪时，那个人会蹲在他面前帮他擦眼泪。\n\n“乖一点，不哭了，好不好？”\n\n—\n\n细水长流小甜饼，欢迎食用◍•ᴗ•◍",
