    "abstract": "【双男主+都市+豪门+年龄差+萌宝+家长里短+HE】\n\n六年前的短暂相处后，焦阳与豪门大佬霍琛再无交集。直到六年后的某天，恒正国际酒店的浴室里，这场沉寂已久的缘分骤然重启……\n\n此时的焦阳是个带着孩子在生活里摸爬滚打的单亲爸爸，十八岁便扛起家庭重担的岁月不但没磨灭他眼里的光，反而让他养出了一身的韧劲儿。而霍琛始终站在金字塔的顶端，手握商业帝国，是人人敬仰的商业巨鳄。\n\n云端之上的豪门大佬碰上市井里摸爬滚打的平民百姓，一场身份悬殊的恋爱自此拉开序幕……",
