    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/5e4e3f822476bd9cdc3deb107f65be18~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358575&x-signature=Vw0wYoXCDR2DHkXuW%2Fr%2Fqr8Ew%2Bo%3D",
    "score": "8.9",
    "category": "双男主",
    "abstract": "完结。老房子着火。【32岁深柜总裁X19岁底层少年】【甜宠+撬墙角+年上攻+双向奔赴+微现实向+双不洁】有副CP，副CP（年上+双洁）集中在番外\n\n已过而立之年的蒙奕事业有成，是个深柜，遇见了在底层挣扎也热情阳光的叶燃。有男朋友？抢过来他就是男朋友。偷看一百四十天的老男人决定主动出击。\n\n以为会和竹马过一辈子的叶燃惨遭背叛，体贴又温柔的大叔让他迅速沦陷。但努力上进换不来外界对他们恋爱的祝福，巨大的身份地位差摆在面前，只有指指点点和嘲笑。\n\n“我们分手吧，我不想成为你的污点。”叶燃红了眼眶。\n\n蒙奕握着他的手，在朋友圈官宣，“现在，你是我的闪光点。”\n\n【爱是陪伴与成长】",
