    "score": "9.4",
    "category": "双男主",
    "abstract": "【温柔钓系受VS高冷真香攻】\n\n【双男主+先婚后爱+双洁+土甜文学】\n\n两年前的一次意外，祝书黎和心悦六年的闻时琛领了证，所有人都说闻时琛不爱他，都在唱衰这场婚姻。\n\n祝书黎却一笑而过，他野心不大，想要的不多，闻时琛的身和心而已。\n\n闻时琛初识祝书黎那会，就看出祝书黎是个很有社交手段的人，不过在他眼里还是不够看，也不觉得祝书黎的小手段敢卖弄到他面前。\n\n起初，闻时琛对这场没有感情的婚姻不以为意，对祝书黎也是如此，后来，他在深夜里拧眉沉思，“老婆最近怎么对我这么冷淡了？”",
