    "author": "莫流云",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2of2b354f8c2ad70aa3d49ba38ab2a6cc0~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358575&x-signature=Ful36yWzQRz1c%2FK%2B1GjOmUh7Ih0%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男+重生+甜宠+爹系攻！】\n\n于恒在看电影途中遇到一个奇怪的大叔，大叔提出要包养三无青年小于——无车、无房、无存款。\n\n正常人应该给对方一巴掌然后转身离开，小于不一样，他同意了。\n\n纪经年像是三月一场细雨，压住了于恒心中的风沙，滋润干涸的心田。\n\n于恒以为这一场爱恋是初遇，于纪经年却是他撕心裂肺求来的重逢。\n\n～～～\n\n欢迎大家去看我的新书《暗污》哦～\n\n非双洁，弃文不用告诉我哦～",
