    "abstract": "【双男主+极限拉扯+双向奔赴】\n\n由于一场官司，晏淮引起了大名鼎鼎的傅董事长的注意，两人各怀鬼胎的成为合作情人关系，在一场充满了欺骗与试探的较量里不断追逐，彼此的秘密一点点被揭开，血淋淋的感情也就此滋生……\n\n（ps：是利己主义、商人作风、执着略偏执冷血的攻\n\nand\n\n性情冷淡、脑子身手双在线、做事干净利落的受）",
