    "book_id": "7343990444449090622",
    "book_name": "京圈大佬手段高，小少爷步步被撩",
    "author": "酒心小面包",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/de90862ad3d4d78cb4f14615ddd1c73a~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358575&x-signature=EueljtNxJPz6pGgKfJUji8dO3nI%3D",
    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+甜宠双洁+救赎+假戏真做+攻蓄谋已久，暗恋成真】\n\n回家三年，沈以南事事谨慎小心，却因一次醉酒招惹了京圈有名的太子爷。\n\n事情本就荒谬，对方开口更是让人震惊：“你会对我负责吧？”\n\n沈以南连忙颤巍巍保证尽所能满足。\n\n温柔的目光落在他脸上，太子爷缓缓说：“家里催婚紧，缺个男友应付。”\n\n二人签下“契约情侣”合约，半年为期。\n\n本以为互取所需，却不想一场蓄谋已久的密谋。\n\n*\n\n合约第一天，太子爷把他带回家贴贴；\n\n合约第二天，礼物鲜花资源任选；\n\n合约第三天，公主抱接下班，摸着他的头说好乖……\n\n沈以南：是不是有哪里不对劲？\n\n*\n\n后来，商界只手遮天的京圈太子自曝有男友。\n\n谁都没有联想过沈家不受宠的真少爷。\n\n直到那天有人亲眼撞见——\n\n光线昏暗的包间里，高大身躯将少年紧紧锢在怀中，声线低哑：\n\n“宝宝，别对别人笑，我会吃醋。”\n\n*\n\n乖巧小可怜受x温柔宠溺钓系攻",
