    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+身份差+引导型年上】\n\n书名：走入你的雨季\n\n年上引导型大佬攻vs清醒独立演员受\n\n1V1双洁\n\n娱乐圈最近很热闹，一个陌生的名字突然空降热搜，自此就成了热搜常驻嘉宾。\n\n各种黑料屠榜，这人依然活跃在各个剧组片场。\n\n有人说，他背后的金主是黑白道通吃的京城叶家二少爷\n\n有人说，他备受宁城世家聂家小少爷的宠爱\n\n有人说，都不对，他跟同是明星的乔小少爷才是一对\n\n......\n\n每每有这样的热搜屠榜，林听都要被某位大佬修理一顿。\n\n他和闻远棠的开始，缘于一场意外。\n\n闻远棠对林听的执着，缘于林听从童年下到成年的一场雨，少年的雨季不仅困住了他本人，也困住了旁观的闻远棠。\n\n闻远棠接二连三路过那场雨后，他决定，如果林听是一只迎风飞舞的风筝，那么，尽头的线必须牢牢地握在他手里。\n\n如果林听是一只胆小却只想自由的麻雀，他只需要将笼子做得足够大就可以。\n\n他说，逃避解决不了问题，但你可以把问题交给我。\n\n他说，人终其一生都在筛选，有人会离开，有人会一直在。\n\n轨迹的终点，其实从相遇起点就已经注定。",
