    "score": "8.7",
    "category": "双男主",
    "abstract": "【双男主/正文已完结】\n\n沪圈顾家和京圈苏家的联姻是整个商界关注的。\n\n顾璟旭从来不认为他的地位需要联姻来稳固。\n\n直到自己的弟弟被当作联姻的工具。\n\n“哥哥替你。”\n\n顾璟旭主动放弃继承权和京圈的那位同样不受宠的少爷联姻。\n\n却没想到，对方竟然是京圈的太子。\n\n“京圈太子，也需要联姻？”\n\n顾璟旭坐在谈判桌上，看着对面衣冠楚楚的男人。\n\n苏晏之挑眉，盯着顾璟旭看：“沪圈的太子，也需要联姻？”\n\n顾璟旭冷淡垂眸：“家弟太小，不适合你。”\n\n苏晏之歪头一笑：“嗯，所以我们绝配。”\n\n小剧场：\n\n“苏晏之，你真要结婚？对方是男人。你的家族在坑你，看不出来吗？”\n\n“看出来了，但和我结婚的，我很满意。”",
