    "author": "你的小菠萝",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/aa46b39bfe75e5ff4749586c83e923d5~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358576&x-signature=LGBEDW7QrdZSBClHfT2OOui%2FwSs%3D",
    "score": "8.6",
    "category": "双男主",
    "abstract": "评分低是因为刚开分。\n\n【双男主+豪门娱乐圈+买买买+打脸+甜宠1v1】\n\n夏眠，平平无奇首富之子，穿成了狗血文里的炮灰真少爷。\n\n被假少爷夺走亲生父母不说，连银行卡都只剩下可怜的五十万。\n\n夏眠：我过不了苦日子呀TT\n\n穿过来时，原主正在破坏主角攻受的订婚宴。\n\n听说主角攻是京城周家的长孙，夏眠眼前一亮。\n\n越过他，看向主位上主角攻的三叔——周家家主周凭川：“听说三爷尚未婚配，您看，我怎么样？”\n\n————\n\n周凭川冷漠狠辣名声在外，旁人不敢直呼其名讳，都尊称一声“三爷”。\n\n抵不住家里催促，三爷为自己选了个叫夏眠的个小朋友。\n\n商讨婚姻事宜那天，小朋友眼尾上扬：“我呢，有一点小小的条件。我家这边的习俗是递聘书、过礼、典礼，这三个环节缺一不可，总要风风光光的，才不至于折了您的面子。然后呢，我没什么特别的爱好，平时就喜欢乘私人飞机出国看看秀、做做高定，和朋友一起度度假、逛逛拍卖会......”\n\n还真是“小小”的条件。\n\n不过周凭川不在意，在他这里，最廉价的恰恰就是金钱。\n\n————\n\n参加一档慢生活类综艺时，嘉宾们都以为夏眠和他爱人过着普普通通的日子。\n\n直到他家占地一条街的豪宅，和800平衣帽间出现在镜头之中…",
