    "author": "千Allure",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2offf8ab76613effe9b1fa7168b4e78ef2~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358576&x-signature=aik4dB%2FUN6LtMPiaqjl03OXcL%2F4%3D",
    "score": "9.5",
    "category": "双男主",
    "abstract": "【已完结 真人有声书已上线】\n\n【双男主+双洁+豪门太子爷】\n\n【绿茶嘴毒攻×清冷美人受】\n\n沈褚辞第一次见到谢遇桉是在酒吧。\n\n身边的狐朋狗友正在喝酒吹牛，不知怎的就提起了谢家那个一头银发及腰的谢大少，话题还没聊多久，主人公就带着三十多个保镖将酒吧一齐围了起来。\n\n忽明忽暗的灯光下，沈褚辞一眼就对上了那双清冷绝情的眼眸，等到谢遇桉走近，他才发现，一直被人说是颜狗而言辞义正纠正的他，原来就是一只颜狗……\n\n长着一张天人共愤的绝美容颜的沈老狗，此刻心里嗷呜嗷呜的嚎：怎么会有人的颜值刚好长在自己的心巴上啊！！\n\n于是他理了理衣领，优雅的走上前，朝银发美人伸出手，语调深情：“你好老婆，结婚。”\n\n谢遇桉：？\n\n谁家好人一上来就直奔结婚的？！！\n\n但……谢遇桉是个资深颜狗，看着面前妖孽般的沈少爷，他可耻地心动了。\n\n几秒后，银发美人伸出手，瓷白如玉的手握上那只伸过来的大手，脸上波澜不惊道：“好啊。”\n\n沈褚辞：！！！老婆答应我了！！！",
