    "book_id": "7636652496349318168",
    "book_name": "逃不掉！穿成财阀继承人的白月光",
    "author": "格桑兔",
    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2ob188c09021fd444e90b50838c5b4e021~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358576&x-signature=7qD1ZYwXnU9daXfxEYXrmBapbaw%3D",
    "score": "8.7",
    "category": "双男主",
    "abstract": "【傲慢克制真天龙人攻x骄纵没心肝不吃压力受】\n\n时雾穿成了男主名义上的白月光。\n\n男主湛薄倾，湛家长子，表面谦逊绅士，骨子里却傲慢刻薄，做事狠辣。\n\n书里时雾为了提升自家暴发户的地位接近湛薄倾，中间因身体原因出国调理，回国后依旧死缠烂打。\n\n最后给湛薄倾下药被发现，导致家破人亡。\n\n时雾穿过来时刚好赶上圈里人在酒吧开party。\n\n好消息：如今的时雾刚回国，还没有开始死缠烂打，远离男主就可保平安。\n\n坏消息：他们刚好在玩国王游戏，梅花5和黑桃King要当众热吻五分钟。\n\n时雾握紧梅花五，看着湛薄倾手里的黑桃King眼前一黑。\n\n“......”\n\n你爹！\n\n-\n\n圈里人都以为湛薄倾爱惨了这位白月光。\n\n只有湛薄倾的好友知道这白月光的名头是时雾故意乱传的。\n\n说爱谈不上，恨倒有不少。\n\n时雾朋友担忧。\n\n“你顶着湛薄倾白月光的名号乱晃，得惹多少人妒忌？”\n\n时雾不解：“表面上我可是湛薄倾的爱而不得！论地位比湛薄倾还高上一头，谁敢动我？”\n\n说完沾沾自喜。\n\n朋友：“？”\n\n你是这么理解的吗？\n\n-\n\n时雾为了保命，刻意和湛薄倾划清界限。\n\n没多久却有流言蜚语传了出来。\n\n传闻那位继承人眼睛猩红把白月光按在怀里亲，还喝下了白月光下药的酒。\n\n白月光毫无还手之力，只能任人为所欲为。",
