    "score": "9.1",
    "category": "双男主",
    "abstract": "【双男主，甜宠，重生，高甜爽，娱乐圈，团宠】\n\n宠妻忠犬总裁攻×团宠绿茶作精受\n\n——\n\n前世被渣男利用，害死父母和四个哥哥，临死才知道自己曾经不屑一顾的霍爷为了自己可以抛下一切。\n\n某老神仙发言：“我可以帮你。”\n\n于是，重来一世，陆知川选择抱紧霍爷大腿！哄老攻什么的，他最在行了！\n\n陆知川一边闯荡娱乐圈完成老神仙的任务，一边报复渣男，抽空还要和霍景渊培养感情……\n\n眼看着四个哥哥争风吃醋，陆知川赶忙叫停。\n\n“你们能不能别对景渊哥哥这样！”\n\n霸道总裁陆大哥：“这种事小宝你不懂”\n\n权势大佬陆二哥：“小宝你往后退，我先跟他打一架！”\n\n高冷影帝陆三哥：“小宝不是一直想进娱乐圈？哥带你闯荡娱乐圈，离那个男的远点！”\n\n大学教授陆四哥：“小宝回来学习，情情爱爱的以后再说！”\n\n霍某渊：“大舅哥这是哪里话？”",
