    "score": "9.2",
    "category": "双男主",
    "abstract": "评分刚开，后期会涨\n\n宠溺大佬攻VS装乖美人受\n\n双男主+双洁+豪门总裁+甜蜜拉扯+土甜文学\n\n外界传闻华盛董事长顾言峥不喜欢女人，所以秘书都要招男的。\n\n顾言峥看着站在自己面前笑得明媚无害的小秘书时越却并不满意。\n\n因为几天前，小秘书拦住他，自荐枕席问他需不需要情人。\n\n*\n\n顾言峥本不想留下这个对自己别有用心的人，奈何小秘书嘴甜爱笑办事还牢靠。\n\n本以为接近自己是为了进一步勾引，没想到小秘书一心扑在工作上只想打工赚钱。\n\n*\n\n不知不觉沦陷的高冷董事长头痒开始长恋爱脑。\n\n小秘书为了还债四处兼职，董事长暗中铺桥搭路想方设法往他兜里塞钱。\n\n*\n\n直到某天董事长亲耳听到乖巧听话的小秘书想要跳槽。\n\n他急了，将人拖回房间按在墙上质问：“不是想做我的情人？”\n\n小秘书压下心中不甘问：“给您当情人需要做什么？”\n\n董事长托起小秘书的下巴：“取悦我。”",
    "word_number": "210612",
