    "thumb_url": "https://p3-reading-sign.fqnovelpic.com/novel-pic/p2o59c5dfe06b51e02b607901aba9e2b6bb~tplv-snk2bdmkp8-superreso-double-rz:1200:0.image?lk3s=64477e16&x-expires=1795358576&x-signature=Se7h1Row2nBH6RrtoeNr7GrkHeA%3D",
    "score": "9.2",
    "category": "双男主",
    "abstract": "【港风+双男主+双洁he+万人迷受+豪门商战】\n\n裴锡年是连饭都快吃不起的贫困生，却凭实力被港城地产大王看中，和他做了个交易。\n\n对方资助他完成学业，完成他的心愿。\n\n他伪装成地产大王的私生子，作为鲶鱼效应中的鲶鱼，让对方那个天生反骨的儿子裴映珩产生危机感，乖乖回家继承万亿家产。\n\n交易很艰难，初次见面，他就被反骨仔骂了一顿。好在他能力出众，不到一年时间，就爬到了地产大王的集团决策层。\n\n反骨仔危机感暴增，真的被他逼的回去继承家产了，就在他打算功成身退时...\n\n---\n\n反骨仔裴映珩有个秘密。\n\n和裴锡年初见那天，他看到了弹幕。上面秘密麻麻全是剧透，那是平行时空里，他和裴锡年未来的人生经历。\n\n他知道裴锡年是个假货，知道裴锡年和他爸的全部计划，但他的危机感不减反增。\n\n他要改变裴锡年的结局。\n\n他要...\n\n裴锡年抓住他不安分的手，忍无可忍的瞪了他一眼。\n\n裴映珩点点头：好，那回家再说。\n\n裴锡年：？？？我是这个意思？\n\n很多年后，圈内人都在回忆，港城金字塔顶端的裴生是何时从飞扬跋扈的肆意少年变妻奴的。\n\n思来想去，大家一致认为，这个转变是从那个大陆来的私生子回港那天开始的。",
