    "score": "9.6",
    "category": "双男主",
    "abstract": "【双男主，1v1，双洁双强】\n\n【冰冷厌世毒舌美人佣兵大佬vs王霸之气爆表纨绔京圈太子爷】\n\n京城豪门沈家私生子沈轻言，看似身娇体软，实则武力值爆表。\n\n出国多年后回归，整个京圈炸了——\n\n“邵家太子爷的白月光回来了？！”\n\n沈轻言打开浏览器，默默输入了白月光三个字。\n\n[白月光：主要指可望而不可即的人或者物，一直在自己心上，却无法留在身边的人。]\n\n沈轻言：“？？？”\n\n拜托，我跟他根本不熟好吗？\n\n于是，狂炫酷霸拽的京圈太子爷开始践行舔狗的108种舔法。\n\n舔狗守则——舔！就硬舔！\n\n邵煜深：身娇体软却能把我脑袋打爆的小哥哥一枚吖~",
