    "score": "9.3",
    "category": "双男主",
    "abstract": "正文已完结【双男主+甜宠+诱撩+暧昧拉扯+双洁+HE】\n\n【宠溺诱撩爱d大佬攻VS双面暴娇少爷受】\n\n司鹿是淮城司家的小少爷，表面乖到不行，实则野的一批！\n\n却一直有个男人对他图谋不轨！\n\n司鹿甩给他个外号——梦中情狗。\n\n某天他哥来了电话，“我带你见个朋友，刚回国的大佬，以后由他照顾你。”\n\n见到大佬后，司鹿惊了！\n\n这不就是那个对他图谋不轨的男人！\n\n大佬转身一变，成了他的金主爸爸。\n\n叶璟深：“宝宝乖，过来。”\n\n司鹿：“别以为老子没脾气，老子是直的！”\n\n整个淮城都知道叶璟深已名草有主，就在所有人猜测是谁能让大佬沦陷时，司鹿在赛车场上以一个漂亮的‘死亡之吻’高调官宣，让整个淮城炸了锅！\n\n当梦中情狗变成了自己老公。\n\n司鹿只能说：“我叫司鹿，我在叶璟深对我诱撩欲捕时，毫无思路......”",
