    "abstract": "【穿书+娱乐圈+爽文男主+甜文】\n\n少爷受虞辞x霸总攻傅斯衡\n\n虞辞穿成书里的十八线糊咖炮灰受，原文里主角受踩着炮灰受成名搞事业，夺走家产，雇凶谋害炮灰受，简直丧尽天良欺人太甚。\n\n于是正义感爆棚的虞辞决定逆袭人生的道路。\n\n主角受装绿茶，他装白莲花。\n\n主角受追主角攻傅斯衡，他搞破坏。\n\n……\n\n没想到却意外捕获主角攻傅斯衡的芳心。\n\n傅斯衡宠他疼他爱他，面对主角攻的追求，虞辞却面露难色，“我是说，就是，你有没有想过咱俩撞型号了？”\n\n傅斯衡瞄了一眼虞辞的小身板，“？”\n\n【阅读指南】\n\n1.受穿书前是攻，穿书后为爱做零！\n\n2.逆袭爽文，一切剧情都为爽负责，介意慎入\n\n3.感情线为主，甜宠\n\n4.没有原型！没有原型！没有原型！\n\n5.双洁1v1，虞辞vs傅斯衡",
