    "abstract": "【双男主+双疯批+HE+钓系VS作精】\n\n腹黑钓系大佬X暴戾骄矜少爷\n\n作为谢家大少爷，谢时一向作天作地高傲无比，直到某日他被霍司按在地上压着揍了一顿。\n\n霍司，京圈中人人畏惧颤抖的疯批大佬，冷血残酷、不近人情。\n\n巧的是，几天后这人就失忆了，谢时满脸核善道：你忘了？你是我的贴身保镖，只对我言听计从、马首是瞻，还爱我爱的死去活来。\n\n霍司：好。\n\n谢时以为一切都在自己的掌控之中，他恶狠狠玩弄这个可怜无助又弱小的失忆人，誓要报当初的一压之仇。\n\n直到后来真相揭晓，原来他才是被玩弄的那一个！\n\n“你的失忆全TM是装出来的！给我滚！”\n\n“发现了？那现在我可以光明正大地囚住你了。”",
