    "score": "9.3",
    "category": "双男主",
    "abstract": "【双男主+双洁+暗恋+甜宠+豪门隐婚】\n\n一开始的青春懵懂变成了匆匆岁月里的默然守护，许舟生气的样子，傲娇的样子，温柔的样子，难过的样子，一举一动都能牵引着他的心……\n\n.\n\n许舟没在身边的六年里，沈延时常在某个角落小心翼翼窥伺着他的笑容。\n\n他是他的目光所及，也是他的心之所向。\n\n.\n\n沈延伸手捏了捏他的脸。\n\n许舟拍开他的手。\n\n“你这毛病得改。”\n\n话音刚落，沈延俯身吻在他脸上，期待的看着他。\n\n“改成亲可以吗？”\n\n【在万般繁华的世界，我以为自己独守着暗恋的秘密，却不知我们互为风景，彼此欣赏】",
